namespace Ds;

use ArrayAccess;
use Countable;
use IteratorAggregate;
use JsonSerializable;
use Traversable;

/**
 * Creates a sequence containing the given values.
 * @template TValue
 * @param iterable<TValue> $values
 * @return Seq<TValue>
 * @since PECL ds 2.0.0
 */
function seq(iterable $values = []): Seq {}

/**
 * Creates a map containing the given values.
 * @template TKey
 * @template TValue
 * @param iterable<TKey, TValue> $values
 * @return Map<TKey, TValue>
 * @since PECL ds 2.0.0
 */
function map(iterable $values = []): Map {}

/**
 * Creates a set containing the given values.
 * @template TValue
 * @param iterable<TValue> $values
 * @return Set<TValue>
 * @since PECL ds 2.0.0
 */
function set(iterable $values = []): Set {}

/**
 * Creates a heap containing the given values.
 * @template TValue
 * @param iterable<TValue> $values
 * @param null|callable(TValue, TValue): int $comparator
 * @return Heap<TValue>
 * @since PECL ds 2.0.0
 */
function heap(iterable $values = [], ?callable $comparator = null): Heap {}

/**
 * Key allows objects to define custom equality when used as map keys or set values.
 * @since PECL ds 2.0.0
 */
interface Key
{
    /**
     * Determines whether another value is equal to this instance.
     * @param mixed $other
     */
    public function equals($other): bool;

    /**
     * Returns a value used as this object's hash.
     * @return mixed
     */
    public function hash();
}

/**
 * @template TValue
 * @implements IteratorAggregate<int, TValue>
 * @implements ArrayAccess<int, TValue>
 * @since PECL ds 2.0.0
 */
final class Seq implements Countable, IteratorAggregate, JsonSerializable, ArrayAccess
{
    public const MIN_CAPACITY = 8;

    /**
     * @param iterable<TValue> $values
     */
    public function __construct(iterable $values = []) {}


    public function allocate(int $capacity): void {}

    /**
     * @param callable(TValue): TValue $callback
     */
    public function apply(callable $callback): void {}


    public function capacity(): int {}


    public function clear(): void {}

    /**
     * @param TValue ...$values
     */
    public function contains(...$values): bool {}

    /**
     * @return Seq<TValue>
     */
    public function copy(): Seq {}


    public function count(): int {}

    /**
     * @param null|callable(TValue): bool $callback
     * @return Seq<TValue>
     */
    public function filter(?callable $callback = null): Seq {}

    /**
     * @param TValue $value
     * @return int|false
     */
    public function find($value) {}

    /**
     * @return TValue
     */
    public function first() {}

    /**
     * @return Traversable<int, TValue>
     */
    public function getIterator(): Traversable {}

    /**
     * @return TValue
     */
    public function get(int $index) {}

    /**
     * @param TValue ...$values
     */
    public function insert(int $index, ...$values): void {}


    public function isEmpty(): bool {}


    public function join(string $glue = ''): string {}

    /**
     * @return array<int, TValue>
     */
    public function jsonSerialize(): array {}

    /**
     * @return TValue
     */
    public function last() {}

    /**
     * @template TReturn
     * @param callable(TValue): TReturn $callback
     * @return Seq<TReturn>
     */
    public function map(callable $callback): Seq {}

    /**
     * @param iterable<TValue> $values
     * @return Seq<TValue>
     */
    public function merge($values): Seq {}

    /**
     * @return TValue
     */
    public function pop() {}

    /**
     * @param TValue ...$values
     */
    public function push(...$values): void {}

    /**
     * @template TInitial
     * @template TReturn
     * @param callable(TInitial|TReturn|null, TValue): TReturn $callback
     * @param TInitial|null $initial
     * @return TReturn|null
     */
    public function reduce(callable $callback, $initial = null) {}

    /**
     * @return TValue
     */
    public function remove(int $index) {}


    public function reverse(): void {}

    /**
     * @return Seq<TValue>
     */
    public function reversed(): Seq {}


    public function rotate(int $rotations): void {}

    /**
     * @param TValue $value
     */
    public function set(int $index, $value): void {}

    /**
     * @return TValue
     */
    public function shift() {}

    /**
     * @return Seq<TValue>
     */
    public function slice(int $index, ?int $length = null): Seq {}

    /**
     * @param null|callable(TValue, TValue): int $comparator
     */
    public function sort(?callable $comparator = null): void {}

    /**
     * @param null|callable(TValue, TValue): int $comparator
     * @return Seq<TValue>
     */
    public function sorted(?callable $comparator = null): Seq {}

    /**
     * @return int|float
     */
    public function sum() {}

    /**
     * @return array<int, TValue>
     */
    public function toArray(): array {}

    /**
     * @param TValue ...$values
     */
    public function unshift(...$values): void {}

    /**
     * @return array<int, TValue>
     */
    public function __serialize(): array {}


    public function __unserialize(array $data): void {}


    public function offsetExists(mixed $offset): bool {}


    public function offsetGet(mixed $offset): mixed {}


    public function offsetSet(mixed $offset, mixed $value): void {}


    public function offsetUnset(mixed $offset): void {}
}

/**
 * <div id="class.ds-map" class="reference"> <h1 class="title">The Map class</h1>  <div class="partintro"><p class="verinfo">(PECL ds &gt;= 1.0.0)</p>  <div class="section" id="ds-map.intro">   <h2 class="title">简介</h2>   <p class="para">    A Map is a sequential collection of key-value pairs, almost identical to an    <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.array.php" class="type array" style="color:#EAB766">array</a></span> used in a similar context. Keys can be any type, but must be unique.    Values are replaced if added to the map using the same key.   </p>  </div><div class="section" id="ds-map.strengths">    <h2 class="title">Strengths</h2>    <p class="para">        </p><ul class="simplelist">            <li>Keys and values can be any type, including objects.</li>            <li>Supports array syntax (square brackets).</li>            <li>Insertion order is preserved.</li>            <li>Performance and memory efficiency is very similar to an <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.array.php" class="type array" style="color:#EAB766">array</a></span>.</li>            <li>Automatically frees allocated memory when its size drops low enough.</li>        </ul>   </div><div class="section" id="ds-map.weaknesses">    <h2 class="title">Weaknesses</h2>    <p class="para">        </p><ul class="simplelist">            <li>Can’t be converted to an array when objects are used as keys.</li>        </ul>   </div>  <div class="section" id="ds-map.synopsis">   <h2 class="title">类摘要</h2>   <div class="classsynopsis">    <span class="ooclass"><strong class="classname"></strong></span>    <div class="classsynopsisinfo">     <span class="ooclass">      <span class="modifier">class</span> <strong class="classname">Ds\Map</strong>     </span>     <span class="oointerface"><span class="modifier">implements</span>        <a href="https://php.net/manual/zh/class.ds-collection.php" class="interfacename">Ds\Collection</a></span><span class="oointerface">,  <a href="https://php.net/manual/zh/class.arrayaccess.php" class="interfacename">ArrayAccess</a></span> {</div>    <div class="classsynopsisinfo classsynopsisinfo_comment">// 常量 </div>    <div class="fieldsynopsis">     <span class="modifier">const</span>     <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.integer.php" class="type int" style="color:#EAB766">int</a></span>      <var class="fieldsynopsis_varname"><a href="https://php.net/manual/zh/class.ds-map.php#ds-map.constants.min-capacity"><var class="varname">MIN_CAPACITY</var></a></var><span class="initializer"> = 8</span>;</div>    <div class="classsynopsisinfo classsynopsisinfo_comment">// 方法 </div>    <div class="methodsynopsis dc-description">   <span class="modifier">public</span> <span class="modifier">function</span> <span class="methodname" style="color:#CC7832"><a href="https://php.net/manual/zh/ds-map.allocate.php" class="methodname" style="color:#CC7832">allocate</a></span>(<span class="methodparam"><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.integer.php" class="type int" style="color:#EAB766">int</a></span> <span class="parameter" style="color:#3A95FF">\$capacity</span></span>): <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.void.php" class="type void" style="color:#EAB766">void</a></span></div><div class="methodsynopsis dc-description"><span class="modifier">public</span> <span class="modifier">function</span> <span class="methodname" style="color:#CC7832"><a href="https://php.net/manual/zh/ds-map.apply.php" class="methodname" style="color:#CC7832">apply</a></span>(<span class="methodparam"><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.callable.php" class="type callable" style="color:#EAB766">callable</a></span> <span class="parameter" style="color:#3