language.types.void.php" class="type void" style="color:#EAB766">void</a></span></div><div class="methodsynopsis dc-description"><span class="modifier">public</span> <span class="modifier">function</span> <span class="methodname" style="color:#CC7832"><a href="https://php.net/manual/zh/ds-map.sorted.php" class="methodname" style="color:#CC7832">sorted</a></span>(<span class="methodparam"><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.callable.php" class="type callable" style="color:#EAB766">callable</a></span> <span class="parameter" style="color:#3A95FF">\$comparator</span><span class="initializer"> = ?</span></span>): <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/class.ds-map.php" class="type Ds\Map" style="color:#EAB766">Ds\Map</a></span></div><div class="methodsynopsis dc-description"><span class="modifier">public</span> <span class="modifier">function</span> <span class="methodname" style="color:#CC7832"><a href="https://php.net/manual/zh/ds-map.sum.php" class="methodname" style="color:#CC7832">sum</a></span>(): <span class="type" style="color:#EAB766"><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.integer.php" class="type int" style="color:#EAB766">int</a></span>|<span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.float.php" class="type float" style="color:#EAB766">float</a></span></span></div><div class="methodsynopsis dc-description"><span class="modifier">public</span> <span class="modifier">function</span> <span class="methodname" style="color:#CC7832"><a href="https://php.net/manual/zh/ds-map.toarray.php" class="methodname" style="color:#CC7832">toArray</a></span>(): <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.array.php" class="type array" style="color:#EAB766">array</a></span></div><div class="methodsynopsis dc-description"><span class="modifier">public</span> <span class="modifier">function</span> <span class="methodname" style="color:#CC7832"><a href="https://php.net/manual/zh/ds-map.union.php" class="methodname" style="color:#CC7832">union</a></span>(<span class="methodparam"><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/class.ds-map.php" class="type Ds\Map" style="color:#EAB766">Ds\Map</a></span> <span class="parameter" style="color:#3A95FF">\$map</span></span>): <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/class.ds-map.php" class="type Ds\Map" style="color:#EAB766">Ds\Map</a></span></div><div class="methodsynopsis dc-description"><span class="modifier">public</span> <span class="modifier">function</span> <span class="methodname" style="color:#CC7832"><a href="https://php.net/manual/zh/ds-map.values.php" class="methodname" style="color:#CC7832">values</a></span>(): <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/class.ds-sequence.php" class="type Ds\Sequence" style="color:#EAB766">Ds\Sequence</a></span></div><div class="methodsynopsis dc-description"><span class="modifier">public</span> <span class="modifier">function</span> <span class="methodname" style="color:#CC7832"><a href="https://php.net/manual/zh/ds-map.xor.php" class="methodname" style="color:#CC7832">xor</a></span>(<span class="methodparam"><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/class.ds-map.php" class="type Ds\Map" style="color:#EAB766">Ds\Map</a></span> <span class="parameter" style="color:#3A95FF">\$map</span></span>): <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/class.ds-map.php" class="type Ds\Map" style="color:#EAB766">Ds\Map</a></span></div>   }</div>  </div>  <div class="section" id="ds-map.constants">   <h2 class="title">预定义常量</h2>   <dl>         <dt id="ds-map.constants.min-capacity"><strong><span>{@link Ds\Map::MIN_CAPACITY}</span></strong></dt>     <dd>      <p class="para"></p>     </dd>       </dl>  </div>  <div class="section">   <h2 class="title">更新日志</h2>   <p class="para">    </p><table class="doctable informaltable">           <thead>       <tr>        <th>版本</th>        <th>说明</th>       </tr>      </thead>      <tbody class="tbody">       <tr>        <td>PECL ds 1.3.0</td>        <td>         The class now implements <span class="classname"><a href="https://php.net/manual/zh/class.arrayaccess.php" class="classname">ArrayAccess</a></span>.        </td>       </tr>       <tr>        <td>PECL ds 1.2.0</td>        <td>         <strong><span>{@link Ds\Map::MIN_CAPACITY}</span></strong> changed from 16 to 8.        </td>       </tr>      </tbody>         </table>     </div> </div> <h2>目录</h2><ul class="chunklist chunklist_reference"><li>{@link Ds\Map::allocate} — Allocates enough memory for a required capacity</li><li>{@link Ds\Map::apply} — Updates all values by applying a callback function to each value</li><li>{@link Ds\Map::capacity} — Returns the current capacity</li><li>{@link Ds\Map::clear} — Removes all values</li><li>{@link Ds\Map::__construct} — Creates a new instance</li><li>{@link Ds\Map::copy} — Returns a shallow copy of the map</li><li>{@link Ds\Map::count} — Returns the number of values in the map</li><li>{@link Ds\Map::diff} — Creates a new map using keys that aren't in another map</li><li>{@link Ds\Map::filter} — Creates a new map using a callable to determine which pairs to include</li><li>{@link Ds\Map::first} — Returns the first pair in the map</li><li>{@link Ds\Map::get} — Returns the value for a given key</li><li>{@link Ds\Map::hasKey} — Determines whether the map contains a given key</li><li>{@link Ds\Map::hasValue} — Determines whether the map contains a given value</li><li>{@link Ds\Map::intersect} — Creates a new map by intersecting keys with another map</li><li>{@link Ds\Map::isEmpty} — Returns whether the map is empty</li><li>{@link Ds\Map::jsonSerialize} — Returns a representation that can be converted to JSON</li><li>{@link Ds\Map::keys} — Returns a set of the map's keys</li><li>{@link Ds\Map::ksort} — Sorts the map in-place by key</li><li>{@link Ds\Map::ksorted} — Returns a copy, sorted by key</li><li>{@link Ds\Map::last} — Returns the last pair of the map</li><li>{@link Ds\Map::map} — Returns the result of applying a callback to each value</li><li>{@link Ds\Map::merge} — Returns the result of adding all given associations</li><li>{@link Ds\Map::pairs} — Returns a sequence containing all the pairs of the map</li><li>{@link Ds\Map::put} — Associates a key with a value</li><li>{@link Ds\Map::putAll} — Associates all key-value pairs of a traversable object or array</li><li>{@link Ds\Map::reduce} — Reduces the map to a single value using a callback function</li><li>{@link Ds\Map::remove} — Removes and returns a value by key</li><li>{@link Ds\Map::reverse} — Reverses the map in-place</li><li>{@link Ds\Map::reversed} — Returns a reversed copy</li><li>{@link Ds\Map::skip} — Returns the pair at a given positional index</li><li>{@link Ds\Map::slice} — Returns a subset of the map defined by a starting index and length</li><li>{@link Ds\Map::sort} — Sorts the map in-place by value</li><li>{@link Ds\Map::sorted} — Returns a copy, sorted by value</li><li>{@link Ds\Map::sum} — Returns the sum of all values in the map</li><li>{@link Ds\Map::toArray} — Converts the map to an array</li><li>{@link Ds\Map::union} — Creates a new map using values from the current instance and another map</li><li>{@link Ds\Map::values} — Returns a sequence of the map's values</li><li>{@link Ds\Map::xor} — Creates a new map using keys of either the current instance or of another map, but not of both</li></ul></div>
 * 
 * @template TKey
 * @template TValue
 * @implements IteratorAggregate<TKey, TValue>
 * @implements ArrayAccess<TKey, TValue>
 * @since PECL ds 2.0.0
 */
final class Map implements Countable, IteratorAggregate, JsonSerializable, ArrayAccess
{
    public const MIN_CAPACITY = 8;

    /**
 * <div id="ds-map.construct" class="refentry"> <div class="refnamediv">  <h1 class="refname">Ds\Map::__construct</h1>  <p class="verinfo">(PECL ds &gt;= 1.0.0)</p><p class="refpurpose"><span class="refname">Ds\Map::__construct</span> — <span class="dc-title">Creates a new instance</span></p> </div> <div class="refsect1 description" id="refsect1-ds-map.construct-description">  <h3 class="title">说明</h3>  <div class="constructorsynopsis dc-description">   <span class="modifier">public</span> <span class="modifier">function</span> <span class="methodname" style="color:#CC7832"><strong>Ds\Map::__construct</strong></span>(<span class="methodparam"><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.mixed.php" class="type mixed" style="color:#EAB766">mixed</a></span> <span class="parameter" style="color:#3A95FF">...\$values</span></span>)</div>  <p class="para rdfs-comment">    Creates a new instance, using either a <span class="classname"><a href="https://php.net/manual/zh/class.traversable.php" class="classname">traversable</a></span>    object or an <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.array.php" class="type array" style="color:#EAB766">array</a></span> for the initial <span class="parameter" style="color:#3A95FF">values</span>.  </p> </div> <div class="refsect1 parameters" id="refsect1-ds-map.construct-parameters">  <h3 class="title">参数</h3>  <dl>       <dt><span class="parameter" style="color:#3A95FF">values</span></dt>    <dd>     <p class="para">        A traversable object or an <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.array.php" class="type array" style="color:#EAB766">array</a></span> to use for the initial values.     </p>    </dd>     </dl> </div>  <div class="refsect1 examples" id="refsect1-ds-map.construct-examples">  <h3 class="title">示例</h3>  <div class="example" id="example-1">   <p><strong>示例 #1 <span class="function"><strong style="color:#CC7832">Ds\Map::__construct()</strong></span> example</strong></p>   <div class="example-contents"><div class="phpcode" style="border-color:gray;background:#1E1F22;"><blockquote style="border:1px gray solid;white-space:pre-wrap"><span style="color: #000000"><span style="color: #9876AA">&lt;?php<br>\$map </span><span style="color: #007700">= new </span><span style="color: #9876AA">\Ds\Map</span><span style="color: #007700">();<br></span><span style="color: #9876AA">var_dump</span><span style="color: #007700">(</span><span style="color: #9876AA">\$map</span><span style="color: #007700">);<br><br></span><span style="color: #9876AA">\$map </span><span style="color: #007700">= new </span><span style="color: #9876AA">\Ds\Map</span><span style="color: #007700">([</span><span style="color: #DD0000">"a" </span><span style="color: #007700">=&gt; </span><span style="color: #9876AA">1</span><span style="color: #007700">, </span><span style="color: #DD0000">"b" </span><span style="color: #007700">=&gt; </span><span style="color: #9876AA">2</span><span style="color: #007700">, </span><span style="color: #DD0000">"c" </span><span style="color: #007700">=&gt; </span><span style="color: #9876AA">3</span><span style="color: #007700">]);<br></span><span style="color: #9876AA">var_dump</span><span style="color: #007700">(</span><span style="color: #9876AA">\$map</span><span style="color: #007700">);<br></span><span style="color: #9876AA">?&gt;</span></span></blockquote></div>   </div>   <div class="example-contents"><p>以上示例的输出类似于：</p></div>   <div class="example-contents screen" style="border-color:gray;background:#1E1F22;"><div class="examplescode"><blockquote style="border:1px gray solid;">object(Ds\Map)#1&nbsp;(0)&nbsp;{<br>}<br>object(Ds\Map)#2&nbsp;(3)&nbsp;{<br>&nbsp;&nbsp;[0]=&gt;<br>&nbsp;&nbsp;object(Ds\Pair)#1&nbsp;(2)&nbsp;{<br>&nbsp;&nbsp;&nbsp;&nbsp;["key"]=&gt;<br>&nbsp;&nbsp;&nbsp;&nbsp;string(1)&nbsp;"a"<br>&nbsp;&nbsp;&nbsp;&nbsp;["value"]=&gt;<br>&nbsp;&nbsp;&nbsp;&nbsp;int(1)<br>&nbsp;&nbsp;}<br>&nbsp;&nbsp;[1]=&gt;<br>&nbsp;&nbsp;object(Ds\Pair)#3&nbsp;(2)&nbsp;{<br>&nbsp;&nbsp;&nbsp;&nbsp;["key"]=&gt;<br>&nbsp;&nbsp;&nbsp;&nbsp;string(1)&nbsp;"b"<br>&nbsp;&nbsp;&nbsp;&nbsp;["value"]=&gt;<br>&nbsp;&nbsp;&nbsp;&nbsp;int(2)<br>&nbsp;&nbsp;}<br>&nbsp;&nbsp;[2]=&gt;<br>&nbsp;&nbsp;object(Ds\Pair)#4&nbsp;(2)&nbsp;{<br>&nbsp;&nbsp;&nbsp;&nbsp;["key"]=&gt;<br>&nbsp;&nbsp;&nbsp;&nbsp;string(1)&nbsp;"c"<br>&nbsp;&nbsp;&nbsp;&nbsp;["value"]=&gt;<br>&nbsp;&nbsp;&nbsp;&nbsp;int(3)<br>&nbsp;&nbsp;}<br>}</blockquote></div>   </div>  </div> </div></div>
 * 
     * @param iterable<TKey, TValue> $values
     */
    public function __construct(iterable $values = []) {}

/**
 * <div id="ds-map.allocate" class="refentry"> <div class="refnamediv">  <h1 class="refname">Ds\Map::allocate</h1>  <p class="verinfo">(PECL ds &gt;= 1.0.0)</p><p class="refpurpose"><span class="refname">Ds\Map::allocate</span> — <span class="dc-title">Allocates enough memory for a required capacity</span></p> </div> <div class="refsect1 description" id="refsect1-ds-map.allocate-description">  <h3 class="title">说明</h3>  <div class="methodsynopsis dc-description">   <span class="modifier">public</span> <span class="modifier">function</span> <span class="methodname" style="color:#CC7832"><strong>Ds\Map::allocate</strong></span>(<span class="methodparam"><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.integer.php" class="type int" style="color:#EAB766">int</a></span> <span class="parameter" style="color:#3A95FF">\$capacity</span></span>): <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.void.php" class="type void" style="color:#EAB766">void</a></span></div>  <p class="para rdfs-comment">    Allocates enough memory for a required capacity.  </p> </div> <div class="refsect1 parameters" id="refsect1-ds-map.allocate-parameters">  <h3 class="title">参数</h3>  <dl>       <dt><span class="parameter" style="color:#3A95FF">capacity</span></dt>    <dd>     <p class="para">        The number of values for which capacity should be allocated.     </p>     <blockquote class="note" style="border:1px gray solid"><p><strong class="note" style="border:1px gray solid">注意</strong>:         </p><p class="para">            Capacity will stay the same if this value is less than or equal to the            current capacity.        </p>     </blockquote>     <blockquote class="note" style="border:1px gray solid"><p><strong class="note" style="border:1px gray solid">注意</strong>:         </p><p class="para">            Capacity will always be rounded up to the nearest power of 2.        </p>     </blockquote>    </dd>     </dl> </div> <div class="refsect1 returnvalues" id="refsect1-ds-map.allocate-returnvalues">  <h3 class="title">返回值</h3>  <p class="para">    没有返回值。  </p> </div> <div class="refsect1 examples" id="refsect1-ds-map.allocate-examples">  <h3 class="title">示例</h3>  <div class="example" id="example-1">   <p><strong>示例 #1 <span class="function"><strong style="color:#CC7832">Ds\Map::allocate()</strong></span> example</strong></p>   <div class="example-contents"><div class="phpcode" style="border-color:gray;background:#1E1F22;"><blockquote style="border:1px gray solid;white-space:pre-wrap"><span style="color: #000000"><span style="color: #9876AA">&lt;?php<br>\$map </span><span style="color: #007700">= new </span><span style="color: #9876AA">\Ds\Map</span><span style="color: #007700">();<br></span><span style="color: #9876AA">var_dump</span><span style="color: #007700">(</span><span style="color: #9876AA">\$map</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">capacity</span><span style="color: #007700">());<br><br></span><span style="color: #9876AA">\$map</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">allocate</span><span style="color: #007700">(</span><span style="color: #9876AA">100</span><span style="color: #007700">);<br></span><span style="color: #9876AA">var_dump</span><span style="color: #007700">(</span><span style="color: #9876AA">\$map</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">capacity</span><span style="color: #007700">());<br></span><span style="color: #9876AA">?&gt;</span></span></blockquote></div>   </div>   <div class="example-contents"><p>以上示例的输出类似于：</p></div>   <div class="example-contents screen" style="border-color:gray;background:#1E1F22;"><div class="examplescode"><blockquote style="border:1px gray solid;">int(16)<br>int(128)</blockquote></div>   </div>  </div> </div></div>
 */
    public function allocate(int $capacity): void {}

    /**
 * <div id="ds-map.apply" class="refentry"> <div class="refnamediv">  <h1 class="refname">Ds\Map::apply</h1>  <p class="verinfo">(PECL ds &gt;= 1.0.0)</p><p class="refpurpose"><span class="refname">Ds\Map::apply</span> — <span class="dc-title">Updates all values by applying a callback function to each value</span></p> </div> <div class="refsect1 description" id="refsect1-ds-map.apply-description">  <h3 class="title">说明</h3>  <div class="methodsynopsis dc-description">   <span class="modifier">public</span> <span class="modifier">function</span> <span class="methodname" style="color:#CC7832"><strong>Ds\Map::apply</strong></span>(<span class="methodparam"><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.callable.php" class="type callable" style="color:#EAB766">callable</a></span> <span class="parameter" style="color:#3A95FF">\$callback</span></span>): <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.void.php" class="type void" style="color:#EAB766">void</a></span></div>  <p class="para rdfs-comment">    Updates all values by applying a <span class="parameter" style="color:#3A95FF">callback</span> function to    each value in the map.  </p> </div> <div class="refsect1 parameters" id="refsect1-ds-map.apply-parameters">  <h3 class="title">参数</h3>  <dl>       <dt><span class="parameter" style="color:#3A95FF">callback</span></dt>    <dd>        <p class="para">            </p><div class="methodsynopsis dc-description">                <span class="modifier">function</span> <span class="methodname" style="color:#CC7832"><span class="replaceable">callback</span></span>(<span class="methodparam"><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.mixed.php" class="type mixed" style="color:#EAB766">mixed</a></span> <span class="parameter" style="color:#3A95FF">\$key</span></span>, <span class="methodparam"><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.mixed.php" class="type mixed" style="color:#EAB766">mixed</a></span> <span class="parameter" style="color:#3A95FF">\$value</span></span>): <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.mixed.php" class="type mixed" style="color:#EAB766">mixed</a></span></div>                <p class="para">            A <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.callable.php" class="type callable" style="color:#EAB766">callable</a></span> to apply to each value in the map.        </p>        <p class="para">            The callback should return what the value should be replaced by.        </p>    </dd>     </dl> </div> <div class="refsect1 returnvalues" id="refsect1-ds-map.apply-returnvalues">  <h3 class="title">返回值</h3>  <p class="para">    没有返回值。  </p> </div> <div class="refsect1 examples" id="refsect1-ds-map.apply-examples">  <h3 class="title">示例</h3>  <div class="example" id="example-1">   <p><strong>示例 #1 <span class="function"><strong style="color:#CC7832">Ds\Map::apply()</strong></span> example</strong></p>   <div class="example-contents"><div class="phpcode" style="border-color:gray;background:#1E1F22;"><blockquote style="border:1px gray solid;white-space:pre-wrap"><span style="color: #000000"><span style="color: #9876AA">&lt;?php<br>\$map </span><span style="color: #007700">= new </span><span style="color: #9876AA">\Ds\Map</span><span style="color: #007700">([</span><span style="color: #DD0000">"a" </span><span style="color: #007700">=&gt; </span><span style="color: #9876AA">1</span><span style="color: #007700">, </span><span style="color: #DD0000">"b" </span><span style="color: #007700">=&gt; </span><span style="color: #9876AA">2</span><span style="color: #007700">, </span><span style="color: #DD0000">"c" </span><span style="color: #007700">=&gt; </span><span style="color: #9876AA">3</span><span style="color: #007700">]);<br></span><span style="color: #9876AA">\$map</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">apply</span><span style="color: #007700">(function(</span><span style="color: #9876AA">\$key</span><span style="color: #007700">, </span><span style="color: #9876AA">\$value</span><span style="color: #007700">) { return </span><span style="color: #9876AA">\$value </span><span style="color: #007700">* </span><span style="color: #9876AA">2</span><span style="color: #007700">; });<br><br></span><span style="color: #9876AA">print_r</span><span style="color: #007700">(</span><span style="color: #9876AA">\$map</span><span style="color: #007700">);<br></span><span style="color: #9876AA">?&gt;</span></span></blockquote></div>   </div>   <div class="example-contents"><p>以上示例的输出类似于：</p></div>   <div class="example-contents screen" style="border-color:gray;background:#1E1F22;"><div class="examplescode"><blockquote style="border:1px gray solid;">Ds\Map&nbsp;Object<br>(<br>&nbsp;&nbsp;&nbsp;&nbsp;[0]&nbsp;=&gt;&nbsp;Ds\Pair&nbsp;Object<br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;(<br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;[key]&nbsp;=&gt;&nbsp;a<br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;[value]&nbsp;=&gt;&nbsp;2<br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;)<br><br>&nbsp;&nbsp;&nbsp;&nbsp;[1]&nbsp;=&gt;&nbsp;Ds\Pair&nbsp;Object<br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;(<br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;[key]&nbsp;=&gt;&nbsp;b<br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;[value]&nbsp;=&gt;&nbsp;4<br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;)<br><br>&nbsp;&nbsp;&nbsp;&nbsp;[2]&nbsp;=&gt;&nbsp;Ds\Pair&nbsp;Object<br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;(<br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;[key]&nbsp;=&gt;&nbsp;c<br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;[value]&nbsp;=&gt;&nbsp;6<br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;)<br><br>)</blockquote></div>   </div>  </div> </div></div>
 * 
     * @param callable(TKey, TValue): TValue $callback
     */
    public function apply(callable $callback): void {}

/**
 * <div id="ds-map.capacity" class="refentry"> <div class="refnamediv">  <h1 class="refname">Ds\Map::capacity</h1>  <p class="verinfo">(PECL ds &gt;= 1.0.0)</p><p class="refpurpose"><span class="refname">Ds\Map::capacity</span> — <span class="dc-title">Returns the current capacity</span></p> </div> <div class="refsect1 description" id="refsect1-ds-map.capacity-description">  <h3 class="title">说明</h3>  <div class="methodsynopsis dc-description">   <span class="modifier">public</span> <span class="modifier">function</span> <span class="methodname" style="color:#CC7832"><strong>Ds\Map::capacity</strong></span>(): <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.integer.php" class="type int" style="color:#EAB766">int</a></span></div>  <p class="para rdfs-comment">    Returns the current capacity.  </p> </div> <div class="refsect1 parameters" id="refsect1-ds-map.capacity-parameters">  <h3 class="title">参数</h3>  <p class="simpara">此函数没有参数。</p> </div> <div class="refsect1 returnvalues" id="refsect1-ds-map.capacity-returnvalues">  <h3 class="title">返回值</h3>  <p class="para">    The current capacity.  </p> </div> <div class="refsect1 examples" id="refsect1-ds-map.capacity-examples">  <h3 class="title">示例</h3>  <div class="example" id="example-1">   <p><strong>示例 #1 <span class="function"><strong style="color:#CC7832">Ds\Map::capacity()</strong></span> example</strong></p>   <div class="example-contents"><div class="phpcode" style="border-color:gray;background:#1E1F22;"><blockquote style="border:1px gray solid;white-space:pre-wrap"><span style="color: #000000"><span style="color: #9876AA">&lt;?php<br>\$map </span><span style="color: #007700">= new </span><span style="color: #9876AA">\Ds\Map</span><span style="color: #007700">();<br></span><span style="color: #9876AA">var_dump</span><span style="color: #007700">(</span><span style="color: #9876AA">\$map</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">capacity</span><span style="color: #007700">());<br></span><span style="color: #9876AA">?&gt;</span></span></blockquote></div>   </div>   <div class="example-contents"><p>以上示例的输出类似于：</p></div>   <div class="example-contents screen" style="border-color:gray;background:#1E1F22;"><div class="examplescode"><blockquote style="border:1px gray solid;">int(16)</blockquote></div>   </div>  </div> </div></div>
