    public function count(): int {}

/**
 * <div id="ds-map.diff" class="refentry"> <div class="refnamediv">  <h1 class="refname">Ds\Map::diff</h1>  <p class="verinfo">(PECL ds &gt;= 1.0.0)</p><p class="refpurpose"><span class="refname">Ds\Map::diff</span> — <span class="dc-title">Creates a new map using keys that aren't in another map</span></p> </div> <div class="refsect1 description" id="refsect1-ds-map.diff-description">  <h3 class="title">说明</h3>  <div class="methodsynopsis dc-description">   <span class="modifier">public</span> <span class="modifier">function</span> <span class="methodname" style="color:#CC7832"><strong>Ds\Map::diff</strong></span>(<span class="methodparam"><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/class.ds-map.php" class="type Ds\Map" style="color:#EAB766">Ds\Map</a></span> <span class="parameter" style="color:#3A95FF">\$map</span></span>): <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/class.ds-map.php" class="type Ds\Map" style="color:#EAB766">Ds\Map</a></span></div>  <p class="para rdfs-comment">    Returns the result of removing all keys from the current instance that are    present in a given <span class="parameter" style="color:#3A95FF">map</span>.  </p>  <p class="para">    <span class="code">A \ B = {x ∈ A | x ∉ B}</span>  </p> </div> <div class="refsect1 parameters" id="refsect1-ds-map.diff-parameters">  <h3 class="title">参数</h3>  <dl>       <dt><span class="parameter" style="color:#3A95FF">map</span></dt>    <dd>     <p class="para">        The map containing the keys to exclude in the resulting map.     </p>    </dd>     </dl> </div> <div class="refsect1 returnvalues" id="refsect1-ds-map.diff-returnvalues">  <h3 class="title">返回值</h3>  <p class="para">    The result of removing all keys from the current instance that are    present in a given <span class="parameter" style="color:#3A95FF">map</span>.  </p> </div> <div class="refsect1 seealso" id="refsect1-ds-map.diff-seealso">  <h3 class="title">参见</h3>  <p class="para">   </p><ul class="simplelist">    <li><a href="https://en.wikipedia.org/wiki/Complement_(set_theory)" class="link external">»&nbsp;Complement</a> on Wikipedia</li>   </ul>   </div> <div class="refsect1 examples" id="refsect1-ds-map.diff-examples">  <h3 class="title">示例</h3>  <div class="example" id="example-1">   <p><strong>示例 #1 <span class="function"><strong style="color:#CC7832">Ds\Map::diff()</strong></span> example</strong></p>   <div class="example-contents"><div class="phpcode" style="border-color:gray;background:#1E1F22;"><blockquote style="border:1px gray solid;white-space:pre-wrap"><span style="color: #000000"><span style="color: #9876AA">&lt;?php<br>\$a </span><span style="color: #007700">= new </span><span style="color: #9876AA">\Ds\Map</span><span style="color: #007700">([</span><span style="color: #DD0000">"a" </span><span style="color: #007700">=&gt; </span><span style="color: #9876AA">1</span><span style="color: #007700">, </span><span style="color: #DD0000">"b" </span><span style="color: #007700">=&gt; </span><span style="color: #9876AA">2</span><span style="color: #007700">, </span><span style="color: #DD0000">"c" </span><span style="color: #007700">=&gt; </span><span style="color: #9876AA">3</span><span style="color: #007700">]);<br></span><span style="color: #9876AA">\$b </span><span style="color: #007700">= new </span><span style="color: #9876AA">\Ds\Map</span><span style="color: #007700">([</span><span style="color: #DD0000">"b" </span><span style="color: #007700">=&gt; </span><span style="color: #9876AA">4</span><span style="color: #007700">, </span><span style="color: #DD0000">"c" </span><span style="color: #007700">=&gt; </span><span style="color: #9876AA">5</span><span style="color: #007700">, </span><span style="color: #DD0000">"d" </span><span style="color: #007700">=&gt; </span><span style="color: #9876AA">6</span><span style="color: #007700">]);<br><br></span><span style="color: #9876AA">var_dump</span><span style="color: #007700">(</span><span style="color: #9876AA">\$a</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">diff</span><span style="color: #007700">(</span><span style="color: #9876AA">\$b</span><span style="color: #007700">));<br></span><span style="color: #9876AA">?&gt;</span></span></blockquote></div>   </div>   <div class="example-contents"><p>以上示例的输出类似于：</p></div>   <div class="example-contents screen" style="border-color:gray;background:#1E1F22;"><div class="examplescode"><blockquote style="border:1px gray solid;">object(Ds\Map)#3&nbsp;(1)&nbsp;{<br>&nbsp;&nbsp;[0]=&gt;<br>&nbsp;&nbsp;object(Ds\Pair)#4&nbsp;(2)&nbsp;{<br>&nbsp;&nbsp;&nbsp;&nbsp;["key"]=&gt;<br>&nbsp;&nbsp;&nbsp;&nbsp;string(1)&nbsp;"a"<br>&nbsp;&nbsp;&nbsp;&nbsp;["value"]=&gt;<br>&nbsp;&nbsp;&nbsp;&nbsp;int(1)<br>&nbsp;&nbsp;}<br>}</blockquote></div>   </div>  </div> </div></div>
 */
    public function diff(Map $map): Map {}

    /**
 * <div id="ds-map.filter" class="refentry"> <div class="refnamediv">  <h1 class="refname">Ds\Map::filter</h1>  <p class="verinfo">(PECL ds &gt;= 1.0.0)</p><p class="refpurpose"><span class="refname">Ds\Map::filter</span> — <span class="dc-title">    Creates a new map using a <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.callable.php" class="type callable" style="color:#EAB766">callable</a></span> to determine which pairs to include  </span></p> </div> <div class="refsect1 description" id="refsect1-ds-map.filter-description">  <h3 class="title">说明</h3>  <div class="methodsynopsis dc-description"><span class="modifier">public</span> <span class="modifier">function</span> <span class="methodname" style="color:#CC7832"><strong>Ds\Map::filter</strong></span>(<span class="methodparam"><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.callable.php" class="type callable" style="color:#EAB766">callable</a></span> <span class="parameter" style="color:#3A95FF">\$callback</span><span class="initializer"> = ?</span></span>): <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/class.ds-map.php" class="type Ds\Map" style="color:#EAB766">Ds\Map</a></span></div>  <p class="para rdfs-comment">    Creates a new map using a <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.callable.php" class="type callable" style="color:#EAB766">callable</a></span> to determine which pairs to include.  </p> </div> <div class="refsect1 parameters" id="refsect1-ds-map.filter-parameters">  <h3 class="title">参数</h3>  <dl>       <dt><span class="parameter" style="color:#3A95FF">callback</span></dt>    <dd>        <p class="para">            </p><div class="methodsynopsis dc-description"><span class="modifier">function</span> <span class="methodname" style="color:#CC7832"><span class="replaceable">callback</span></span>(<span class="methodparam"><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.mixed.php" class="type mixed" style="color:#EAB766">mixed</a></span> <span class="parameter" style="color:#3A95FF">\$key</span></span>, <span class="methodparam"><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.mixed.php" class="type mixed" style="color:#EAB766">mixed</a></span> <span class="parameter" style="color:#3A95FF">\$value</span></span>): <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.boolean.php" class="type bool" style="color:#EAB766">bool</a></span></div>                <p class="para">            Optional <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.callable.php" class="type callable" style="color:#EAB766">callable</a></span> which returns <strong><span><a href="https://php.net/manual/zh/reserved.constants.php#constant.true">true</a></span></strong> if the pair should be included, <strong><span><a href="https://php.net/manual/zh/reserved.constants.php#constant.false">false</a></span></strong> otherwise.        </p>        <p class="para">            If a callback is not provided, only values which are <strong><span><a href="https://php.net/manual/zh/reserved.constants.php#constant.true">true</a></span></strong>            (see <a href="https://php.net/manual/zh/language.types.boolean.php#language.types.boolean.casting" class="link">converting to boolean</a>)            will be included.        </p>    </dd>     </dl> </div> <div class="refsect1 returnvalues" id="refsect1-ds-map.filter-returnvalues">  <h3 class="title">返回值</h3>  <p class="para">    A new map containing all the pairs for which    either the <span class="parameter" style="color:#3A95FF">callback</span> returned <strong><span><a href="https://php.net/manual/zh/reserved.constants.php#constant.true">true</a></span></strong>, or all values that    convert to <strong><span><a href="https://php.net/manual/zh/reserved.constants.php#constant.true">true</a></span></strong> if a <span class="parameter" style="color:#3A95FF">callback</span> was not provided.  </p> </div> <div class="refsect1 examples" id="refsect1-ds-map.filter-examples">  <h3 class="title">示例</h3>  <div class="example" id="example-1">   <p><strong>示例 #1 <span class="function"><strong style="color:#CC7832">Ds\Map::filter()</strong></span> example using callback function</strong></p>   <div class="example-contents"><div class="phpcode" style="border-color:gray;background:#1E1F22;"><blockquote style="border:1px gray solid;white-space:pre-wrap"><span style="color: #000000"><span style="color: #9876AA">&lt;?php<br>\$map </span><span style="color: #007700">= new </span><span style="color: #9876AA">\Ds\Map</span><span style="color: #007700">([</span><span style="color: #DD0000">"a"</span><span style="color: #007700">, </span><span style="color: #DD0000">"b"</span><span style="color: #007700">, </span><span style="color: #DD0000">"c"</span><span style="color: #007700">, </span><span style="color: #DD0000">"d"</span><span style="color: #007700">, </span><span style="color: #DD0000">"e"</span><span style="color: #007700">]);<br><br></span><span style="color: #9876AA">var_dump</span><span style="color: #007700">(</span><span style="color: #9876AA">\$map</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">filter</span><span style="color: #007700">(function(</span><span style="color: #9876AA">\$key</span><span style="color: #007700">, </span><span style="color: #9876AA">\$value</span><span style="color: #007700">) {<br>    return </span><span style="color: #9876AA">\$key </span><span style="color: #007700">% </span><span style="color: #9876AA">2 </span><span style="color: #007700">== </span><span style="color: #9876AA">0</span><span style="color: #007700">;<br>}));<br></span><span style="color: #9876AA">?&gt;</span></span></blockquote></div>   </div>   <div class="example-contents"><p>以上示例的输出类似于：</p></div>   <div class="example-contents screen" style="border-color:gray;background:#1E1F22;"><div class="examplescode"><blockquote style="border:1px gray solid;">object(Ds\Map)#3&nbsp;(3)&nbsp;{<br>&nbsp;&nbsp;[0]=&gt;<br>&nbsp;&nbsp;object(Ds\Pair)#2&nbsp;(2)&nbsp;{<br>&nbsp;&nbsp;&nbsp;&nbsp;["key"]=&gt;<br>&nbsp;&nbsp;&nbsp;&nbsp;int(0)<br>&nbsp;&nbsp;&nbsp;&nbsp;["value"]=&gt;<br>&nbsp;&nbsp;&nbsp;&nbsp;string(1)&nbsp;"a"<br>&nbsp;&nbsp;}<br>&nbsp;&nbsp;[1]=&gt;<br>&nbsp;&nbsp;object(Ds\Pair)#4&nbsp;(2)&nbsp;{<br>&nbsp;&nbsp;&nbsp;&nbsp;["key"]=&gt;<br>&nbsp;&nbsp;&nbsp;&nbsp;int(2)<br>&nbsp;&nbsp;&nbsp;&nbsp;["value"]=&gt;<br>&nbsp;&nbsp;&nbsp;&nbsp;string(1)&nbsp;"c"<br>&nbsp;&nbsp;}<br>&nbsp;&nbsp;[2]=&gt;<br>&nbsp;&nbsp;object(Ds\Pair)#5&nbsp;(2)&nbsp;{<br>&nbsp;&nbsp;&nbsp;&nbsp;["key"]=&gt;<br>&nbsp;&nbsp;&nbsp;&nbsp;int(4)<br>&nbsp;&nbsp;&nbsp;&nbsp;["value"]=&gt;<br>&nbsp;&nbsp;&nbsp;&nbsp;string(1)&nbsp;"e"<br>&nbsp;&nbsp;}<br>}</blockquote></div>   </div>  </div>  <div class="example" id="example-2">   <p><strong>示例 #2 <span class="function"><strong style="color:#CC7832">Ds\Map::filter()</strong></span> example without a callback function</strong></p>   <div class="example-contents"><div class="phpcode" style="border-color:gray;background:#1E1F22;"><blockquote style="border:1px gray solid;white-space:pre-wrap"><span style="color: #000000"><span style="color: #9876AA">&lt;?php<br>\$map </span><span style="color: #007700">= new </span><span style="color: #9876AA">\Ds\Map</span><span style="color: #007700">([</span><span style="color: #DD0000">"a" </span><span style="color: #007700">=&gt; </span><span style="color: #9876AA">0</span><span style="color: #007700">, </span><span style="color: #DD0000">"b" </span><span style="color: #007700">=&gt; </span><span style="color: #9876AA">1</span><span style="color: #007700">, </span><span style="color: #DD0000">"c" </span><span style="color: #007700">=&gt; </span><span style="color: #9876AA">true</span><span style="color: #007700">, </span><span style="color: #DD0000">"d" </span><span style="color: #007700">=&gt; </span><span style="color: #9876AA">false</span><span style="color: #007700">]);<br><br></span><span style="color: #9876AA">var_dump</span><span style="color: #007700">(</span><span style="color: #9876AA">\$map</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">filter</span><span style="color: #007700">());<br></span><span style="color: #9876AA">?&gt;</span></span></blockquote></div>   </div>   <div class="example-contents"><p>以上示例的输出类似于：</p></div>   <div class="example-contents screen" style="border-color:gray;background:#1E1F22;"><div class="examplescode"><blockquote style="border:1px gray solid;">object(Ds\Map)#2&nbsp;(3)&nbsp;{<br>&nbsp;&nbsp;[0]=&gt;<br>&nbsp;&nbsp;int(1)<br>&nbsp;&nbsp;[1]=&gt;<br>&nbsp;&nbsp;string(1)&nbsp;"a"<br>&nbsp;&nbsp;[2]=&gt;<br>&nbsp;&nbsp;bool(true)<br>}</blockquote></div>   </div>  </div> </div></div>
 * 
     * @param null|callable(TKey, TValue): bool $callback
     * @return Map<TKey, TValue>
     */
    public function filter(?callable $callback = null): Map {}

/**
 * <div id="ds-map.first" class="refentry"> <div class="refnamediv">  <h1 class="refname">Ds\Map::first</h1>  <p class="verinfo">(PECL ds &gt;= 1.0.0)</p><p class="refpurpose"><span class="refname">Ds\Map::first</span> — <span class="dc-title">Returns the first pair in the map</span></p> </div> <div class="refsect1 description" id="refsect1-ds-map.first-description">  <h3 class="title">说明</h3>  <div class="methodsynopsis dc-description">   <span class="modifier">public</span> <span class="modifier">function</span> <span class="methodname" style="color:#CC7832"><strong>Ds\Map::first</strong></span>(): <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/class.ds-pair.php" class="type Ds\Pair" style="color:#EAB766">Ds\Pair</a></span></div>  <p class="para rdfs-comment">    Returns the first pair in the map.  </p> </div> <div class="refsect1 parameters" id="refsect1-ds-map.first-parameters">  <h3 class="title">参数</h3>  <p class="simpara">此函数没有参数。</p> </div> <div class="refsect1 returnvalues" id="refsect1-ds-map.first-returnvalues">  <h3 class="title">返回值</h3>  <p class="para">    The first pair in the map.  </p> </div> <div class="refsect1 errors" id="refsect1-ds-map.first-errors">  <h3 class="title">错误／异常</h3>  <p class="para">   <span class="classname"><a href="https://php.net/manual/zh/class.underflowexception.php" class="classname">UnderflowException</a></span> if empty.  </p> </div> <div class="refsect1 examples" id="refsect1-ds-map.first-examples">  <h3 class="title">示例</h3>  <div class="example" id="example-1">   <p><strong>示例 #1 <span class="function"><strong style="color:#CC7832">Ds\Map::first()</strong></span> example</strong></p>   <div class="example-contents"><div class="phpcode" style="border-color:gray;background:#1E1F22;"><blockquote style="border:1px gray solid;white-space:pre-wrap"><span style="color: #000000"><span style="color: #9876AA">&lt;?php<br>\$map </span><span style="color: #007700">= new </span><span style="color: #9876AA">\Ds\Map</span><span style="color: #007700">([</span><span style="color: #DD0000">"a" </span><span style="color: #007700">=&gt; </span><span style="color: #9876AA">1</span><span style="color: #007700">, </span><span style="color: #DD0000">"b" </span><span style="color: #007700">=&gt; </span><span style="color: #9876AA">2</span><span style="color: #007700">, </span><span style="color: #DD0000">"c" </span><span style="color: #007700">=&gt; </span><span style="color: #9876AA">3</span><span style="color: #007700">]);<br></span><span style="color: #9876AA">var_dump</span><span style="color: #007700">(</span><span style="color: #9876AA">\$map</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">first</span><span style="color: #007700">());<br></span><span style="color: #9876AA">?&gt;</span></span></blockquote></div>   </div>   <div class="example-contents"><p>以上示例的输出类似于：</p></div>   <div class="example-contents screen" style="border-color:gray;background:#1E1F22;"><div class="examplescode"><blockquote style="border:1px gray solid;">object(Ds\Pair)#2&nbsp;(2)&nbsp;{<br>&nbsp;&nbsp;["key"]=&gt;<br>&nbsp;&nbsp;string(1)&nbsp;"a"<br>&nbsp;&nbsp;["value"]=&gt;<br>&nbsp;&nbsp;int(1)<br>}</blockquote></div>   </div>  </div> </div></div>
 */
    public function first(): Pair {}

    /**
 * <div id="ds-map.get" class="refentry"> <div class="refnamediv">  <h1 class="refname">Ds\Map::get</h1>  <p class="verinfo">(PECL ds &gt;= 1.0.0)</p><p class="refpurpose"><span class="refname">Ds\Map::get</span> — <span class="dc-title">Returns the value for a given key</span></p> </div> <div class="refsect1 description" id="refsect1-ds-map.get-description">  <h3 class="title">说明</h3>  <div class="methodsynopsis dc-description">   <span class="modifier">public</span> <span class="modifier">function</span> <span class="methodname" style="color:#CC7832"><strong>Ds\Map::get</strong></span>(<span class="methodparam"><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.mixed.php" class="type mixed" style="color:#EAB766">mixed</a></span> <span class="parameter" style="color:#3A95FF">\$key</span></span>, <span class="methodparam"><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.mixed.php" class="type mixed" style="color:#EAB766">mixed</a></span> <span class="parameter" style="color:#3A95FF">\$default</span><span class="initializer"> = ?</span></span>): <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.mixed.php" class="type mixed" style="color:#EAB766">mixed</a></span></div>  <p class="para rdfs-comment">    Returns the value for a given key, or an optional default value if the key    could not be found.  </p>  <blockquote class="note" style="border:1px gray solid"><p><strong class="note" style="border:1px gray solid">注意</strong>:     </p><p class="para">        Keys of type <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.object.php" class="type object" style="color:#EAB766">object</a></span> are supported.        If an object implements <span class="classname"><a href="https://php.net/manual/zh/class.ds-hashable.php" class="classname">Ds\Hashable</a></span>,        equality will be determined by the object's <span class="code">equals</span> function.        If an object does not implement <span class="classname"><a href="https://php.net/manual/zh/class.ds-hashable.php" class="classname">Ds\Hashable</a></span>,        objects must be references to the same instance to be considered equal.    </p>  </blockquote>  <blockquote class="note" style="border:1px gray solid"><p><strong class="note" style="border:1px gray solid">注意</strong>:     </p><p class="para">        You can also use array syntax to access values by key, eg. <span class="code">\$map["key"]</span>.    </p>  </blockquote>  <div class="caution"><strong class="caution">警告</strong>    <p class="para">        Be careful when using array syntax. Scalar keys will be coerced to        integers by the engine. For example, <span class="code">\$map["1"]</span> will attempt        to access <span class="code">int(1)</span>, while <span class="code">\$map-&gt;get("1")</span> will        correctly look up the string key.    </p>    <p class="para">        See <a href="https://php.net/manual/zh/language.types.array.php" class="link">Arrays</a>.    </p>  </div> </div> <div class="refsect1 parameters" id="refsect1-ds-map.get-parameters">  <h3 class="title">参数</h3>  <dl>       <dt><span class="parameter" style="color:#3A95FF">key</span></dt>    <dd>     <p class="para">        The key to look up.     </p>    </dd>          <dt><span class="parameter" style="color:#3A95FF">default</span></dt>    <dd>     <p class="para">        The optional default value, returned if the key could not be found.     </p>    </dd>     </dl> </div> <div class="refsect1 returnvalues" id="refsect1-ds-map.get-returnvalues">  <h3 class="title">返回值</h3>  <p class="para">    The value mapped to the given <span class="parameter" style="color:#3A95FF">key</span>, or the <span class="parameter" style="color:#3A95FF">default</span>    value if provided and the key could not be found in the map.  </p> </div> <div class="refsect1 errors" id="refsect1-ds-map.get-errors">  <h3 class="title">错误／异常</h3>  <p class="para">   <span class="classname"><a href="https://php.net/manual/zh/class.outofboundsexception.php" class="classname">OutOfBoundsException</a></span> if the key could not be found   and a default value was not provided.  </p> </div> <div class="refsect1 examples" id="refsect1-ds-map.get-examples">  <h3 class="title">示例</h3>  <div class="example" id="example-1">   <p><strong>示例 #1 <span class="function"><strong style="color:#CC7832">Ds\Map::get()</strong></span> example</strong></p>   <div class="example-contents"><div class="phpcode" style="border-color:gray;background:#1E1F22;"><blockquote style="border:1px gray solid;white-space:pre-wrap"><span style="color: #000000"><span style="color: #9876AA">&lt;?php<br>\$map </span><span style="color: #007700">= new </span><span style="color: #9876AA">\Ds\Map</span><span style="color: #007700">([</span><span style="color: #DD0000">"a" </span><span style="color: #007700">=&gt; </span><span style="color: #9876AA">1</span><span style="color: #007700">, </span><span style="color: #DD0000">"b" </span><span style="color: #007700">=&gt; </span><span style="color: #9876AA">2</span><span style="color: #007700">, </span><span style="color: #DD0000">"c" </span><span style="color: #007700">=&gt; </span><span style="color: #9876AA">3</span><span style="color: #007700">]);<br><br></span><span style="color: #9876AA">var_dump</span><span style="color: #007700">(</span><span style="color: #9876AA">\$map</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">get</span><span style="color: #007700">(</span><span style="color: #DD0000">"a"</span><span style="color: #007700">));       </span><span style="color: #FF8000">// 1<br></span><span style="color: #9876AA">var_dump</span><span style="color: #007700">(</span><span style="color: #9876AA">\$map</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">get</span><span style="color: #007700">(</span><span style="color: #DD0000">"d"</span><span style="color: #007700">, </span><span style="color: #9876AA">10</span><span style="color: #007700">));   </span><span style="color: #FF8000">// 10 (default used)<br></span><span style="color: #9876AA">?&gt;</span></span></blockquote></div>   </div>   <div class="example-contents"><p>以上示例的输出类似于：</p></div>   <div class="example-contents screen" style="border-color:gray;background:#1E1F22;"><div class="examplescode"><blockquote style="border:1px gray solid;">int(1)<br>int(10)</blockquote></div>   </div>  </div>  <div class="example" id="example-2">   <p><strong>示例 #2 <span class="function"><strong style="color:#CC7832">Ds\Map::get()</strong></span> example using array syntax</strong></p>   <div class="example-contents"><div class="phpcode" style="border-color:gray;background:#1E1F22;"><blockquote style="border:1px gray solid;white-space:pre-wrap"><span style="color: #000000"><span style="color: #9876AA">&lt;?php<br>\$map </span><span style="color: #007700">= new </span><span style="color: #9876AA">\Ds\Map</span><span style="color: #007700">([</span><span style="color: #DD0000">"a" </span><span style="color: #007700">=&gt; </span><span style="color: #9876AA">1</span><span style="color: #007700">, </span><span style="color: #DD0000">"b" </span><span style="color: #007700">=&gt; </span><span style="color: #9876AA">2</span><span style="color: #007700">, </span><span style="color: #DD0000">"c" </span><span style="color: #007700">=&gt; </span><span style="color: #9876AA">3</span><span style="color: #007700">]);<br><br></span><span style="color: #9876AA">var_dump</span><span style="color: #007700">(</span><span style="color: #9876AA">\$map</span><span style="color: #007700">[</span><span style="color: #DD0000">"a"</span><span style="color: #007700">]); </span><span style="color: #FF8000">// 1<br></span><span style="color: #9876AA">?&gt;</span></span></blockquote></div>   </div>   <div class="example-contents"><p>以上示例的输出类似于：</p></div>   <div class="example-contents screen" style="border-color:gray;background:#1E1F22;"><div class="examplescode"><blockquote style="border:1px gray solid;">int(1)</blockquote></div>   </div>  </div> </div></div>
 * 
     * @param TKey $key
     * @param TValue|null $default
     * @return TValue|null
     */
    public function get($key, $default = null) {}

    /** @return Traversable<TKey, TValue> */
    public function getIterator(): Traversable {}

/**
 * <div id="ds-map.haskey" class="refentry"> <div class="refnamediv">  <h1 class="refname">Ds\Map::hasKey</h1>  <p class="verinfo">(PECL ds &gt;= 1.0.0)</p><p class="refpurpose"><span class="refname">Ds\Map::hasKey</span> — <span class="dc-title">Determines whether the map contains a given key</span></p> </div> <div class="refsect1 description" id="refsect1-ds-map.haskey-description">  <h3 class="title">说明</h3>  <div class="methodsynopsis dc-description">   <span class="modifier">public</span> <span class="modifier">function</span> <span class="methodname" style="color:#CC7832"><strong>Ds\Map::hasKey</strong></span>(<span class="methodparam"><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.mixed.php" class="type mixed" style="color:#EAB766">mixed</a></span> <span class="parameter" style="color:#3A95FF">\$key</span></span>): <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.boolean.php" class="type bool" style="color:#EAB766">bool</a></span></div>  <p class="para rdfs-comment">    Determines whether the map contains a given key.  </p> </div> <div class="refsect1 parameters" id="refsect1-ds-map.haskey-parameters">  <h3 class="title">参数</h3>  <dl>       <dt><span class="parameter" style="color:#3A95FF">key</span></dt>    <dd>     <p class="para">        The key to look for.     </p>    </dd>     </dl> </div> <div class="refsect1 returnvalues" id="refsect1-ds-map.haskey-returnvalues">  <h3 class="title">返回值</h3>  <p class="simpara">    Returns <strong><span><a href="https://php.net/manual/zh/reserved.constants.php#constant.true">true</a></span></strong> if the key could be found, <strong><span><a href="https://php.net/manual/zh/reserved.constants.php#constant.false">false</a></span></strong> otherwise.  </p> </div> <div class="refsect1 examples" id="refsect1-ds-map.haskey-examples">  <h3 class="title">示例</h3>  <div class="example" id="example-1">   <p><strong>示例 #1 <span class="function"><strong style="color:#CC7832">Ds\Map::hasKey()</strong></span> example</strong></p>   <div class="example-contents"><div class="phpcode" style="border-color:gray;background:#1E1F22;"><blockquote style="border:1px gray solid;white-space:pre-wrap"><span style="color: #000000"><span style="color: #9876AA">&lt;?php<br>\$map </span><span style="color: #007700">= new </span><span style="color: #9876AA">\Ds\Map</span><span style="color: #007700">([</span><span style="color: #DD0000">"a" </span><span style="color: #007700">=&gt; </span><span style="color: #9876AA">1</span><span style="color: #007700">, </span><span style="color: #DD0000">"b" </span><span style="color: #007700">=&gt; </span><span style="color: #9876AA">2</span><span style="color: #007700">, </span><span style="color: #DD0000">"c" </span><span style="color: #007700">=&gt; </span><span style="color: #9876AA">3</span><span style="color: #007700">]);<br><br></span><span style="color: #9876AA">var_dump</span><span style="color: #007700">(</span><span style="color: #9876AA">\$map</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">hasKey</span><span style="color: #007700">(</span><span style="color: #DD0000">"a"</span><span style="color: #007700">)); </span><span style="color: #FF8000">// true<br></span><span style="color: #9876AA">var_dump</span><span style="color: #007700">(</span><span style="color: #9876AA">\$map</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">hasKey</span><span style="color: #007700">(</span><span style="color: #DD0000">"e"</span><span style="color: #007700">)); </span><span style="color: #FF8000">// false<br></span><span style="color: #9876AA">?&gt;</span></span></blockquote></div>   </div>   <div class="example-contents"><p>以上示例的输出类似于：</p></div>   <div class="example-contents screen" style="border-color:gray;background:#1E1F22;"><div class="examplescode"><blockquote style="border:1px gray solid;">bool(true)<br>bool(false)</blockquote></div>   </div>  </div> </div></div>
 */
    public function hasKey($key): bool {}

/**
 * <div id="ds-map.hasvalue" class="refentry"> <div class="refnamediv">  <h1 class="refname">Ds\Map::hasValue</h1>  <p class="verinfo">(PECL ds &gt;= 1.0.0)</p><p class="refpurpose"><span class="refname">Ds\Map::hasValue</span> — <span class="dc-title">Determines whether the map contains a given value</span></p> </div> <div class="refsect1 description" id="refsect1-ds-map.hasvalue-description">  <h3 class="title">说明</h3>  <div class="methodsynopsis dc-description">   <span class="modifier">public</span> <span class="modifier">function</span> <span class="methodname" style="color:#CC7832"><strong>Ds\Map::hasValue</strong></span>(<span class="methodparam"><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.mixed.php" class="type mixed" style="color:#EAB766">mixed</a></span> <span class="parameter" style="color:#3A95FF">\$value</span></span>): <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.boolean.php" class="type bool" style="color:#EAB766">bool</a></span></div>  <p class="para rdfs-comment">    Determines whether the map contains a given value.  </p> </div> <div class="refsect1 parameters" id="refsect1-ds-map.hasvalue-parameters">  <h3 class="title">参数</h3>  <dl>       <dt><span class="parameter" style="color:#3A95FF">value</span></dt>    <dd>     <p class="para">        The value to look for.     </p>    </dd>     </dl> </div> <div class="refsect1 returnvalues" id="refsect1-ds-map.hasvalue-returnvalues">  <h3 class="title">返回值</h3>  <p class="simpara">    Returns <strong><span><a href="https://php.net/manual/zh/reserved.constants.php#constant.true">true</a></span></strong> if the value could be found, <strong><span><a href="https://php.net/manual/zh/reserved.constants.php#constant.false">false</a></span></strong> otherwise.  </p> </div> <div class="refsect1 examples" id="refsect1-ds-map.hasvalue-examples">  <h3 class="title">示例</h3>  <div class="example" id="example-1">   <p><strong>示例 #1 <span class="function"><strong style="color:#CC7832">Ds\Map::hasValue()</strong></span> example</strong></p>   <div class="example-contents"><div class="phpcode" style="border-color:gray;background:#1E1F22;"><blockquote style="border:1px gray solid;white-space:pre-wrap"><span style="color: #000000"><span style="color: #9876AA">&lt;?php<br>\$map </span><span style="color: #007700">= new </span><span style="color: #9876AA">\Ds\Map</span><span style="color: #007700">([</span><span style="color: #DD0000">"a" </span><span style="color: #007700">=&gt; </span><span style="color: #9876AA">1</span><span style="color: #007700">, </span><span style="color: #DD0000">"b" </span><span style="color: #007700">=&gt; </span><span style="color: #9876AA">2</span><span style="color: #007700">, </span><span style="color: #DD0000">"c" </span><span style="color: #007700">=&gt; </span><span style="color: #9876AA">3</span><span style="color: #007700">]);<br><br></span><span style="color: #9876AA">var_dump</span><span style="color: #007700">(</span><span style="color: #9876AA">\$map</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">hasValue</span><span style="color: #007700">(</span><span style="color: #9876AA">1</span><span style="color: #007700">)); </span><span style="color: #FF8000">// true<br></span><span style="color: #9876AA">var_dump</span><span style="color: #007700">(</span><span style="color: #9876AA">\$map</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">hasValue</span><span style="color: #007700">(</span><span style="color: #9876AA">4</span><span style="color: #007700">)); </span><span style="color: #FF8000">// false<br></span><span style="color: #9876AA">?&gt;</span></span></blockquote></div>   </div>   <div class="example-contents"><p>以上示例的输出类似于：</p></div>   <div class="example-contents screen" style="border-color:gray;background:#1E1F22;"><div class="examplescode"><blockquote style="border:1px gray solid;">bool(true)<br>bool(false)</blockquote></div>   </div>  </div> </div></div>
 */
    public function hasValue($value): bool {}

/**
 * <div id="ds-map.intersect" class="refentry"> <div class="refnamediv">  <h1 class="refname">Ds\Map::intersect</h1>  <p class="verinfo">(PECL ds &gt;= 1.0.0)</p><p class="refpurpose"><span class="refname">Ds\Map::intersect</span> — <span class="dc-title">Creates a new map by intersecting keys with another map</span></p> </div> <div class="refsect1 description" id="refsect1-ds-map.intersect-description">  <h3 class="title">说明</h3>  <div class="methodsynopsis dc-description">   <span class="modifier">public</span> <span class="modifier">function</span> <span class="methodname" style="color:#CC7832"><strong>Ds\Map::intersect</strong></span>(<span class="methodparam"><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/class.ds-map.php" class="type Ds\Map" style="color:#EAB766">Ds\Map</a></span> <span class="parameter" style="color:#3A95FF">\$map</span></span>): <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/class.ds-map.php" class="type Ds\Map" style="color:#EAB766">Ds\Map</a></span></div>  <p class="para rdfs-comment">    Creates a new map containing the pairs of the current instance whose keys    are also present in the given <span class="parameter" style="color:#3A95FF">map</span>.    In other words, returns a copy of the current instance with all keys removed that    are not also in the other <span class="parameter" style="color:#3A95FF">map</span>.  </p>  <p class="para">    <span class="code">A ∩ B = {x : x ∈ A ∧ x ∈ B}</span>  </p>  <blockquote class="note" style="border:1px gray solid"><p><strong class="note" style="border:1px gray solid">注意</strong>:     </p><p class="para">        Values from the current instance will be kept.    </p>  </blockquote> </div> <div class="refsect1 parameters" id="refsect1-ds-map.intersect-parameters">  <h3 class="title">参数</h3>  <dl>       <dt><span class="parameter" style="color:#3A95FF">map</span></dt>    <dd>     <p class="para">        The other map, containing the keys to intersect with.     </p>    </dd>     </dl> </div> <div class="refsect1 returnvalues" id="refsect1-ds-map.intersect-returnvalues">  <h3 class="title">返回值</h3>    <p class="para">    The key intersection of the current instance and another <span class="parameter" style="color:#3A95FF">map</span>.    </p> </div> <div class="refsect1 seealso" id="refsect1-ds-map.intersect-seealso">  <h3 class="title">参见</h3>  <p class="para">   </p><ul class="simplelist">    <li><a href="https://en.wikipedia.org/wiki/Intersection_(set_theory)" class="link external">»&nbsp;Intersection</a> on Wikipedia</li>   </ul>   </div> <div class="refsect1 examples" id="refsect1-ds-map.intersect-examples">  <h3 class="title">示例</h3>  <div class="example" id="example-1">   <p><strong>示例 #1 <span class="function"><strong style="color:#CC7832">Ds\Map::intersect()</strong></span> example</strong></p>   <div class="example-contents"><div class="phpcode" style="border-color:gray;background:#1E1F22;"><blockquote style="border:1px gray solid;white-space:pre-wrap"><span style="color: #000000"><span style="color: #9876AA">&lt;?php<br>\$a </span><span style="color: #007700">= new </span><span style="color: #9876AA">\Ds\Map</span><span style="color: #007700">([</span><span style="color: #DD0000">"a" </span><span style="color: #007700">=&gt; </span><span style="color: #9876AA">1</span><span style="color: #007700">, </span><span style="color: #DD0000">"b" </span><span style="color: #007700">=&gt; </span><span style="color: #9876AA">2</span><span style="color: #007700">, </span><span style="color: #DD0000">"c" </span><span style="color: #007700">=&gt; </span><span style="color: #9876AA">3</span><span style="color: #007700">]);<br></span><span style="color: #9876AA">\$b </span><span style="color: #007700">= new </span><span style="color: #9876AA">\Ds\Map</span><span style="color: #007700">([</span><span style="color: #DD0000">"b" </span><span style="color: #007700">=&gt; </span><span style="color: #9876AA">4</span><span style="color: #007700">, </span><span style="color: #DD0000">"c" </span><span style="color: #007700">=&gt; </span><span style="color: #9876AA">5</span><span style="color: #007700">, </span><span style="color: #DD0000">"d" </span><span style="color: #007700">=&gt; </span><span style="color: #9876AA">6</span><span style="color: #007700">]);<br><br></span><span style="color: #9876AA">var_dump</span><span style="color: #007700">(</span><span style="color: #9876AA">\$a</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">intersect</span><span style="color: #007700">(</span><span style="color: #9876AA">\$b</span><span style="color: #007700">));<br></span><span style="color: #9876AA">?&gt;</span></span></blockquote></div>   </div>   <div class="example-contents"><p>以上示例的输出类似于：</p></div>   <div class="example-contents screen" style="border-color:gray;background:#1E1F22;"><div class="examplescode"><blockquote style="border:1px gray solid;">object(Ds\Map)#3&nbsp;(2)&nbsp;{<br>&nbsp;&nbsp;[0]=&gt;<br>&nbsp;&nbsp;object(Ds\Pair)#4&nbsp;(2)&nbsp;{<br>&nbsp;&nbsp;&nbsp;&nbsp;["key"]=&gt;<br>&nbsp;&nbsp;&nbsp;&nbsp;string(1)&nbsp;"b"<br>&nbsp;&nbsp;&nbsp;&nbsp;["value"]=&gt;<br>&nbsp;&nbsp;&nbsp;&nbsp;int(2)<br>&nbsp;&nbsp;}<br>&nbsp;&nbsp;[1]=&gt;<br>&nbsp;&nbsp;object(Ds\Pair)#5&nbsp;(2)&nbsp;{<br>&nbsp;&nbsp;&nbsp;&nbsp;["key"]=&gt;<br>&nbsp;&nbsp;&nbsp;&nbsp;string(1)&nbsp;"c"<br>&nbsp;&nbsp;&nbsp;&nbsp;["value"]=&gt;<br>&nbsp;&nbsp;&nbsp;&nbsp;int(3)<br>&nbsp;&nbsp;}<br>}</blockquote></div>   </div>  </div> </div></div>
 */
    public function intersect(Map $map): Map {}

/**
 * <div id="ds-map.isempty" class="refentry"> <div class="refnamediv">  <h1 class="refname">Ds\Map::isEmpty</h1>  <p class="verinfo">(PECL ds &gt;= 1.0.0)</p><p class="refpurpose"><span class="refname">Ds\Map::isEmpty</span> — <span class="dc-title">Returns whether the map is empty</span></p> </div> <div class="refsect1 description" id="refsect1-ds-map.isempty-description">  <h3 class="title">说明</h3>  <div class="methodsynopsis dc-description">   <span class="modifier">public</span> <span class="modifier">function</span> <span class="methodname" style="color:#CC7832"><strong>Ds\Map::isEmpty</strong></span>(): <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.boolean.php" class="type bool" style="color:#EAB766">bool</a></span></div>  <p class="para rdfs-comment">    Returns whether the map is empty.  </p> </div> <div class="refsect1 parameters" id="refsect1-ds-map.isempty-parameters">  <h3 class="title">参数</h3>  <p class="simpara">此函数没有参数。</p> </div> <div class="refsect1 returnvalues" id="refsect1-ds-map.isempty-returnvalues">  <h3 class="title">返回值</h3>  <p class="para">    Returns <strong><span><a href="https://php.net/manual/zh/reserved.constants.php#constant.true">true</a></span></strong> if the map is empty, <strong><span><a href="https://php.net/manual/zh/reserved.constants.php#constant.false">false</a></span></strong> otherwise.  </p> </div> <div class="refsect1 examples" id="refsect1-ds-map.isempty-examples">  <h3 class="title">示例</h3>  <div class="example" id="example-1">   <p><strong>示例 #1 <span class="function"><strong style="color:#CC7832">Ds\Map::isEmpty()</strong></span> example</strong></p>   <div class="example-contents"><div class="phpcode" style="border-color:gray;background:#1E1F22;"><blockquote style="border:1px gray solid;white-space:pre-wrap"><span style="color: #000000"><span style="color: #9876AA">&lt;?php<br>\$a </span><span style="color: #007700">= new </span><span style="color: #9876AA">\Ds\Map</span><span style="color: #007700">([</span><span style="color: #DD0000">"a" </span><span style="color: #007700">=&gt; </span><span style="color: #9876AA">1</span><span style="color: #007700">, </span><span style="color: #DD0000">"b" </span><span style="color: #007700">=&gt; </span><span style="color: #9876AA">2</span><span style="color: #007700">, </span><span style="color: #DD0000">"c" </span><span style="color: #007700">=&gt; </span><span style="color: #9876AA">3</span><span style="color: #007700">]);<br></span><span style="color: #9876AA">\$b </span><span style="color: #007700">= new </span><span style="color: #9876AA">\Ds\Map</span><span style="color: #007700">();<br><br></span><span style="color: #9876AA">var_dump</span><span style="color: #007700">(</span><span style="color: #9876AA">\$a</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">isEmpty</span><span style="color: #007700">());<br></span><span style="color: #9876AA">var_dump</span><span style="color: #007700">(</span><span style="color: #9876AA">\$b</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">isEmpty</span><span style="color: #007700">());<br></span><span style="color: #9876AA">?&gt;</span></span></blockquote></div>   </div>   <div class="example-contents"><p>以上示例的输出类似于：</p></div>   <div class="example-contents screen" style="border-color:gray;background:#1E1F22;"><div class="examplescode"><blockquote style="border:1px gray solid;">bool(false)<br>bool(true)</blockquote></div>   </div>  </div> </div></div>
 */
    public function isEmpty(): bool {}

