/span><span class="initializer"> = ?</span></span>): <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/class.ds-set.php" class="type Ds\Set" style="color:#EAB766">Ds\Set</a></span></div><div class="methodsynopsis dc-description"><span class="modifier">public</span> <span class="modifier">function</span> <span class="methodname" style="color:#CC7832"><a href="https://php.net/manual/zh/ds-set.sum.php" class="methodname" style="color:#CC7832">sum</a></span>(): <span class="type" style="color:#EAB766"><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.integer.php" class="type int" style="color:#EAB766">int</a></span>|<span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.float.php" class="type float" style="color:#EAB766">float</a></span></span></div><div class="methodsynopsis dc-description"><span class="modifier">public</span> <span class="modifier">function</span> <span class="methodname" style="color:#CC7832"><a href="https://php.net/manual/zh/ds-set.toarray.php" class="methodname" style="color:#CC7832">toArray</a></span>(): <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.array.php" class="type array" style="color:#EAB766">array</a></span></div><div class="methodsynopsis dc-description"><span class="modifier">public</span> <span class="modifier">function</span> <span class="methodname" style="color:#CC7832"><a href="https://php.net/manual/zh/ds-set.union.php" class="methodname" style="color:#CC7832">union</a></span>(<span class="methodparam"><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/class.ds-set.php" class="type Ds\Set" style="color:#EAB766">Ds\Set</a></span> <span class="parameter" style="color:#3A95FF">\$set</span></span>): <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/class.ds-set.php" class="type Ds\Set" style="color:#EAB766">Ds\Set</a></span></div><div class="methodsynopsis dc-description"><span class="modifier">public</span> <span class="modifier">function</span> <span class="methodname" style="color:#CC7832"><a href="https://php.net/manual/zh/ds-set.xor.php" class="methodname" style="color:#CC7832">xor</a></span>(<span class="methodparam"><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/class.ds-set.php" class="type Ds\Set" style="color:#EAB766">Ds\Set</a></span> <span class="parameter" style="color:#3A95FF">\$set</span></span>): <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/class.ds-set.php" class="type Ds\Set" style="color:#EAB766">Ds\Set</a></span></div>   }</div>  </div>  <div class="section" id="ds-set.constants">   <h2 class="title">预定义常量</h2>   <dl>         <dt id="ds-set.constants.min-capacity"><strong><span>{@link Ds\Set::MIN_CAPACITY}</span></strong></dt>     <dd>      <p class="para"></p>     </dd>       </dl>  </div>  <div class="section">   <h2 class="title">更新日志</h2>   <p class="para">    </p><table class="doctable informaltable">           <thead>       <tr>        <th>版本</th>        <th>说明</th>       </tr>      </thead>      <tbody class="tbody">       <tr>        <td>PECL ds 1.3.0</td>        <td>         The class now implements <span class="classname"><a href="https://php.net/manual/zh/class.arrayaccess.php" class="classname">ArrayAccess</a></span>.        </td>       </tr>       <tr>        <td>PECL ds 1.2.7</td>        <td>         Added the <span class="methodname" style="color:#CC7832">{@link Ds\Set::map()}</span> method.        </td>       </tr>       <tr>        <td>PECL ds 1.2.0</td>        <td>         <strong><span>{@link Ds\Set::MIN_CAPACITY}</span></strong> changed from 16 to 8.        </td>       </tr>      </tbody>         </table>     </div> </div> <h2>目录</h2><ul class="chunklist chunklist_reference"><li>{@link Ds\Set::add} — Adds values to the set</li><li>{@link Ds\Set::allocate} — Allocates enough memory for a required capacity</li><li>{@link Ds\Set::capacity} — Returns the current capacity</li><li>{@link Ds\Set::clear} — Removes all values</li><li>{@link Ds\Set::__construct} — Creates a new instance</li><li>{@link Ds\Set::contains} — Determines if the set contains all values</li><li>{@link Ds\Set::copy} — Returns a shallow copy of the set</li><li>{@link Ds\Set::count} — Returns the number of values in the set</li><li>{@link Ds\Set::diff} — Creates a new set using values that aren't in another set</li><li>{@link Ds\Set::filter} — Creates a new set using a callable to    determine which values to include</li><li>{@link Ds\Set::first} — Returns the first value in the set</li><li>{@link Ds\Set::get} — Returns the value at a given index</li><li>{@link Ds\Set::intersect} — Creates a new set by intersecting values with another set</li><li>{@link Ds\Set::isEmpty} — Returns whether the set is empty</li><li>{@link Ds\Set::join} — Joins all values together as a string</li><li>{@link Ds\Set::jsonSerialize} — Returns a representation that can be converted to JSON</li><li>{@link Ds\Set::last} — Returns the last value in the set</li><li>{@link Ds\Set::map} — Returns the result of applying a callback to each value</li><li>{@link Ds\Set::merge} — Returns the result of adding all given values to the set</li><li>{@link Ds\Set::reduce} — Reduces the set to a single value using a callback function</li><li>{@link Ds\Set::remove} — Removes all given values from the set</li><li>{@link Ds\Set::reverse} — Reverses the set in-place</li><li>{@link Ds\Set::reversed} — Returns a reversed copy</li><li>{@link Ds\Set::slice} — Returns a sub-set of a given range</li><li>{@link Ds\Set::sort} — Sorts the set in-place</li><li>{@link Ds\Set::sorted} — Returns a sorted copy</li><li>{@link Ds\Set::sum} — Returns the sum of all values in the set</li><li>{@link Ds\Set::toArray} — Converts the set to an array</li><li>{@link Ds\Set::union} — Creates a new set using values from the current instance and another set</li><li>{@link Ds\Set::xor} — Creates a new set using values in either the current instance or in another set, but not in both</li></ul></div>
 * 
 * @template TValue
 * @implements IteratorAggregate<int, TValue>
 * @implements ArrayAccess<int, TValue>
 * @since PECL ds 2.0.0
 */
final class Set implements Countable, IteratorAggregate, JsonSerializable, ArrayAccess
{
    public const MIN_CAPACITY = 8;

/**
 * <div id="ds-set.construct" class="refentry"> <div class="refnamediv">  <h1 class="refname">Ds\Set::__construct</h1>  <p class="verinfo">(PECL ds &gt;= 1.0.0)</p><p class="refpurpose"><span class="refname">Ds\Set::__construct</span> — <span class="dc-title">Creates a new instance</span></p> </div> <div class="refsect1 description" id="refsect1-ds-set.construct-description">  <h3 class="title">说明</h3>  <div class="constructorsynopsis dc-description">   <span class="modifier">public</span> <span class="modifier">function</span> <span class="methodname" style="color:#CC7832"><strong>Ds\Set::__construct</strong></span>(<span class="methodparam"><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.mixed.php" class="type mixed" style="color:#EAB766">mixed</a></span> <span class="parameter" style="color:#3A95FF">\$values</span><span class="initializer"> = []</span></span>)</div>  <p class="para rdfs-comment">    Creates a new instance, using either a <span class="classname"><a href="https://php.net/manual/zh/class.traversable.php" class="classname">traversable</a></span>    object or an <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.array.php" class="type array" style="color:#EAB766">array</a></span> for the initial <span class="parameter" style="color:#3A95FF">values</span>.  </p> </div> <div class="refsect1 parameters" id="refsect1-ds-set.construct-parameters">  <h3 class="title">参数</h3>  <dl>       <dt><span class="parameter" style="color:#3A95FF">values</span></dt>    <dd>     <p class="para">        A traversable object or an <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.array.php" class="type array" style="color:#EAB766">array</a></span> to use for the initial values.     </p>    </dd>     </dl> </div>  <div class="refsect1 examples" id="refsect1-ds-set.construct-examples">  <h3 class="title">示例</h3>  <div class="example" id="example-1">   <p><strong>示例 #1 <span class="function"><strong style="color:#CC7832">Ds\Set::__construct()</strong></span> example</strong></p>   <div class="example-contents"><div class="phpcode" style="border-color:gray;background:#1E1F22;"><blockquote style="border:1px gray solid;white-space:pre-wrap"><span style="color: #000000"><span style="color: #9876AA">&lt;?php<br>\$set </span><span style="color: #007700">= new </span><span style="color: #9876AA">\Ds\Set</span><span style="color: #007700">();<br></span><span style="color: #9876AA">var_dump</span><span style="color: #007700">(</span><span style="color: #9876AA">\$set</span><span style="color: #007700">);<br><br></span><span style="color: #9876AA">\$set </span><span style="color: #007700">= new </span><span style="color: #9876AA">\Ds\Set</span><span style="color: #007700">([</span><span style="color: #9876AA">1</span><span style="color: #007700">, </span><span style="color: #9876AA">2</span><span style="color: #007700">, </span><span style="color: #9876AA">3</span><span style="color: #007700">]);<br></span><span style="color: #9876AA">var_dump</span><span style="color: #007700">(</span><span style="color: #9876AA">\$set</span><span style="color: #007700">);<br></span><span style="color: #9876AA">?&gt;</span></span></blockquote></div>   </div>   <div class="example-contents"><p>以上示例的输出类似于：</p></div>   <div class="example-contents screen" style="border-color:gray;background:#1E1F22;"><div class="examplescode"><blockquote style="border:1px gray solid;">object(Ds\Set)#1&nbsp;(0)&nbsp;{<br>}<br>object(Ds\Set)#2&nbsp;(3)&nbsp;{<br>&nbsp;&nbsp;[0]=&gt;<br>&nbsp;&nbsp;int(1)<br>&nbsp;&nbsp;[1]=&gt;<br>&nbsp;&nbsp;int(2)<br>&nbsp;&nbsp;[2]=&gt;<br>&nbsp;&nbsp;int(3)<br>}</blockquote></div>   </div>  </div> </div></div>
 */
    public function __construct(iterable $values = []) {}

/**
 * <div id="ds-set.add" class="refentry"> <div class="refnamediv">  <h1 class="refname">Ds\Set::add</h1>  <p class="verinfo">(PECL ds &gt;= 1.0.0)</p><p class="refpurpose"><span class="refname">Ds\Set::add</span> — <span class="dc-title">Adds values to the set</span></p> </div> <div class="refsect1 description" id="refsect1-ds-set.add-description">  <h3 class="title">说明</h3>  <div class="methodsynopsis dc-description">   <span class="modifier">public</span> <span class="modifier">function</span> <span class="methodname" style="color:#CC7832"><strong>Ds\Set::add</strong></span>(<span class="methodparam"><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.mixed.php" class="type mixed" style="color:#EAB766">mixed</a></span> <span class="parameter" style="color:#3A95FF">...\$values</span></span>): <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.void.php" class="type void" style="color:#EAB766">void</a></span></div>  <p class="para rdfs-comment">    Adds all given values to the set that haven't already been added.  </p>  <blockquote class="note" style="border:1px gray solid"><p><strong class="note" style="border:1px gray solid">注意</strong>:     </p><p class="para">        Values of type <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.object.php" class="type object" style="color:#EAB766">object</a></span> are supported.        If an object implements <span class="classname"><a href="https://php.net/manual/zh/class.ds-hashable.php" class="classname">Ds\Hashable</a></span>,        equality will be determined by the object's <span class="code">equals</span> function.        If an object does not implement <span class="classname"><a href="https://php.net/manual/zh/class.ds-hashable.php" class="classname">Ds\Hashable</a></span>,        objects must be references to the same instance to be considered equal.    </p>  </blockquote>  <div class="caution"><strong class="caution">警告</strong>    <p class="para">        All comparisons are strict (type and value).    </p>  </div> </div> <div class="refsect1 parameters" id="refsect1-ds-set.add-parameters">  <h3 class="title">参数</h3>  <dl>       <dt><span class="parameter" style="color:#3A95FF">values</span></dt>    <dd>     <p class="para">        Values to add to the set.     </p>    </dd>     </dl> </div> <div class="refsect1 returnvalues" id="refsect1-ds-set.add-returnvalues">  <h3 class="title">返回值</h3>  <p class="para">    没有返回值。  </p> </div> <div class="refsect1 examples" id="refsect1-ds-set.add-examples">  <h3 class="title">示例</h3>  <div class="example" id="example-1">   <p><strong>示例 #1 <span class="function"><strong style="color:#CC7832">Ds\Set::add()</strong></span> example using integers</strong></p>   <div class="example-contents"><div class="phpcode" style="border-color:gray;background:#1E1F22;"><blockquote style="border:1px gray solid;white-space:pre-wrap"><span style="color: #000000"><span style="color: #9876AA">&lt;?php<br>\$set </span><span style="color: #007700">= new </span><span style="color: #9876AA">\Ds\Set</span><span style="color: #007700">();<br><br></span><span style="color: #9876AA">\$set</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">add</span><span style="color: #007700">(</span><span style="color: #9876AA">1</span><span style="color: #007700">);<br></span><span style="color: #9876AA">\$set</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">add</span><span style="color: #007700">(</span><span style="color: #9876AA">1</span><span style="color: #007700">);<br></span><span style="color: #9876AA">\$set</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">add</span><span style="color: #007700">(</span><span style="color: #9876AA">2</span><span style="color: #007700">);<br></span><span style="color: #9876AA">\$set</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">add</span><span style="color: #007700">(</span><span style="color: #9876AA">3</span><span style="color: #007700">);<br><br></span><span style="color: #FF8000">// Strict comparison would not treat these the same as int(1)<br></span><span style="color: #9876AA">\$set</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">add</span><span style="color: #007700">(</span><span style="color: #DD0000">"1"</span><span style="color: #007700">);<br></span><span style="color: #9876AA">\$set</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">add</span><span style="color: #007700">(</span><span style="color: #9876AA">true</span><span style="color: #007700">);<br><br></span><span style="color: #9876AA">var_dump</span><span style="color: #007700">(</span><span style="color: #9876AA">\$set</span><span style="color: #007700">);<br></span><span style="color: #9876AA">?&gt;</span></span></blockquote></div>   </div>   <div class="example-contents"><p>以上示例的输出类似于：</p></div>   <div class="example-contents screen" style="border-color:gray;background:#1E1F22;"><div class="examplescode"><blockquote style="border:1px gray solid;">object(Ds\Set)#1&nbsp;(5)&nbsp;{<br>&nbsp;&nbsp;[0]=&gt;<br>&nbsp;&nbsp;int(1)<br>&nbsp;&nbsp;[1]=&gt;<br>&nbsp;&nbsp;int(2)<br>&nbsp;&nbsp;[2]=&gt;<br>&nbsp;&nbsp;int(3)<br>&nbsp;&nbsp;[3]=&gt;<br>&nbsp;&nbsp;string(1)&nbsp;"1"<br>&nbsp;&nbsp;[4]=&gt;<br>&nbsp;&nbsp;bool(true)<br>}</blockquote></div>   </div>  </div>  <div class="example" id="example-2">   <p><strong>示例 #2 <span class="function"><strong style="color:#CC7832">Ds\Set::add()</strong></span> example using objects</strong></p>   <div class="example-contents"><div class="phpcode" style="border-color:gray;background:#1E1F22;"><blockquote style="border:1px gray solid;white-space:pre-wrap"><span style="color: #000000"><span style="color: #9876AA">&lt;?php<br></span><span style="color: #007700">class </span><span style="color: #9876AA">HashableObject </span><span style="color: #007700">implements </span><span style="color: #9876AA">\Ds\Hashable<br></span><span style="color: #007700">{<br>    </span><span style="color: #FF8000">//*<br>     * An arbitrary value to use as the hash value. Does not define equality.<br>     <br>    </span><span style="color: #007700">private </span><span style="color: #9876AA">\$value</span><span style="color: #007700">;<br><br>    public function </span><span style="color: #9876AA">__construct</span><span style="color: #007700">(</span><span style="color: #9876AA">\$value</span><span style="color: #007700">)<br>    {<br>        </span><span style="color: #9876AA">\$this</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">value </span><span style="color: #007700">= </span><span style="color: #9876AA">\$value</span><span style="color: #007700">;<br>    }<br><br>    public function </span><span style="color: #9876AA">hash</span><span style="color: #007700">()<br>    {<br>        return </span><span style="color: #9876AA">\$this</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">value</span><span style="color: #007700">;<br>    }<br><br>    public function </span><span style="color: #9876AA">equals</span><span style="color: #007700">(</span><span style="color: #9876AA">\$obj</span><span style="color: #007700">): </span><span style="color: #9876AA">bool<br>    </span><span style="color: #007700">{<br>        return </span><span style="color: #9876AA">\$this</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">value </span><span style="color: #007700">=== </span><span style="color: #9876AA">\$obj</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">value</span><span style="color: #007700">;<br>    }<br>}<br><br></span><span style="color: #9876AA">\$set </span><span style="color: #007700">= new </span><span style="color: #9876AA">\Ds\Set</span><span style="color: #007700">();<br><br></span><span style="color: #9876AA">\$obj </span><span style="color: #007700">= new </span><span style="color: #9876AA">\ArrayIterator</span><span style="color: #007700">([]);<br><br></span><span style="color: #FF8000">// Adding the same instance multiple times will only add the first.<br></span><span style="color: #9876AA">\$set</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">add</span><span style="color: #007700">(</span><span style="color: #9876AA">\$obj</span><span style="color: #007700">);<br></span><span style="color: #9876AA">\$set</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">add</span><span style="color: #007700">(</span><span style="color: #9876AA">\$obj</span><span style="color: #007700">);<br><br></span><span style="color: #FF8000">// Adding multiple instances of the same object will add them all.<br></span><span style="color: #9876AA">\$set</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">add</span><span style="color: #007700">(new </span><span style="color: #9876AA">\stdClass</span><span style="color: #007700">());<br></span><span style="color: #9876AA">\$set</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">add</span><span style="color: #007700">(new </span><span style="color: #9876AA">\stdClass</span><span style="color: #007700">());<br><br></span><span style="color: #FF8000">// Adding multiple instances of equal hashable objects will only add the first.<br></span><span style="color: #9876AA">\$set</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">add</span><span style="color: #007700">(new </span><span style="color: #9876AA">\HashableObject</span><span style="color: #007700">(</span><span style="color: #9876AA">1</span><span style="color: #007700">));<br></span><span style="color: #9876AA">\$set</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">add</span><span style="color: #007700">(new </span><span style="color: #9876AA">\HashableObject</span><span style="color: #007700">(</span><span style="color: #9876AA">1</span><span style="color: #007700">));<br></span><span style="color: #9876AA">\$set</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">add</span><span style="color: #007700">(new </span><span style="color: #9876AA">\HashableObject</span><span style="color: #007700">(</span><span style="color: #9876AA">2</span><span style="color: #007700">));<br></span><span style="color: #9876AA">\$set</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">add</span><span style="color: #007700">(new </span><span style="color: #9876AA">\HashableObject</span><span style="color: #007700">(</span><span style="color: #9876AA">2</span><span style="color: #007700">));<br><br></span><span style="color: #9876AA">var_dump</span><span style="color: #007700">(</span><span style="color: #9876AA">\$set</span><span style="color: #007700">);<br></span><span style="color: #9876AA">?&gt;</span></span></blockquote></div>   </div>   <div class="example-contents"><p>以上示例的输出类似于：</p></div>   <div class="example-contents screen" style="border-color:gray;background:#1E1F22;"><div class="examplescode"><blockquote style="border:1px gray solid;">object(Ds\Set)#1&nbsp;(5)&nbsp;{<br>&nbsp;&nbsp;[0]=&gt;<br>&nbsp;&nbsp;object(ArrayIterator)#2&nbsp;(1)&nbsp;{<br>&nbsp;&nbsp;&nbsp;&nbsp;["storage":"ArrayIterator":private]=&gt;<br>&nbsp;&nbsp;&nbsp;&nbsp;array(0)&nbsp;{<br>&nbsp;&nbsp;&nbsp;&nbsp;}<br>&nbsp;&nbsp;}<br>&nbsp;&nbsp;[1]=&gt;<br>&nbsp;&nbsp;object(stdClass)#3&nbsp;(0)&nbsp;{<br>&nbsp;&nbsp;}<br>&nbsp;&nbsp;[2]=&gt;<br>&nbsp;&nbsp;object(stdClass)#4&nbsp;(0)&nbsp;{<br>&nbsp;&nbsp;}<br>&nbsp;&nbsp;[3]=&gt;<br>&nbsp;&nbsp;object(HashableObject)#5&nbsp;(1)&nbsp;{<br>&nbsp;&nbsp;&nbsp;&nbsp;["value":"HashableObject":private]=&gt;<br>&nbsp;&nbsp;&nbsp;&nbsp;int(1)<br>&nbsp;&nbsp;}<br>&nbsp;&nbsp;[4]=&gt;<br>&nbsp;&nbsp;object(HashableObject)#6&nbsp;(1)&nbsp;{<br>&nbsp;&nbsp;&nbsp;&nbsp;["value":"HashableObject":private]=&gt;<br>&nbsp;&nbsp;&nbsp;&nbsp;int(2)<br>&nbsp;&nbsp;}<br>}</blockquote></div>   </div>  </div> </div></div>
 */
    public function add(...$values): void {}

/**
 * <div id="ds-set.allocate" class="refentry"> <div class="refnamediv">  <h1 class="refname">Ds\Set::allocate</h1>  <p class="verinfo">(PECL ds &gt;= 1.0.0)</p><p class="refpurpose"><span class="refname">Ds\Set::allocate</span> — <span class="dc-title">Allocates enough memory for a required capacity</span></p> </div> <div class="refsect1 description" id="refsect1-ds-set.allocate-description">  <h3 class="title">说明</h3>  <div class="methodsynopsis dc-description">   <span class="modifier">public</span> <span class="modifier">function</span> <span class="methodname" style="color:#CC7832"><strong>Ds\Set::allocate</strong></span>(<span class="methodparam"><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.integer.php" class="type int" style="color:#EAB766">int</a></span> <span class="parameter" style="color:#3A95FF">\$capacity</span></span>): <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.void.php" class="type void" style="color:#EAB766">void</a></span></div>  <p class="para rdfs-comment">    Allocates enough memory for a required capacity.  </p> </div> <div class="refsect1 parameters" id="refsect1-ds-set.allocate-parameters">  <h3 class="title">参数</h3>  <dl>       <dt><span class="parameter" style="color:#3A95FF">capacity</span></dt>    <dd>     <p class="para">        The number of values for which capacity should be allocated.     </p>     <blockquote class="note" style="border:1px gray solid"><p><strong class="note" style="border:1px gray solid">注意</strong>:         </p><p class="para">            Capacity will stay the same if this value is less than or equal to the            current capacity.        </p>     </blockquote>     <blockquote class="note" style="border:1px gray solid"><p><strong class="note" style="border:1px gray solid">注意</strong>:         </p><p class="para">            Capacity will always be rounded up to the nearest power of 2.        </p>     </blockquote>    </dd>     </dl> </div> <div class="refsect1 returnvalues" id="refsect1-ds-set.allocate-returnvalues">  <h3 class="title">返回值</h3>  <p class="para">    没有返回值。  </p> </div> <div class="refsect1 examples" id="refsect1-ds-set.allocate-examples">  <h3 class="title">示例</h3>  <div class="example" id="example-1">   <p><strong>示例 #1 <span class="function"><strong style="color:#CC7832">Ds\Set::allocate()</strong></span> example</strong></p>   <div class="example-contents"><div class="phpcode" style="border-color:gray;background:#1E1F22;"><blockquote style="border:1px gray solid;white-space:pre-wrap"><span style="color: #000000"><span style="color: #9876AA">&lt;?php<br>\$set </span><span style="color: #007700">= new </span><span style="color: #9876AA">\Ds\Set</span><span style="color: #007700">();<br></span><span style="color: #9876AA">var_dump</span><span style="color: #007700">(</span><span style="color: #9876AA">\$set</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">capacity</span><span style="color: #007700">());<br><br></span><span style="color: #9876AA">\$set</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">allocate</span><span style="color: #007700">(</span><span style="color: #9876AA">100</span><span style="color: #007700">);<br></span><span style="color: #9876AA">var_dump</span><span style="color: #007700">(</span><span style="color: #9876AA">\$set</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">capacity</span><span style="color: #007700">());<br></span><span style="color: #9876AA">?&gt;</span></span></blockquote></div>   </div>   <div class="example-contents"><p>以上示例的输出类似于：</p></div>   <div class="example-contents screen" style="border-color:gray;background:#1E1F22;"><div class="examplescode"><blockquote style="border:1px gray solid;">int(16)<br>int(128)</blockquote></div>   </div>  </div> </div></div>
 */
    public function allocate(int $capacity): void {}

/**
 * <div id="ds-set.capacity" class="refentry"> <div class="refnamediv">  <h1 class="refname">Ds\Set::capacity</h1>  <p class="verinfo">(PECL ds &gt;= 1.0.0)</p><p class="refpurpose"><span class="refname">Ds\Set::capacity</span> — <span class="dc-title">Returns the current capacity</span></p> </div> <div class="refsect1 description" id="refsect1-ds-set.capacity-description">  <h3 class="title">说明</h3>  <div class="methodsynopsis dc-description">   <span class="modifier">public</span> <span class="modifier">function</span> <span class="methodname" style="color:#CC7832"><strong>Ds\Set::capacity</strong></span>(): <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.integer.php" class="type int" style="color:#EAB766">int</a></span></div>  <p class="para rdfs-comment">    Returns the current capacity.  </p> </div> <div class="refsect1 parameters" id="refsect1-ds-set.capacity-parameters">  <h3 class="title">参数</h3>  <p class="simpara">此函数没有参数。</p> </div> <div class="refsect1 returnvalues" id="refsect1-ds-set.capacity-returnvalues">  <h3 class="title">返回值</h3>  <p class="para">    The current capacity.  </p> </div> <div class="refsect1 examples" id="refsect1-ds-set.capacity-examples">  <h3 class="title">示例</h3>  <div class="example" id="example-1">   <p><strong>示例 #1 <span class="function"><strong style="color:#CC7832">Ds\Set::capacity()</strong></span> example</strong></p>   <div class="example-contents"><div class="phpcode" style="border-color:gray;background:#1E1F22;"><blockquote style="border:1px gray solid;white-space:pre-wrap"><span style="color: #000000"><span style="color: #9876AA">&lt;?php<br>\$set </span><span style="color: #007700">= new </span><span style="color: #9876AA">\Ds\Set</span><span style="color: #007700">();<br></span><span style="color: #9876AA">var_dump</span><span style="color: #007700">(</span><span style="color: #9876AA">\$set</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">capacity</span><span style="color: #007700">());<br><br></span><span style="color: #9876AA">\$set</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">add</span><span style="color: #007700">(...</span><span style="color: #9876AA">range</span><span style="color: #007700">(</span><span style="color: #9876AA">1</span><span style="color: #007700">, </span><span style="color: #9876AA">50</span><span style="color: #007700">));<br></span><span style="color: #9876AA">var_dump</span><span style="color: #007700">(</span><span style="color: #9876AA">\$set</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">capacity</span><span style="color: #007700">());<br></span><span style="color: #9876AA">?&gt;</span></span></blockquote></div>   </div>   <div class="example-contents"><p>以上示例的输出类似于：</p></div>   <div class="example-contents screen" style="border-color:gray;background:#1E1F22;"><div class="examplescode"><blockquote style="border:1px gray solid;">int(16)<br>int(64)</blockquote></div>   </div>  </div> </div></div>
 */
    public function capacity(): int {}

/**
 * <div id="ds-set.clear" class="refentry"> <div class="refnamediv">  <h1 class="refname">Ds\Set::clear</h1>  <p class="verinfo">(PECL ds &gt;= 1.0.0)</p><p class="refpurpose"><span class="refname">Ds\Set::clear</span> — <span class="dc-title">Removes all values</span></p> </div> <div class="refsect1 description" id="refsect1-ds-set.clear-description">  <h3 class="title">说明</h3>  <div class="methodsynopsis dc-description">   <span class="modifier">public</span> <span class="modifier">function</span> <span class="methodname" style="color:#CC7832"><strong>Ds\Set::clear</strong></span>(): <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.void.php" class="type void" style="color:#EAB766">void</a></span></div>  <p class="para rdfs-comment">    Removes all values from the set.  </p> </div> <div class="refsect1 parameters" id="refsect1-ds-set.clear-parameters">  <h3 class="title">参数</h3>  <p class="simpara">此函数没有参数。</p> </div> <div class="refsect1 returnvalues" id="refsect1-ds-set.clear-returnvalues">  <h3 class="title">返回值</h3>  <p class="para">   没有返回值。  </p> </div> <div class="refsect1 examples" id="refsect1-ds-set.clear-examples">  <h3 class="title">示例</h3>  <div class="example" id="example-1">   <p><strong>示例 #1 <span class="function"><strong style="color:#CC7832">Ds\Set::clear()</strong></span> example</strong></p>   <div class="example-contents"><div class="phpcode" style="border-color:gray;background:#1E1F22;"><blockquote style="border:1px gray solid;white-space:pre-wrap"><span style="color: #000000"><span style="color: #9876AA">&lt;?php<br>\$set </span><span style="color: #007700">= new </span><span style="color: #9876AA">\Ds\Set</span><span style="color: #007700">([</span><span style="color: #9876AA">1</span><span style="color: #007700">, </span><span style="color: #9876AA">2</span><span style="color: #007700">, </span><span style="color: #9876AA">3</span><span style="color: #007700">]);<br></span><span style="color: #9876AA">print_r</span><span style="color: #007700">(</span><span style="color: #9876AA">\$set</span><span style="color: #007700">);<br><br></span><span style="color: #9876AA">\$set</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">clear</span><span style="color: #007700">();<br></span><span style="color: #9876AA">print_r</span><span style="color: #007700">(</span><span style="color: #9876AA">\$set</span><span style="color: #007700">);<br></span><span style="color: #9876AA">?&gt;</span></span></blockquote></div>   </div>   <div class="example-contents"><p>以上示例的输出类似于：</p></div>   <div class="example-contents screen" style="border-color:gray;background:#1E1F22;"><div class="examplescode"><blockquote style="border:1px gray solid;">Ds\Set&nbsp;Object<br>(<br>&nbsp;&nbsp;&nbsp;&nbsp;[0]&nbsp;=&gt;&nbsp;1<br>&nbsp;&nbsp;&nbsp;&nbsp;[1]&nbsp;=&gt;&nbsp;2<br>&nbsp;&nbsp;&nbsp;&nbsp;[2]&nbsp;=&gt;&nbsp;3<br>)<br>Ds\Set&nbsp;Object<br>(<br>)</blockquote></div>   </div>  </div> </div></div>
 */
    public function clear(): void {}

/**
 * <div id="ds-set.contains" class="refentry"> <div class="refnamediv">  <h1 class="refname">Ds\Set::contains</h1>  <p class="verinfo">(PECL ds &gt;= 1.0.0)</p><p class="refpurpose"><span class="refname">Ds\Set::contains</span> — <span class="dc-title">Determines if the set contains all values</span></p> </div> <div class="refsect1 description" id="refsect1-ds-set.contains-description">  <h3 class="title">说明</h3>  <div class="methodsynopsis dc-description">   <span class="modifier">public</span> <span class="modifier">function</span> <span class="methodname" style="color:#CC7832"><strong>Ds\Set::contains</strong></span>(<span class="methodparam"><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.mixed.php" class="type mixed" style="color:#EAB766">mixed</a></span> <span class="parameter" style="color:#3A95FF">...\$values</span></span>): <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.boolean.php" class="type bool" style="color:#EAB766">bool</a></span></div>  <p class="para rdfs-comment">    Determines if the set contains all values.  </p>  <blockquote class="note" style="border:1px gray solid"><p><strong class="note" style="border:1px gray solid">注意</strong>:     </p><p class="para">        Values of type <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.object.php" class="type object" style="color:#EAB766">object</a></span> are supported.        If an object implements <span class="classname"><a href="https://php.net/manual/zh/class.ds-hashable.php" class="classname">Ds\Hashable</a></span>,        equality will be determined by the object's <span class="code">equals</span> function.        If an object does not implement <span class="classname"><a href="https://php.net/manual/zh/class.ds-hashable.php" class="classname">Ds\Hashable</a></span>,        objects must be references to the same instance to be considered equal.    </p>  </blockquote>  <div class="caution"><strong class="caution">警告</strong>    <p class="para">        All comparisons are strict (type and value).    </p>  </div> </div> <div class="refsect1 parameters" id="refsect1-ds-set.contains-parameters">  <h3 class="title">参数</h3>  <dl>       <dt><span class="parameter" style="color:#3A95FF">values</span></dt>    <dd>     <p class="para">        Values to check.     </p>    </dd>     </dl> </div> <div class="refsect1 returnvalues" id="refsect1-ds-set.contains-returnvalues">  <h3 class="title">返回值</h3>  <p class="para">    <strong><span><a href="https://php.net/manual/zh/reserved.constants.php#constant.false">false</a></span></strong> if any of the provided <span class="parameter" style="color:#3A95FF">values</span> are not in the    set, <strong><span><a href="https://php.net/manual/zh/reserved.constants.php#constant.true">true</a></span></strong> otherwise.  </p> </div> <div class="refsect1 examples" id="refsect1-ds-set.contains-examples">  <h3 class="title">示例</h3>  <div class="example" id="example-1">   <p><strong>示例 #1 <span class="function"><strong style="color:#CC7832">Ds\Set::contains()</strong></span> example</strong></p>   <div class="example-contents"><div class="phpcode" style="border-color:gray;background:#1E1F22;"><blockquote style="border:1px gray solid;white-space:pre-wrap"><span style="color: #000000"><span style="color: #9876AA">&lt;?php<br>\$set </span><span style="color: #007700">= new </span><span style="color: #9876AA">\Ds\Set</span><span style="color: #007700">([</span><span style="color: #9876AA">1</span><span style="color: #007700">, </span><span style="color: #9876AA">2</span><span style="color: #007700">, </span><span style="color: #9876AA">3</span><span style="color: #007700">]);<br><br></span><span style="color: #9876AA">var_dump</span><span style="color: #007700">(</span><span style="color: #9876AA">\$set</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">contains</span><span style="color: #007700">(</span><span style="color: #9876AA">1</span><span style="color: #007700">));                </span><span style="color: #FF8000">// true<br></span><span style="color: #9876AA">var_dump</span><span style="color: #007700">(</span><span style="color: #9876AA">\$set</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">contains</span><span style="color: #007700">(</span><span style="color: #9876AA">1</span><span style="color: #007700">, </span><span style="color: #9876AA">2</span><span style="color: #007700">));             </span><span style="color: #FF8000">// true<br></span><span style="color: #9876AA">var_dump</span><span style="color: #007700">(</span><span style="color: #9876AA">\$set</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">contains</span><span style="color: #007700">(...[</span><span style="color: #9876AA">1</span><span style="color: #007700">, </span><span style="color: #9876AA">2</span><span style="color: #007700">]));        </span><span style="color: #FF8000">// true<br><br></span><span style="color: #9876AA">var_dump</span><span style="color: #007700">(</span><span style="color: #9876AA">\$set</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">contains</span><span style="color: #007700">(</span><span style="color: #DD0000">"1"</span><span style="color: #007700">));              </span><span style="color: #FF8000">// false<br></span><span style="color: #9876AA">var_dump</span><span style="color: #007700">(</span><span style="color: #9876AA">\$set</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">contains</span><span style="color: #007700">(...[</span><span style="color: #9876AA">1</span><span style="color: #007700">, </span><span style="color: #9876AA">2</span><span style="color: #007700">, </span><span style="color: #9876AA">3</span><span style="color: #007700">, </span><span style="color: #9876AA">4</span><span style="color: #007700">]));  </span><span style="color: #FF8000">// false<br><br></span><span style="color: #9876AA">var_dump</span><span style="color: #007700">(</span><span style="color: #9876AA">\$set</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">contains</span><span style="color: #007700">(...[]));            </span><span style="color: #FF8000">// true<br></span><span style="color: #9876AA">?&gt;</span></span></blockquote></div>   </div>   <div class="example-contents"><p>以上示例的输出类似于：</p></div>   <div class="example-contents screen" style="border-color:gray;background:#1E1F22;"><div class="examplescode"><blockquote style="border:1px gray solid;">bool(true)<br>bool(true)<br>bool(true)<br>bool(false)<br>bool(false)<br>bool(true)</blockquote></div>   </div>  </div> </div></div>
 */
    public function contains(...$values): bool {}

/**
 * <div id="ds-set.copy" class="refentry"> <div class="refnamediv">  <h1 class="refname">Ds\Set::copy</h1>  <p class="verinfo">(PECL ds &gt;= 1.0.0)</p><p class="refpurpose"><span class="refname">Ds\Set::copy</span> — <span class="dc-title">Returns a shallow copy of the set</span></p> </div> <div class="refsect1 description" id="refsect1-ds-set.copy-description">  <h3 class="title">说明</h3>  <div class="methodsynopsis dc-description">   <span class="modifier">public</span> <span class="modifier">function</span> <span class="methodname" style="color:#CC7832"><strong>Ds\Set::copy</strong></span>(): <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/class.ds-set.php" class="type Ds\Set" style="color:#EAB766">Ds\Set</a></span></div>  <p class="para rdfs-comment">    Returns a shallow copy of the set.  </p> </div> <div class="refsect1 parameters" id="refsect1-ds-set.copy-parameters">  <h3 class="title">参数</h3>  <p class="simpara">此函数没有参数。</p> </div> <div class="refsect1 returnvalues" id="refsect1-ds-set.copy-returnvalues">  <h3 class="title">返回值</h3>  <p class="para">   Returns a shallow copy of the set.  </p> </div> <div class="refsect1 examples" id="refsect1-ds-set.copy-examples">  <h3 class="title">示例</h3>  <div class="example" id="example-1">   <p><strong>示例 #1 <span class="function"><strong style="color:#CC7832">Ds\Set::copy()</strong></span> example</strong></p>   <div class="example-contents"><div class="phpcode" style="border-color:gray;background:#1E1F22;"><blockquote style="border:1px gray solid;white-space:pre-wrap"><span style="color: #000000"><span style="color: #9876AA">&lt;?php<br>\$a </span><span style="color: #007700">= new </span><span style="color: #9876AA">\Ds\Set</span><span style="color: #007700">([</span><span style="color: #9876AA">1</span><span style="color: #007700">, </span><span style="color: #9876AA">2</span><span style="color: #007700">, </span><span style="color: #9876AA">3</span><span style="color: #007700">]);<br></span><span style="color: #9876AA">\$b </span><span style="color: #007700">= </span><span style="color: #9876AA">\$a</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">copy</span><span style="color: #007700">();<br><br></span><span style="color: #FF8000">// Updating the copy doesn't affect the original<br></span><span style="color: #9876AA">\$b</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">add</span><span style="color: #007700">(</span><span style="color: #9876AA">4</span><span style="color: #007700">);<br><br></span><span style="color: #9876AA">print_r</span><span style="color: #007700">(</span><span style="color: #9876AA">\$a</span><span style="color: #007700">);<br></span><span style="color: #9876AA">print_r</span><span style="color: #007700">(</span><span style="color: #9876AA">\$b</span><span style="color: #007700">);<br></span><span style="color: #9876AA">?&gt;</span></span></blockquote></div>   </div>   <div class="example-contents"><p>以上示例的输出类似于：</p></div>   <div class="example-contents screen" style="border-color:gray;background:#1E1F22;"><div class="examplescode"><blockquote style="border:1px gray solid;">Ds\Set&nbsp;Object<br>(<br>&nbsp;&nbsp;&nbsp;&nbsp;[0]&nbsp;=&gt;&nbsp;1<br>&nbsp;&nbsp;&nbsp;&nbsp;[1]&nbsp;=&gt;&nbsp;2<br>&nbsp;&nbsp;&nbsp;&nbsp;[2]&nbsp;=&gt;&nbsp;3<br>)<br>Ds\Set&nbsp;Object<br>(<br>&nbsp;&nbsp;&nbsp;&nbsp;[0]&nbsp;=&gt;&nbsp;1<br>&nbsp;&nbsp;&nbsp;&nbsp;[1]&nbsp;=&gt;&nbsp;2<br>&nbsp;&nbsp;&nbsp;&nbsp;[2]&nbsp;=&gt;&nbsp;3<br>&nbsp;&nbsp;&nbsp;&nbsp;[3]&nbsp;=&gt;&nbsp;4<br>)</blockquote></div>   </div>  </div> </div></div>
 */
    public function copy(): Set {}

