/**
 * <div id="ds-set.diff" class="refentry"> <div class="refnamediv">  <h1 class="refname">Ds\Set::diff</h1>  <p class="verinfo">(PECL ds &gt;= 1.0.0)</p><p class="refpurpose"><span class="refname">Ds\Set::diff</span> — <span class="dc-title">Creates a new set using values that aren't in another set</span></p> </div> <div class="refsect1 description" id="refsect1-ds-set.diff-description">  <h3 class="title">说明</h3>  <div class="methodsynopsis dc-description">   <span class="modifier">public</span> <span class="modifier">function</span> <span class="methodname" style="color:#CC7832"><strong>Ds\Set::diff</strong></span>(<span class="methodparam"><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/class.ds-set.php" class="type Ds\Set" style="color:#EAB766">Ds\Set</a></span> <span class="parameter" style="color:#3A95FF">\$set</span></span>): <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/class.ds-set.php" class="type Ds\Set" style="color:#EAB766">Ds\Set</a></span></div>  <p class="para rdfs-comment">    Creates a new set using values that aren't in another set.  </p>  <p class="para">    <span class="code">A \ B = {x ∈ A | x ∉ B}</span>  </p> </div> <div class="refsect1 parameters" id="refsect1-ds-set.diff-parameters">  <h3 class="title">参数</h3>  <dl>       <dt><span class="parameter" style="color:#3A95FF">set</span></dt>    <dd>     <p class="para">        Set containing the values to exclude.     </p>    </dd>     </dl> </div> <div class="refsect1 returnvalues" id="refsect1-ds-set.diff-returnvalues">  <h3 class="title">返回值</h3>  <p class="para">    A new set containing all values that were not in the other <span class="parameter" style="color:#3A95FF">set</span>.  </p> </div> <div class="refsect1 seealso" id="refsect1-ds-set.diff-seealso">  <h3 class="title">参见</h3>  <p class="para">   </p><ul class="simplelist">    <li><a href="https://en.wikipedia.org/wiki/Complement_(set_theory)" class="link external">»&nbsp;Complement</a> on Wikipedia</li>   </ul>   </div> <div class="refsect1 examples" id="refsect1-ds-set.diff-examples">  <h3 class="title">示例</h3>  <div class="example" id="example-1">   <p><strong>示例 #1 <span class="function"><strong style="color:#CC7832">Ds\Set::diff()</strong></span> example</strong></p>   <div class="example-contents"><div class="phpcode" style="border-color:gray;background:#1E1F22;"><blockquote style="border:1px gray solid;white-space:pre-wrap"><span style="color: #000000"><span style="color: #9876AA">&lt;?php<br>\$a </span><span style="color: #007700">= new </span><span style="color: #9876AA">\Ds\Set</span><span style="color: #007700">([</span><span style="color: #9876AA">1</span><span style="color: #007700">, </span><span style="color: #9876AA">2</span><span style="color: #007700">, </span><span style="color: #9876AA">3</span><span style="color: #007700">]);<br></span><span style="color: #9876AA">\$b </span><span style="color: #007700">= new </span><span style="color: #9876AA">\Ds\Set</span><span style="color: #007700">([</span><span style="color: #9876AA">3</span><span style="color: #007700">, </span><span style="color: #9876AA">4</span><span style="color: #007700">, </span><span style="color: #9876AA">5</span><span style="color: #007700">]);<br><br></span><span style="color: #9876AA">var_dump</span><span style="color: #007700">(</span><span style="color: #9876AA">\$a</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">diff</span><span style="color: #007700">(</span><span style="color: #9876AA">\$b</span><span style="color: #007700">));<br></span><span style="color: #9876AA">?&gt;</span></span></blockquote></div>   </div>   <div class="example-contents"><p>以上示例的输出类似于：</p></div>   <div class="example-contents screen" style="border-color:gray;background:#1E1F22;"><div class="examplescode"><blockquote style="border:1px gray solid;">object(Ds\Set)#3&nbsp;(2)&nbsp;{<br>&nbsp;&nbsp;[0]=&gt;<br>&nbsp;&nbsp;int(1)<br>&nbsp;&nbsp;[1]=&gt;<br>&nbsp;&nbsp;int(2)<br>}</blockquote></div>   </div>  </div> </div></div>
 */
    public function diff(Set $set): Set {}

    /**
 * <div id="ds-set.filter" class="refentry"> <div class="refnamediv">  <h1 class="refname">Ds\Set::filter</h1>  <p class="verinfo">(PECL ds &gt;= 1.0.0)</p><p class="refpurpose"><span class="refname">Ds\Set::filter</span> — <span class="dc-title">    Creates a new set using a <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.callable.php" class="type callable" style="color:#EAB766">callable</a></span> to    determine which values to include  </span></p> </div> <div class="refsect1 description" id="refsect1-ds-set.filter-description">  <h3 class="title">说明</h3>  <div class="methodsynopsis dc-description"><span class="modifier">public</span> <span class="modifier">function</span> <span class="methodname" style="color:#CC7832"><strong>Ds\Set::filter</strong></span>(<span class="methodparam"><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.callable.php" class="type callable" style="color:#EAB766">callable</a></span> <span class="parameter" style="color:#3A95FF">\$callback</span><span class="initializer"> = ?</span></span>): <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/class.ds-set.php" class="type Ds\Set" style="color:#EAB766">Ds\Set</a></span></div>  <p class="para rdfs-comment">    Creates a new set using a <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.callable.php" class="type callable" style="color:#EAB766">callable</a></span> to    determine which values to include.  </p> </div> <div class="refsect1 parameters" id="refsect1-ds-set.filter-parameters">  <h3 class="title">参数</h3>  <dl>       <dt><span class="parameter" style="color:#3A95FF">callback</span></dt>    <dd>        <p class="para">            </p><div class="methodsynopsis dc-description">                <span class="modifier">function</span> <span class="methodname" style="color:#CC7832"><span class="replaceable">callback</span></span>(<span class="methodparam"><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.mixed.php" class="type mixed" style="color:#EAB766">mixed</a></span> <span class="parameter" style="color:#3A95FF">\$value</span></span>): <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.boolean.php" class="type bool" style="color:#EAB766">bool</a></span></div>                <p class="para">            Optional <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.callable.php" class="type callable" style="color:#EAB766">callable</a></span> which returns <strong><span><a href="https://php.net/manual/zh/reserved.constants.php#constant.true">true</a></span></strong> if the value should be included, <strong><span><a href="https://php.net/manual/zh/reserved.constants.php#constant.false">false</a></span></strong> otherwise.        </p>        <p class="para">            If a callback is not provided, only values which are <strong><span><a href="https://php.net/manual/zh/reserved.constants.php#constant.true">true</a></span></strong>            (see <a href="https://php.net/manual/zh/language.types.boolean.php#language.types.boolean.casting" class="link">converting to boolean</a>)            will be included.        </p>    </dd>     </dl> </div> <div class="refsect1 returnvalues" id="refsect1-ds-set.filter-returnvalues">  <h3 class="title">返回值</h3>  <p class="para">    A new set containing all the values for which    either the <span class="parameter" style="color:#3A95FF">callback</span> returned <strong><span><a href="https://php.net/manual/zh/reserved.constants.php#constant.true">true</a></span></strong>, or all values that    convert to <strong><span><a href="https://php.net/manual/zh/reserved.constants.php#constant.true">true</a></span></strong> if a <span class="parameter" style="color:#3A95FF">callback</span> was not provided.  </p> </div> <div class="refsect1 examples" id="refsect1-ds-set.filter-examples">  <h3 class="title">示例</h3>  <div class="example" id="example-1">   <p><strong>示例 #1 <span class="function"><strong style="color:#CC7832">Ds\Set::filter()</strong></span> example using callback function</strong></p>   <div class="example-contents"><div class="phpcode" style="border-color:gray;background:#1E1F22;"><blockquote style="border:1px gray solid;white-space:pre-wrap"><span style="color: #000000"><span style="color: #9876AA">&lt;?php<br>\$set </span><span style="color: #007700">= new </span><span style="color: #9876AA">\Ds\Set</span><span style="color: #007700">([</span><span style="color: #9876AA">1</span><span style="color: #007700">, </span><span style="color: #9876AA">2</span><span style="color: #007700">, </span><span style="color: #9876AA">3</span><span style="color: #007700">, </span><span style="color: #9876AA">4</span><span style="color: #007700">, </span><span style="color: #9876AA">5</span><span style="color: #007700">]);<br><br></span><span style="color: #9876AA">var_dump</span><span style="color: #007700">(</span><span style="color: #9876AA">\$set</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">filter</span><span style="color: #007700">(function(</span><span style="color: #9876AA">\$value</span><span style="color: #007700">) {<br>    return </span><span style="color: #9876AA">\$value </span><span style="color: #007700">% </span><span style="color: #9876AA">2 </span><span style="color: #007700">== </span><span style="color: #9876AA">0</span><span style="color: #007700">;<br>}));<br></span><span style="color: #9876AA">?&gt;</span></span></blockquote></div>   </div>   <div class="example-contents"><p>以上示例的输出类似于：</p></div>   <div class="example-contents screen" style="border-color:gray;background:#1E1F22;"><div class="examplescode"><blockquote style="border:1px gray solid;">object(Ds\Set)#3&nbsp;(2)&nbsp;{<br>&nbsp;&nbsp;[0]=&gt;<br>&nbsp;&nbsp;int(2)<br>&nbsp;&nbsp;[1]=&gt;<br>&nbsp;&nbsp;int(4)<br>}</blockquote></div>   </div>  </div>  <div class="example" id="example-2">   <p><strong>示例 #2 <span class="function"><strong style="color:#CC7832">Ds\Set::filter()</strong></span> example without a callback function</strong></p>   <div class="example-contents"><div class="phpcode" style="border-color:gray;background:#1E1F22;"><blockquote style="border:1px gray solid;white-space:pre-wrap"><span style="color: #000000"><span style="color: #9876AA">&lt;?php<br>\$set </span><span style="color: #007700">= new </span><span style="color: #9876AA">\Ds\Set</span><span style="color: #007700">([</span><span style="color: #9876AA">0</span><span style="color: #007700">, </span><span style="color: #9876AA">1</span><span style="color: #007700">, </span><span style="color: #DD0000">'a'</span><span style="color: #007700">, </span><span style="color: #9876AA">true</span><span style="color: #007700">, </span><span style="color: #9876AA">false</span><span style="color: #007700">]);<br><br></span><span style="color: #9876AA">var_dump</span><span style="color: #007700">(</span><span style="color: #9876AA">\$set</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">filter</span><span style="color: #007700">());<br></span><span style="color: #9876AA">?&gt;</span></span></blockquote></div>   </div>   <div class="example-contents"><p>以上示例的输出类似于：</p></div>   <div class="example-contents screen" style="border-color:gray;background:#1E1F22;"><div class="examplescode"><blockquote style="border:1px gray solid;">object(Ds\Set)#2&nbsp;(3)&nbsp;{<br>&nbsp;&nbsp;[0]=&gt;<br>&nbsp;&nbsp;int(1)<br>&nbsp;&nbsp;[1]=&gt;<br>&nbsp;&nbsp;string(1)&nbsp;"a"<br>&nbsp;&nbsp;[2]=&gt;<br>&nbsp;&nbsp;bool(true)<br>}</blockquote></div>   </div>  </div> </div></div>
 * 
     * @param null|callable(TValue): bool $callback
     * @return Set<TValue>
     */
    public function filter(?callable $callback = null): Set {}

