    public function first() {}

/**
 * <div id="ds-set.get" class="refentry"> <div class="refnamediv">  <h1 class="refname">Ds\Set::get</h1>  <p class="verinfo">(PECL ds &gt;= 1.0.0)</p><p class="refpurpose"><span class="refname">Ds\Set::get</span> — <span class="dc-title">Returns the value at a given index</span></p> </div> <div class="refsect1 description" id="refsect1-ds-set.get-description">  <h3 class="title">说明</h3>  <div class="methodsynopsis dc-description">   <span class="modifier">public</span> <span class="modifier">function</span> <span class="methodname" style="color:#CC7832"><strong>Ds\Set::get</strong></span>(<span class="methodparam"><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.integer.php" class="type int" style="color:#EAB766">int</a></span> <span class="parameter" style="color:#3A95FF">\$index</span></span>): <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.mixed.php" class="type mixed" style="color:#EAB766">mixed</a></span></div>  <p class="para rdfs-comment">    Returns the value at a given index.  </p> </div> <div class="refsect1 parameters" id="refsect1-ds-set.get-parameters">  <h3 class="title">参数</h3>  <dl>       <dt><span class="parameter" style="color:#3A95FF">index</span></dt>    <dd>     <p class="para">        The index to access, starting at 0.     </p>    </dd>     </dl> </div> <div class="refsect1 returnvalues" id="refsect1-ds-set.get-returnvalues">  <h3 class="title">返回值</h3>  <p class="para">    The value at the requested index.  </p> </div> <div class="refsect1 errors" id="refsect1-ds-set.get-errors">  <h3 class="title">错误／异常</h3>  <p class="para">   <span class="classname"><a href="https://php.net/manual/zh/class.outofrangeexception.php" class="classname">OutOfRangeException</a></span> if the index is not valid.  </p> </div> <div class="refsect1 examples" id="refsect1-ds-set.get-examples">  <h3 class="title">示例</h3>  <div class="example" id="example-1">   <p><strong>示例 #1 <span 