/**
 * <div id="ds-set.intersect" class="refentry"> <div class="refnamediv">  <h1 class="refname">Ds\Set::intersect</h1>  <p class="verinfo">(PECL ds &gt;= 1.0.0)</p><p class="refpurpose"><span class="refname">Ds\Set::intersect</span> — <span class="dc-title">Creates a new set by intersecting values with another set</span></p> </div> <div class="refsect1 description" id="refsect1-ds-set.intersect-description">  <h3 class="title">说明</h3>  <div class="methodsynopsis dc-description">   <span class="modifier">public</span> <span class="modifier">function</span> <span class="methodname" style="color:#CC7832"><strong>Ds\Set::intersect</strong></span>(<span class="methodparam"><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/class.ds-set.php" class="type Ds\Set" style="color:#EAB766">Ds\Set</a></span> <span class="parameter" style="color:#3A95FF">\$set</span></span>): <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/class.ds-set.php" class="type Ds\Set" style="color:#EAB766">Ds\Set</a></span></div>  <p class="para rdfs-comment">    Creates a new set using values common to both the current instance and another <span class="parameter" style="color:#3A95FF">set</span>.    In other words, returns a copy of the current instance with all values removed that    are not in the other <span class="parameter" style="color:#3A95FF">set</span>.  </p>  <p class="para">    <span class="code">A ∩ B = {x : x ∈ A ∧ x ∈ B}</span>  </p> </div> <div class="refsect1 parameters" id="refsect1-ds-set.intersect-parameters">  <h3 class="title">参数</h3>  <dl>       <dt><span class="parameter" style="color:#3A95FF">set</span></dt>    <dd>     <p class="para">        The other set.     </p>    </dd>     </dl> </div> <div class="refsect1 returnvalues" id="refsect1-ds-set.intersect-returnvalues">  <h3 class="title">返回值</h3>    <p class="para">    The intersection of the current instance and another <span class="parameter" style="color:#3A95FF">set</span>.    </p> </div> <div class="refsect1 seealso" id="refsect1-ds-set.intersect-seealso">  <h3 class="title">参见</h3>  <p class="para">   </p><ul class="simplelist">    <li><a href="https://en.wikipedia.org/wiki/Intersection_(set_theory)" class="link external">»&nbsp;Intersection</a> on Wikipedia</li>   </ul>   </div> <div class="refsect1 examples" id="refsect1-ds-set.intersect-examples">  <h3 class="title">示例</h3>  <div class="example" id="example-1">   <p><strong>示例 #1 <span class="function"><strong style="color:#CC7832">Ds\Set::intersect()</strong></span> example</strong></p>   <div class="example-contents"><div class="phpcode" style="border-color:gray;background:#1E1F22;"><blockquote style="border:1px gray solid;white-space:pre-wrap"><span style="color: #000000"><span style="color: #9876AA">&lt;?php<br>\$a </span><span style="color: #007700">= new </span><span style="color: #9876AA">\Ds\Set</span><span style="color: #007700">([</span><span style="color: #9876AA">1</span><span style="color: #007700">, </span><span style="color: #9876AA">2</span><span style="color: #007700">, </span><span style="color: #9876AA">3</span><span style="color: #007700">]);<br></span><span style="color: #9876AA">\$b </span><span style="color: #007700">= new </span><span style="color: #9876AA">\Ds\Set</span><span style="color: #007700">([</span><span style="color: #9876AA">3</span><span style="color: #007700">, </span><span style="color: #9876AA">4</span><span style="color: #007700">, </span><span style="color: #9876AA">5</span><span style="color: #007700">]);<br><br></span><span style="color: #9876AA">var_dump</span><span style="color: #007700">(</span><span style="color: #9876AA">\$a</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">intersect</span><span style="color: #007700">(</span><span style="color: #9876AA">\$b</span><span style="color: #007700">));<br></span><span style="color: #9876AA">?&gt;</span></span></blockquote></div>   </div>   <div class="example-contents"><p>以上示例的输出类似于：</p></div>   <div class="example-contents screen" style="border-color:gray;background:#1E1F22;"><div class="examplescode"><blockquote style="border:1px gray solid;">object(Ds\Set)#3&nbsp;(1)&nbsp;{<br>&nbsp;&nbsp;[0]=&gt;<br>&nbsp;&nbsp;int(3)<br>}</blockquote></div>   </div>  </div> </div></div>
 */
    public function intersect(Set $set): Set {}

/**
 * <div id="ds-set.isempty" class="refentry"> <div class="refnamediv">  <h1 class="refname">Ds\Set::isEmpty</h1>  <p class="verinfo">(PECL ds &gt;= 1.0.0)</p><p class="refpurpose"><span class="refname">Ds\Set::isEmpty</span> — <span class="dc-title">Returns whether the set is empty</span></p> </div> <div class="refsect1 description" id="refsect1-ds-set.isempty-description">  <h3 class="title">说明</h3>  <div class="methodsynopsis dc-description">   <span class="modifier">public</span> <span class="modifier">function</span> <span class="methodname" style="color:#CC7832"><strong>Ds\Set::isEmpty</strong></span>(): <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.boolean.php" class="type bool" style="color:#EAB766">bool</a></span></div>  <p class="para rdfs-comment">    Returns whether the set is empty.  </p> </div> <div class="refsect1 parameters" id="refsect1-ds-set.isempty-parameters">  <h3 class="title">参数</h3>  <p class="simpara">此函数没有参数。</p> </div> <div class="refsect1 returnvalues" id="refsect1-ds-set.isempty-returnvalues">  <h3 class="title">返回值</h3>  <p class="para">    Returns <strong><span><a href="https://php.net/manual/zh/reserved.constants.php#constant.true">true</a></span></strong> if the set is empty, <strong><span><a href="https://php.net/manual/zh/reserved.constants.php#constant.false">false</a></span></strong> otherwise.  </p> </div> <div class="refsect1 examples" id="refsect1-ds-set.isempty-examples">  <h3 class="title">示例</h3>  <div class="example" id="example-1">   <p><strong>示例 #1 <span class="function"><strong style="color:#CC7832">Ds\Set::isEmpty()</strong></span> example</strong></p>   <div class="example-contents"><div class="phpcode" style="border-color:gray;background:#1E1F22;"><blockquote style="border:1px gray solid;white-space:pre-wrap"><span style="color: #000000"><span style="color: #9876AA">&lt;?php<br>\$a </span><span style="color: #007700">= new </span><span style="color: #9876AA">\Ds\Set</span><span style="color: #007700">([</span><span style="color: #9876AA">1</span><span style="color: #007700">, </span><span style="color: #9876AA">2</span><span style="color: #007700">, </span><span style="color: #9876AA">3</span><span style="color: #007700">]);<br></span><span style="color: #9876AA">\$b </span><span style="color: #007700">= new </span><span style="color: #9876AA">\Ds\Set</span><span style="color: #007700">();<br><br></span><span style="color: #9876AA">var_dump</span><span style="color: #007700">(</span><span style="color: #9876AA">\$a</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">isEmpty</span><span style="color: #007700">());<br></span><span style="color: #9876AA">var_dump</span><span style="color: #007700">(</span><span style="color: #9876AA">\$b</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">isEmpty</span><span style="color: #007700">());<br></span><span style="color: #9876AA">?&gt;</span></span></blockquote></div>   </div>   <div class="example-contents"><p>以上示例的输出类似于：</p></div>   <div class="example-contents screen" style="border-color:gray;background:#1E1F22;"><div class="examplescode"><blockquote style="border:1px gray solid;">bool(false)<br>bool(true)</blockquote></div>   </div>  </div> </div></div>
