/**
 * <div id="ds-set.join" class="refentry"> <div class="refnamediv">  <h1 class="refname">Ds\Set::join</h1>  <p class="verinfo">(PECL ds &gt;= 1.0.0)</p><p class="refpurpose"><span class="refname">Ds\Set::join</span> — <span class="dc-title">Joins all values together as a string</span></p> </div> <div class="refsect1 description" id="refsect1-ds-set.join-description">  <h3 class="title">说明</h3>  <div class="methodsynopsis dc-description">   <span class="modifier">public</span> <span class="modifier">function</span> <span class="methodname" style="color:#CC7832"><strong>Ds\Set::join</strong></span>(<span class="methodparam"><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.string.php" class="type string" style="color:#EAB766">string</a></span> <span class="parameter" style="color:#3A95FF">\$glue</span><span class="initializer"> = ?</span></span>): <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.string.php" class="type string" style="color:#EAB766">string</a></span></div>  <p class="para rdfs-comment">    Joins all values together as a string using an optional separator between each value.  </p> </div> <div class="refsect1 parameters" id="refsect1-ds-set.join-parameters">  <h3 class="title">参数</h3>  <dl>       <dt><span class="parameter" style="color:#3A95FF">glue</span></dt>    <dd>     <p class="para">        An optional string to separate each value.     </p>    </dd>     </dl> </div> <div class="refsect1 returnvalues" id="refsect1-ds-set.join-returnvalues">  <h3 class="title">返回值</h3>  <p class="para">    All values of the set joined together as a string.  </p> </div> <div class="refsect1 examples" id="refsect1-ds-set.join-examples">  <h3 class="title">示例</h3>  <div class="example" id="example-1">   <p><strong>示例 #1 <span class="function"><strong style="color:#CC7832">Ds\Set::join()</strong></span> example using a separator string</strong></p>   <div class="example-contents"><div class="phpcode" style="border-color:gray;background:#1E1F22;"><blockquote style="border:1px gray solid;white-space:pre-wrap"><span style="color: #000000"><span style="color: #9876AA">&lt;?php<br>\$set </span><span style="color: #007700">= new </span><span style="color: #9876AA">\Ds\Set</span><span style="color: #007700">([</span><span style="color: #DD0000">"a"</span><span style="color: #007700">, </span><span style="color: #DD0000">"b"</span><span style="color: #007700">, </span><span style="color: #DD0000">"c"</span><span style="color: #007700">, </span><span style="color: #9876AA">1</span><span style="color: #007700">, </span><span style="color: #9876AA">2</span><span style="color: #007700">, </span><span style="color: #9876AA">3</span><span style="color: #007700">]);<br><br></span><span style="color: #9876AA">var_dump</span><span style="color: #007700">(</span><span style="color: #9876AA">\$set</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">join</span><span style="color: #007700">(</span><span style="color: #DD0000">"|"</span><span style="color: #007700">));<br></span><span style="color: #9876AA">?&gt;</span></span></blockquote></div>   </div>   <div class="example-contents"><p>以上示例的输出类似于：</p></div>   <div class="example-contents screen" style="border-color:gray;background:#1E1F22;"><div class="examplescode"><blockquote style="border:1px gray solid;">string(11)&nbsp;"a|b|c|1|2|3"</blockquote></div>   </div>  </div>  <div class="example" id="example-2"> <p><strong>示例 #2 <span class="function"><strong style="color:#CC7832">Ds\Set::join()</strong></span> example without a separator string</strong></p>   <div class="example-contents"><div class="phpcode" style="border-color:gray;background:#1E1F22;"><blockquote style="border:1px gray solid;white-space:pre-wrap"><span style="color: #000000"><span style="color: #9876AA">&lt;?php<br>\$set </span><span style="color: #007700">= new </span><span style="color: #9876AA">\Ds\Set</span><span style="color: #007700">([</span><span style="color: #DD0000">"a"</span><span style="color: #007700">, </span><span style="color: #DD0000">"b"</span><span style="color: #007700">, </span><span style="color: #DD0000">"c"</span><span style="color: #007700">, </span><span style="color: #9876AA">1</span><span style="color: #007700">, </span><span style="color: #9876AA">2</span><span style="color: #007700">, </span><span style="color: #9876AA">3</span><span style="color: #007700">]);<br><br></span><span style="color: #9876AA">var_dump</span><span style="color: #007700">(</span><span style="color: #9876AA">\$set</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">join</span><span style="color: #007700">());<br></span><span style="color: #9876AA">?&gt;</span></span></blockquote></div>   </div>   <div class="example-contents"><p>以上示例的输出类似于：</p></div>   <div class="example-contents screen" style="border-color:gray;background:#1E1F22;"><div class="examplescode"><blockquote style="border:1px gray solid;">string(11)&nbsp;"abc123"</blockquote></div>   </div>  </div> </div></div>
 */
    public function join(string $glue = ''): string {}

