    public function last() {}

    /**
 * <div id="ds-set.map" class="refentry"> <div class="refnamediv">  <h1 class="refname">Ds\Set::map</h1>  <p class="verinfo">(PECL ds &gt;= 1.2.7)</p><p class="refpurpose"><span class="refname">Ds\Set::map</span> — <span class="dc-title">Returns the result of applying a callback to each value</span></p> </div> <div class="refsect1 description" id="refsect1-ds-set.map-description">  <h3 class="title">说明</h3>  <div class="methodsynopsis dc-description">   <span class="modifier">public</span> <span class="modifier">function</span> <span class="methodname" style="color:#CC7832"><strong>Ds\Set::map</strong></span>(<span class="methodparam"><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.callable.php" class="type callable" style="color:#EAB766">callable</a></span> <span class="parameter" style="color:#3A95FF">\$callback</span></span>): <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/class.ds-set.php" class="type Ds\Set" style="color:#EAB766">Ds\Set</a></span></div>  <p class="para rdfs-comment">   Returns the result of applying a <span class="parameter" style="color:#3A95FF">callback</span> function to   each value in the set.  </p> </div> <div class="refsect1 parameters" id="refsect1-ds-set.map-parameters">  <h3 class="title">参数</h3>  <dl>       <dt><span class="parameter" style="color:#3A95FF">callback</span></dt>    <dd>     <p class="para">      The callback to apply to each value in the set must have the following signature:      </p><div class="methodsynopsis dc-description"><span class="modifier">function</span> <span class="methodname" style="color:#CC7832"><span class="replaceable">callback</span></span>(<span class="methodparam"><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.mixed.php" class="type mixed" style="color:#EAB766">mixed</a></span> <span class="parameter" style="color:#3A95FF">\$value</span></span>): <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.mixed.php" class="type mixed" style="color:#EAB766">mixed</a></span></div>         </dd>     </dl> </div> <div class="refsect1 returnvalues" id="refsect1-ds-set.map-returnvalues">  <h3 class="title">返回值</h3>  <p class="para">   Returns a new <span class="classname"><a href="https://php.net/manual/zh/class.ds-set.php" class="classname">Ds\Set</a></span> instance where each value   is the result of applying the <span class="parameter" style="color:#3A95FF">callback</span> to each value   of the set.  </p> </div> <div class="refsect1 examples" id="refsect1-ds-set.map-examples">  <h3 class="title">示例</h3>  <div class="example" id="example-1">   <p><strong>示例 #1 <span class="methodname" style="color:#CC7832"><strong>Ds\Set::map()</strong></span> example</strong></p>   <div class="example-contents"><div class="phpcode" style="border-color:gray;background:#1E1F22;"><blockquote style="border:1px gray solid;white-space:pre-wrap"><span style="color: #000000"><span style="color: #9876AA">&lt;?php<br>\$set </span><span style="color: #007700">= new </span><span style="color: #9876AA">\Ds\Set</span><span style="color: #007700">([</span><span style="color: #9876AA">1</span><span style="color: #007700">, </span><span style="color: #9876AA">2</span><span style="color: #007700">, </span><span style="color: #9876AA">3</span><span style="color: #007700">]);<br><br></span><span style="color: #9876AA">var_dump</span><span style="color: #007700">(</span><span style="color: #9876AA">\$set</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">map</span><span style="color: #007700">(function(</span><span style="color: #9876AA">\$value</span><span style="color: #007700">) { return </span><span style="color: #9876AA">\$value </span><span style="color: #007700">* </span><span style="color: #9876AA">2</span><span style="color: #007700">; }));<br></span><span style="color: #9876AA">var_dump</span><span style="color: #007700">(</span><span style="color: #9876AA">\$set</span><span style="color: #007700">);<br></span><span style="color: #9876AA">?&gt;</span></span></blockquote></div>   </div>   <div class="example-contents"><p>以上示例的输出类似于：</p></div>   <div class="example-contents screen" style="border-color:gray;background:#1E1F22;"><div class="examplescode"><blockquote style="border:1px gray solid;">object(Ds\Set)#3&nbsp;(3)&nbsp;{<br>&nbsp;&nbsp;[0]=&gt;<br>&nbsp;&nbsp;int(2)<br>&nbsp;&nbsp;[1]=&gt;<br>&nbsp;&nbsp;int(4)<br>&nbsp;&nbsp;[2]=&gt;<br>&nbsp;&nbsp;int(6)<br>}<br>object(Ds\Set)#1&nbsp;(3)&nbsp;{<br>&nbsp;&nbsp;[0]=&gt;<br>&nbsp;&nbsp;int(1)<br>&nbsp;&nbsp;[1]=&gt;<br>&nbsp;&nbsp;int(2)<br>&nbsp;&nbsp;[2]=&gt;<br>&nbsp;&nbsp;int(3)<br>}</blockquote></div>   </div>  </div> </div></div>
 * 
     * @template TReturn
     * @param callable(TValue): TReturn $callback
     * @return Set<TReturn>
     */
    public function map(callable $callback): Set {}

    /**
 * <div id="ds-set.merge" class="refentry"> <div class="refnamediv">  <h1 class="refname">Ds\Set::merge</h1>  <p class="verinfo">(PECL ds &gt;= 1.0.3)</p><p class="refpurpose"><span class="refname">Ds\Set::merge</span> — <span class="dc-title">Returns the result of adding all given values to the set</span></p> </div> <div class="refsect1 description" id="refsect1-ds-set.merge-description">  <h3 class="title">说明</h3>  <div class="methodsynopsis dc-description">   <span class="modifier">public</span> <span class="modifier">function</span> <span class="methodname" style="color:#CC7832"><strong>Ds\Set::merge</strong></span>(<span class="methodparam"><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.mixed.php" class="type mixed" style="color:#EAB766">mixed</a></span> <span class="parameter" style="color:#3A95FF">\$values</span></span>): <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/class.ds-set.php" class="type Ds\Set" style="color:#EAB766">Ds\Set</a></span></div>  <p class="para rdfs-comment">    Returns the result of adding all given values to the set.  </p> </div> <div class="refsect1 parameters" id="refsect1-ds-set.merge-parameters">  <h3 class="title">参数</h3>  <dl>       <dt><span class="parameter" style="color:#3A95FF">values</span></dt>    <dd>     <p class="para">        A <span class="classname"><a href="https://php.net/manual/zh/class.traversable.php" class="classname">traversable</a></span> object or an <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.array.php" class="type array" style="color:#EAB766">array</a></span>.     </p>    </dd>     </dl> </div> <div class="refsect1 returnvalues" id="refsect1-ds-set.merge-returnvalues">  <h3 class="title">返回值</h3>  <p class="para">    The result of adding all given values to the set,    effectively the same as adding the values to a copy, then returning that copy.  </p>  <blockquote class="note" style="border:1px gray solid"><p><strong class="note" style="border:1px gray solid">注意</strong>:     </p><p class="para">        The current instance won't be affected.    </p>  </blockquote> </div> <div class="refsect1 examples" id="refsect1-ds-set.merge-examples">  <h3 class="title">示例</h3>  <div class="example" id="example-1">   <p><strong>示例 #1 <span class="function"><strong style="color:#CC7832">Ds\Set::merge()</strong></span> example</strong></p>   <div class="example-contents"><div class="phpcode" style="border-color:gray;background:#1E1F22;"><blockquote style="border:1px gray solid;white-space:pre-wrap"><span style="color: #000000"><span style="color: #9876AA">&lt;?php<br>\$set </span><span style="color: #007700">= new </span><span style="color: #9876AA">\Ds\Set</span><span style="color: #007700">([</span><span style="color: #9876AA">1</span><span style="color: #007700">, </span><span style="color: #9876AA">2</span><span style="color: #007700">, </span><span style="color: #9876AA">3</span><span style="color: #007700">]);<br><br></span><span style="color: #9876AA">var_dump</span><span style="color: #007700">(</span><span style="color: #9876AA">\$set</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">merge</span><span style="color: #007700">([</span><span style="color: #9876AA">3</span><span style="color: #007700">, </span><span style="color: #9876AA">4</span><span style="color: #007700">, </span><span style="color: #9876AA">5</span><span style="color: #007700">]));<br></span><span style="color: #9876AA">var_dump</span><span style="color: #007700">(</span><span style="color: #9876AA">\$set</span><span style="color: #007700">);<br></span><span style="color: #9876AA">?&gt;</span></span></blockquote></div>   </div>   <div class="example-contents"><p>以上示例的输出类似于：</p></div>   <div class="example-contents screen" style="border-color:gray;background:#1E1F22;"><div class="examplescode"><blockquote style="border:1px gray solid;">object(Ds\Set)#2&nbsp;(6)&nbsp;{<br>&nbsp;&nbsp;[0]=&gt;<br>&nbsp;&nbsp;int(1)<br>&nbsp;&nbsp;[1]=&gt;<br>&nbsp;&nbsp;int(2)<br>&nbsp;&nbsp;[2]=&gt;<br>&nbsp;&nbsp;int(3)<br>&nbsp;&nbsp;[3]=&gt;<br>&nbsp;&nbsp;int(4)<br>&nbsp;&nbsp;[4]=&gt;<br>&nbsp;&nbsp;int(5)<br>}<br>object(Ds\Set)#1&nbsp;(3)&nbsp;{<br>&nbsp;&nbsp;[0]=&gt;<br>&nbsp;&nbsp;int(1)<br>&nbsp;&nbsp;[1]=&gt;<br>&nbsp;&nbsp;int(2)<br>&nbsp;&nbsp;[2]=&gt;<br>&nbsp;&nbsp;int(3)<br>}</blockquote></div>   </div>  </div> </div></div>
 * 
     * @param iterable<TValue> $values
     * @return Set<TValue>
     */
    public function merge($values): Set {}

    /**
 * <div id="ds-set.reduce" class="refentry"> <div class="refnamediv">  <h1 class="refname">Ds\Set::reduce</h1>  <p class="verinfo">(PECL ds &gt;= 1.0.0)</p><p class="refpurpose"><span class="refname">Ds\Set::reduce</span> — <span class="dc-title">Reduces the set to a single value using a callback function</span></p> </div> <div class="refsect1 description" id="refsect1-ds-set.reduce-description">  <h3 class="title">说明</h3>  <div class="methodsynopsis dc-description">   <span class="modifier">public</span> <span class="modifier">function</span> <span class="methodname" style="color:#CC7832"><strong>Ds\Set::reduce</strong></span>(<span class="methodparam"><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.callable.php" class="type callable" style="color:#EAB766">callable</a></span> <span class="parameter" style="color:#3A95FF">\$callback</span></span>, <span class="methodparam"><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.mixed.php" class="type mixed" style="color:#EAB766">mixed</a></span> <span class="parameter" style="color:#3A95FF">\$initial</span><span class="initializer"> = ?</span></span>): <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.mixed.php" class="type mixed" style="color:#EAB766">mixed</a></span></div>  <p class="para rdfs-comment">    Reduces the set to a single value using a callback function.  </p> </div> <div class="refsect1 parameters" id="refsect1-ds-set.reduce-parameters">  <h3 class="title">参数</h3>  <dl>       <dt><span class="parameter" style="color:#3A95FF">callback</span></dt>    <dd>      <div class="methodsynopsis dc-description"><span class="modifier">function</span> <span class="methodname" style="color:#CC7832"><span class="replaceable">callback</span></span>(<span class="methodparam"><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.mixed.php" class="type mixed" style="color:#EAB766">mixed</a></span> <span class="parameter" style="color:#3A95FF">\$carry</span></span>, <span class="methodparam"><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.mixed.php" class="type mixed" style="color:#EAB766">mixed</a></span> <span class="parameter" style="color:#3A95FF">\$value</span></span>): <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.mixed.php" class="type mixed" style="color:#EAB766">mixed</a></span></div>      <dl>               <dt><span class="parameter" style="color:#3A95FF">carry</span></dt>        <dd>         <p class="para">          The return value of the previous callback, or <span class="parameter" style="color:#3A95FF">initial</span> if          it's the first iteration.         </p>        </dd>                      <dt><span class="parameter" style="color:#3A95FF">value</span></dt>        <dd>         <p class="para">          The value of the current iteration.         </p>        </dd>             </dl>     </dd>          <dt><span class="parameter" style="color:#3A95FF">initial</span></dt>    <dd>     <p class="para">        The initial value of the carry value. Can be <strong><span><a href="https://php.net/manual/zh/reserved.constants.php#constant.null">null</a></span></strong>.     </p>    </dd>     </dl> </div> <div class="refsect1 returnvalues" id="refsect1-ds-set.reduce-returnvalues">  <h3 class="title">返回值</h3>  <p class="para">    The return value of the final callback.  </p> </div> <div class="refsect1 examples" id="refsect1-ds-set.reduce-examples">  <h3 class="title">示例</h3>  <div class="example" id="example-1">   <p><strong>示例 #1 <span class="function"><strong style="color:#CC7832">Ds\Set::reduce()</strong></span> with initial value example</strong></p>   <div class="example-contents"><div class="phpcode" style="border-color:gray;background:#1E1F22;"><blockquote style="border:1px gray solid;white-space:pre-wrap"><span style="color: #000000"><span style="color: #9876AA">&lt;?php<br>\$set </span><span style="color: #007700">= new </span><span style="color: #9876AA">\Ds\Set</span><span style="color: #007700">([</span><span style="color: #9876AA">1</span><span style="color: #007700">, </span><span style="color: #9876AA">2</span><span style="color: #007700">, </span><span style="color: #9876AA">3</span><span style="color: #007700">]);<br><br></span><span style="color: #9876AA">\$callback </span><span style="color: #007700">= function(</span><span style="color: #9876AA">\$carry</span><span style="color: #007700">, </span><span style="color: #9876AA">\$value</span><span style="color: #007700">) {<br>    return </span><span style="color: #9876AA">\$carry </span><span style="color: #007700">* </span><span style="color: #9876AA">\$value</span><span style="color: #007700">;<br>};<br><br></span><span style="color: #9876AA">var_dump</span><span style="color: #007700">(</span><span style="color: #9876AA">\$set</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">reduce</span><span style="color: #007700">(</span><span style="color: #9876AA">\$callback</span><span style="color: #007700">, </span><span style="color: #9876AA">5</span><span style="color: #007700">));<br><br></span><span style="color: #FF8000">// Iterations:<br>//<br>// \$carry = \$initial = 5<br>//<br>// \$carry = \$carry * 1 =  5<br>// \$carry = \$carry * 2 = 10<br>// \$carry = \$carry * 3 = 30<br></span><span style="color: #9876AA">?&gt;</span></span></blockquote></div>   </div>   <div class="example-contents"><p>以上示例的输出类似于：</p></div>   <div class="example-contents screen" style="border-color:gray;background:#1E1F22;"><div class="examplescode"><blockquote style="border:1px gray solid;">int(30)</blockquote></div>   </div>  </div>  <div class="example" id="example-2">   <p><strong>示例 #2 <span class="function"><strong style="color:#CC7832">Ds\Set::reduce()</strong></span> without an initial value example</strong></p>   <div class="example-contents"><div class="phpcode" style="border-color:gray;background:#1E1F22;"><blockquote style="border:1px gray solid;white-space:pre-wrap"><span style="color: #000000"><span style="color: #9876AA">&lt;?php<br>\$set </span><span style="color: #007700">= new </span><span style="color: #9876AA">\Ds\Set</span><span style="color: #007700">([</span><span style="color: #9876AA">1</span><span style="color: #007700">, </span><span style="color: #9876AA">2</span><span style="color: #007700">, </span><span style="color: #9876AA">3</span><span style="color: #007700">]);<br><br></span><span style="color: #9876AA">var_dump</span><span style="color: #007700">(</span><span style="color: #9876AA">\$set</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">reduce</span><span style="color: #007700">(function(</span><span style="color: #9876AA">\$carry</span><span style="color: #007700">, </span><span style="color: #9876AA">\$value</span><span style="color: #007700">) {<br>    return </span><span style="color: #9876AA">\$carry </span><span style="color: #007700">+ </span><span style="color: #9876AA">\$value </span><span style="color: #007700">+ </span><span style="color: #9876AA">5</span><span style="color: #007700">;<br>}));<br><br></span><span style="color: #FF8000">// Iterations:<br>//<br>// \$carry = \$initial = null<br>//<br>// \$carry = \$carry + 1 + 5 =  6<br>// \$carry = \$carry + 2 + 5 = 13<br>// \$carry = \$carry + 3 + 5 = 21<br></span><span style="color: #9876AA">?&gt;</span></span></blockquote></div>   </div>   <div class="example-contents"><p>以上示例的输出类似于：</p></div>   <div class="example-contents screen" style="border-color:gray;background:#1E1F22;"><div class="examplescode"><blockquote style="border:1px gray solid;">int(21)</blockquote></div>   </div>  </div> </div></div>
 * 
     * @template TInitial
     * @template TReturn
     * @param callable(TInitial|TReturn|null, TValue): TReturn $callback
     * @param TInitial|null $initial
     * @return TReturn|null
     */
    public function reduce(callable $callback, $initial = null) {}

/**
 * <div id="ds-set.remove" class="refentry"> <div class="refnamediv">  <h1 class="refname">Ds\Set::remove</h1>  <p class="verinfo">(PECL ds &gt;= 1.0.0)</p><p class="refpurpose"><span class="refname">Ds\Set::remove</span> — <span class="dc-title">Removes all given values from the set</span></p> </div> <div class="refsect1 description" id="refsect1-ds-set.remove-description">  <h3 class="title">说明</h3>  <div class="methodsynopsis dc-description">   <span class="modifier">public</span> <span class="modifier">function</span> <span class="methodname" style="color:#CC7832"><strong>Ds\Set::remove</strong></span>(<span class="methodparam"><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.mixed.php" class="type mixed" style="color:#EAB766">mixed</a></span> <span class="parameter" style="color:#3A95FF">...\$values</span></span>): <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.void.php" class="type void" style="color:#EAB766">void</a></span></div>  <p class="para rdfs-comment">    Removes all given <span class="parameter" style="color:#3A95FF">values</span> from the set, ignoring any that are not in the set.  </p> </div> <div class="refsect1 parameters" id="refsect1-ds-set.remove-parameters">  <h3 class="title">参数</h3>  <dl>       <dt><span class="parameter" style="color:#3A95FF">values</span></dt>    <dd>     <p class="para">        The values to remove.     </p>    </dd>     </dl> </div> <div class="refsect1 returnvalues" id="refsect1-ds-set.remove-returnvalues">  <h3 class="title">返回值</h3>  <p class="para">    没有返回值。  </p> </div> <div class="refsect1 examples" id="refsect1-ds-set.remove-examples">  <h3 class="title">示例</h3>  <div class="example" id="example-1">   <p><strong>示例 #1 <span class="function"><strong style="color:#CC7832">Ds\Set::remove()</strong></span> example</strong></p>   <div class="example-contents"><div class="phpcode" style="border-color:gray;background:#1E1F22;"><blockquote style="border:1px gray solid;white-space:pre-wrap"><span style="color: #000000"><span style="color: #9876AA">&lt;?php<br>\$set </span><span style="color: #007700">= new </span><span style="color: #9876AA">\Ds\Set</span><span style="color: #007700">([</span><span style="color: #9876AA">1</span><span style="color: #007700">, </span><span style="color: #9876AA">2</span><span style="color: #007700">, </span><span style="color: #9876AA">3</span><span style="color: #007700">, </span><span style="color: #9876AA">4</span><span style="color: #007700">, </span><span style="color: #9876AA">5</span><span style="color: #007700">]);<br><br></span><span style="color: #9876AA">\$set</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">remove</span><span style="color: #007700">(</span><span style="color: #9876AA">1</span><span style="color: #007700">);            </span><span style="color: #FF8000">// Remove 1<br></span><span style="color: #9876AA">\$set</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">remove</span><span style="color: #007700">(</span><span style="color: #9876AA">1</span><span style="color: #007700">, </span><span style="color: #9876AA">2</span><span style="color: #007700">);         </span><span style="color: #FF8000">// Can't find 1, but remove 2<br></span><span style="color: #9876AA">\$set</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">remove</span><span style="color: #007700">(...[</span><span style="color: #9876AA">3</span><span style="color: #007700">, </span><span style="color: #9876AA">4</span><span style="color: #007700">]);    </span><span style="color: #FF8000">// Remove 3 and 4<br><br></span><span style="color: #9876AA">var_dump</span><span style="color: #007700">(</span><span style="color: #9876AA">\$set</span><span style="color: #007700">);<br></span><span style="color: #9876AA">?&gt;</span></span></blockquote></div>   </div>   <div class="example-contents"><p>以上示例的输出类似于：</p></div>   <div class="example-contents screen" style="border-color:gray;background:#1E1F22;"><div class="examplescode"><blockquote style="border:1px gray solid;">object(Ds\Set)#1&nbsp;(1)&nbsp;{<br>&nbsp;&nbsp;[0]=&gt;<br>&nbsp;&nbsp;int(5)<br>}</blockquote></div>   </div>  </div> </div></div>
 */
    public function remove(...$values): void {}

/**
 * <div id="ds-set.reverse" class="refentry"> <div class="refnamediv">  <h1 class="refname">Ds\Set::reverse</h1>  <p class="verinfo">(PECL ds &gt;= 1.0.0)</p><p class="refpurpose"><span class="refname">Ds\Set::reverse</span> — <span class="dc-title">    Reverses the set in-place  </span></p> </div> <div class="refsect1 description" id="refsect1-ds-set.reverse-description">  <h3 class="title">说明</h3>  <div class="methodsynopsis dc-description">   <span class="modifier">public</span> <span class="modifier">function</span> <span class="methodname" style="color:#CC7832"><strong>Ds\Set::reverse</strong></span>(): <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.void.php" class="type void" style="color:#EAB766">void</a></span></div>  <p class="para rdfs-comment">    Reverses the set in-place.  </p> </div> <div class="refsect1 parameters" id="refsect1-ds-set.reverse-parameters">  <h3 class="title">参数</h3>  <p class="simpara">此函数没有参数。</p> </div> <div class="refsect1 returnvalues" id="refsect1-ds-set.reverse-returnvalues">  <h3 class="title">返回值</h3>  <p class="para">    没有返回值。  </p> </div> <div class="refsect1 examples" id="refsect1-ds-set.reverse-examples">  <h3 class="title">示例</h3>  <div class="example" id="example-1">   <p><strong>示例 #1 <span class="function"><strong style="color:#CC7832">Ds\Set::reverse()</strong></span> example</strong></p>   <div class="example-contents"><div class="phpcode" style="border-color:gray;background:#1E1F22;"><blockquote style="border:1px gray solid;white-space:pre-wrap"><span style="color: #000000"><span style="color: #9876AA">&lt;?php<br>\$set </span><span style="color: #007700">= new </span><span style="color: #9876AA">\Ds\Set</span><span style="color: #007700">([</span><span style="color: #DD0000">"a"</span><span style="color: #007700">, </span><span style="color: #DD0000">"b"</span><span style="color: #007700">, </span><span style="color: #DD0000">"c"</span><span style="color: #007700">]);<br></span><span style="color: #9876AA">\$set</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">reverse</span><span style="color: #007700">();<br><br></span><span style="color: #9876AA">print_r</span><span style="color: #007700">(</span><span style="color: #9876AA">\$set</span><span style="color: #007700">);<br></span><span style="color: #9876AA">?&gt;</span></span></blockquote></div>   </div>   <div class="example-contents"><p>以上示例的输出类似于：</p></div>   <div class="example-contents screen" style="border-color:gray;background:#1E1F22;"><div class="examplescode"><blockquote style="border:1px gray solid;">Ds\Set&nbsp;Object<br>(<br>&nbsp;&nbsp;&nbsp;&nbsp;[0]&nbsp;=&gt;&nbsp;c<br>&nbsp;&nbsp;&nbsp;&nbsp;[1]&nbsp;=&gt;&nbsp;b<br>&nbsp;&nbsp;&nbsp;&nbsp;[2]&nbsp;=&gt;&nbsp;a<br>)</blockquote></div>   </div>  </div> </div></div>
 */
    public function reverse(): void {}

/**
 * <div id="ds-set.reversed" class="refentry"> <div class="refnamediv">  <h1 class="refname">Ds\Set::reversed</h1>  <p class="verinfo">(PECL ds &gt;= 1.0.0)</p><p class="refpurpose"><span class="refname">Ds\Set::reversed</span> — <span class="dc-title">Returns a reversed copy</span></p> </div> <div class="refsect1 description" id="refsect1-ds-set.reversed-description">  <h3 class="title">说明</h3>  <div class="methodsynopsis dc-description">   <span class="modifier">public</span> <span class="modifier">function</span> <span class="methodname" style="color:#CC7832"><strong>Ds\Set::reversed</strong></span>(): <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/class.ds-set.php" class="type Ds\Set" style="color:#EAB766">Ds\Set</a></span></div>  <p class="para rdfs-comment">    Returns a reversed copy of the set.  </p> </div> <div class="refsect1 parameters" id="refsect1-ds-set.reversed-parameters">  <h3 class="title">参数</h3>  <p class="simpara">此函数没有参数。</p> </div> <div class="refsect1 returnvalues" id="refsect1-ds-set.reversed-returnvalues">  <h3 class="title">返回值</h3>  <p class="para">    A reversed copy of the set.    </p><blockquote class="note" style="border:1px gray solid"><p><strong class="note" style="border:1px gray solid">注意</strong>:         </p><p class="para">            The current instance is not affected.        </p>    </blockquote>   </div> <div class="refsect1 examples" id="refsect1-ds-set.reversed-examples">  <h3 class="title">示例</h3>  <div class="example" id="example-1">   <p><strong>示例 #1 <span class="function"><strong style="color:#CC7832">Ds\Set::reversed()</strong></span> example</strong></p>   <div class="example-contents"><div class="phpcode" style="border-color:gray;background:#1E1F22;"><blockquote style="border:1px gray solid;white-space:pre-wrap"><span style="color: #000000"><span style="color: #9876AA">&lt;?php<br>\$set </span><span style="color: #007700">= new </span><span style="color: #9876AA">\Ds\Set</span><span style="color: #007700">([</span><span style="color: #DD0000">"a"</span><span style="color: #007700">, </span><span style="color: #DD0000">"b"</span><span style="color: #007700">, </span><span style="color: #DD0000">"c"</span><span style="color: #007700">]);<br><br></span><span style="color: #9876AA">print_r</span><span style="color: #007700">(</span><span style="color: #9876AA">\$set</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">reversed</span><span style="color: #007700">());<br></span><span style="color: #9876AA">print_r</span><span style="color: #007700">(</span><span style="color: #9876AA">\$set</span><span style="color: #007700">);<br></span><span style="color: #9876AA">?&gt;</span></span></blockquote></div>   </div>   <div class="example-contents"><p>以上示例的输出类似于：</p></div>   <div class="example-contents screen" style="border-color:gray;background:#1E1F22;"><div class="examplescode"><blockquote style="border:1px gray solid;">Ds\Set&nbsp;Object<br>(<br>&nbsp;&nbsp;&nbsp;&nbsp;[0]&nbsp;=&gt;&nbsp;c<br>&nbsp;&nbsp;&nbsp;&nbsp;[1]&nbsp;=&gt;&nbsp;b<br>&nbsp;&nbsp;&nbsp;&nbsp;[2]&nbsp;=&gt;&nbsp;a<br>)<br>Ds\Set&nbsp;Object<br>(<br>&nbsp;&nbsp;&nbsp;&nbsp;[0]&nbsp;=&gt;&nbsp;a<br>&nbsp;&nbsp;&nbsp;&nbsp;[1]&nbsp;=&gt;&nbsp;b<br>&nbsp;&nbsp;&nbsp;&nbsp;[2]&nbsp;=&gt;&nbsp;c<br>)</blockquote></div>   </div>  </div> </div></div>
 */
    public function reversed(): Set {}

/**
 * <div id="ds-set.slice" class="refentry"> <div class="refnamediv">  <h1 class="refname">Ds\Set::slice</h1>  <p class="verinfo">(PECL ds &gt;= 1.0.0)</p><p class="refpurpose"><span class="refname">Ds\Set::slice</span> — <span class="dc-title">   Returns a sub-set of a given range  </span></p> </div> <div class="refsect1 description" id="refsect1-ds-set.slice-description">  <h3 class="title">说明</h3>  <div class="methodsynopsis dc-description">   <span class="modifier">public</span> <span class="modifier">function</span> <span class="methodname" style="color:#CC7832"><strong>Ds\Set::slice</strong></span>(<span class="methodparam"><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.integer.php" class="type int" style="color:#EAB766">int</a></span> <span class="parameter" style="color:#3A95FF">\$index</span></span>, <span class="methodparam"><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.integer.php" class="type int" style="color:#EAB766">int</a></span> <span class="parameter" style="color:#3A95FF">\$length</span><span class="initializer"> = ?</span></span>): <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/class.ds-set.php" class="type Ds\Set" style="color:#EAB766">Ds\Set</a></span></div>  <p class="para rdfs-comment">    Creates a sub-set of a given range.  </p> </div> <div class="refsect1 parameters" id="refsect1-ds-set.slice-parameters">  <h3 class="title">参数</h3>  <dl>       <dt><span class="parameter" style="color:#3A95FF">index</span></dt>    <dd>        <p class="para">            The index at which the sub-set starts.        </p>        <p class="para">            If positive, the set will start at that index in the set.            If negative, the set will start that far from the end.        </p>    </dd>            <dt><span class="parameter" style="color:#3A95FF">length</span></dt>    <dd>     <p class="para">        If a length is given and is positive, the resulting        set will have up to that many values in it.        If the length results in an overflow, only        values up to the end of the set will be included.        If a length is given and is negative, the set        will stop that many values from the end.        If a length is not provided, the resulting set        will contain all values between the index and the        end of the set.     </p>    </dd>     </dl> </div> <div class="refsect1 returnvalues" id="refsect1-ds-set.slice-returnvalues">  <h3 class="title">返回值</h3>  <p class="para">    A sub-set of the given range.  </p> </div> <div class="refsect1 examples" id="refsect1-ds-set.slice-examples">  <h3 class="title">示例</h3>  <div class="example" id="example-1">   <p><strong>示例 #1 <span class="function"><strong style="color:#CC7832">Ds\Set::slice()</strong></span> example</strong></p>   <div class="example-contents"><div class="phpcode" style="border-color:gray;background:#1E1F22;"><blockquote style="border:1px gray solid;white-space:pre-wrap"><span style="color: #000000"><span style="color: #9876AA">&lt;?php<br>\$set </span><span style="color: #007700">= new </span><span style="color: #9876AA">\Ds\Set</span><span style="color: #007700">([</span><span style="color: #DD0000">"a"</span><span style="color: #007700">, </span><span style="color: #DD0000">"b"</span><span style="color: #007700">, </span><span style="color: #DD0000">"c"</span><span style="color: #007700">, </span><span style="color: #DD0000">"d"</span><span style="color: #007700">, </span><span style="color: #DD0000">"e"</span><span style="color: #007700">]);<br><br></span><span style="color: #FF8000">// Slice from 2 onwards<br></span><span style="color: #9876AA">print_r</span><span style="color: #007700">(</span><span style="color: #9876AA">\$set</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">slice</span><span style="color: #007700">(</span><span style="color: #9876AA">2</span><span style="color: #007700">));<br><br></span><span style="color: #FF8000">// Slice from 1, for a length of 3<br></span><span style="color: #9876AA">print_r</span><span style="color: #007700">(</span><span style="color: #9876AA">\$set</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">slice</span><span style="color: #007700">(</span><span style="color: #9876AA">1</span><span style="color: #007700">, </span><span style="color: #9876AA">3</span><span style="color: #007700">));<br><br></span><span style="color: #FF8000">// Slice from 1 onwards<br></span><span style="color: #9876AA">print_r</span><span style="color: #007700">(</span><span style="color: #9876AA">\$set</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">slice</span><span style="color: #007700">(</span><span style="color: #9876AA">1</span><span style="color: #007700">));<br><br></span><span style="color: #FF8000">// Slice from 2 from the end onwards<br></span><span style="color: #9876AA">print_r</span><span style="color: #007700">(</span><span style="color: #9876AA">\$set</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">slice</span><span style="color: #007700">(-</span><span style="color: #9876AA">2</span><span style="color: #007700">));<br><br></span><span style="color: #FF8000">// Slice from 1 to 1 from the end<br></span><span style="color: #9876AA">print_r</span><span style="color: #007700">(</span><span style="color: #9876AA">\$set</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">slice</span><span style="color: #007700">(</span><span style="color: #9876AA">1</span><span style="color: #007700">, -</span><span style="color: #9876AA">1</span><span style="color: #007700">));<br></span><span style="color: #9876AA">?&gt;</span></span></blockquote></div>   </div>   <div class="example-contents"><p>以上示例的输出类似于：</p></div>   <div class="example-contents screen" style="border-color:gray;background:#1E1F22;"><div class="examplescode"><blockquote style="border:1px gray solid;">Ds\Set&nbsp;Object<br>(<br>&nbsp;&nbsp;&nbsp;&nbsp;[0]&nbsp;=&gt;&nbsp;c<br>&nbsp;&nbsp;&nbsp;&nbsp;[1]&nbsp;=&gt;&nbsp;d<br>&nbsp;&nbsp;&nbsp;&nbsp;[2]&nbsp;=&gt;&nbsp;e<br>)<br>Ds\Set&nbsp;Object<br>(<br>&nbsp;&nbsp;&nbsp;&nbsp;[0]&nbsp;=&gt;&nbsp;b<br>&nbsp;&nbsp;&nbsp;&nbsp;[1]&nbsp;=&gt;&nbsp;c<br>&nbsp;&nbsp;&nbsp;&nbsp;[2]&nbsp;=&gt;&nbsp;d<br>)<br>Ds\Set&nbsp;Object<br>(<br>&nbsp;&nbsp;&nbsp;&nbsp;[0]&nbsp;=&gt;&nbsp;b<br>&nbsp;&nbsp;&nbsp;&nbsp;[1]&nbsp;=&gt;&nbsp;c<br>&nbsp;&nbsp;&nbsp;&nbsp;[2]&nbsp;=&gt;&nbsp;d<br>&nbsp;&nbsp;&nbsp;&nbsp;[3]&nbsp;=&gt;&nbsp;e<br>)<br>Ds\Set&nbsp;Object<br>(<br>&nbsp;&nbsp;&nbsp;&nbsp;[0]&nbsp;=&gt;&nbsp;d<br>&nbsp;&nbsp;&nbsp;&nbsp;[1]&nbsp;=&gt;&nbsp;e<br>)<br>Ds\Set&nbsp;Object<br>(<br>&nbsp;&nbsp;&nbsp;&nbsp;[0]&nbsp;=&gt;&nbsp;b<br>&nbsp;&nbsp;&nbsp;&nbsp;[1]&nbsp;=&gt;&nbsp;c<br>&nbsp;&nbsp;&nbsp;&nbsp;[2]&nbsp;=&gt;&nbsp;d<br>)</blockquote></div>   </div>  </div> </div></div>
 */
    public function slice(int $index, ?int $length = null): Set {}

/**
 * <div id="ds-set.sort" class="refentry"> <div class="refnamediv">  <h1 class="refname">Ds\Set::sort</h1>  <p class="verinfo">(PECL ds &gt;= 1.0.0)</p><p class="refpurpose"><span class="refname">Ds\Set::sort</span> — <span class="dc-title">    Sorts the set in-place </span></p> </div> <div class="refsect1 description" id="refsect1-ds-set.sort-description">  <h3 class="title">说明</h3>  <div class="methodsynopsis dc-description">   <span class="modifier">public</span> <span class="modifier">function</span> <span class="methodname" style="color:#CC7832"><strong>Ds\Set::sort</strong></span>(<span class="methodparam"><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.callable.php" class="type callable" style="color:#EAB766">callable</a></span> <span class="parameter" style="color:#3A95FF">\$comparator</span><span class="initializer"> = ?</span></span>): <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.void.php" class="type void" style="color:#EAB766">void</a></span></div>  <p class="para rdfs-comment">    Sorts the set in-place, using an optional <span class="parameter" style="color:#3A95FF">comparator</span> function.  </p> </div> <div class="refsect1 parameters" id="refsect1-ds-set.sort-parameters">  <h3 class="title">参数</h3>  <dl>        <dt><span class="parameter" style="color:#3A95FF">comparator</span></dt>     <dd>      <span class="simpara"> 在第一个参数小于，等于或大于第二个参数时，该比较函数必须相应地返回一个小于，等于或大于 0 的整数。</span><div class="methodsynopsis dc-description"><span class="modifier">function</span> <span class="methodname" style="color:#CC7832"><span class="replaceable">callback</span></span>(<span class="methodparam"><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.mixed.php" class="type mixed" style="color:#EAB766">mixed</a></span> <span class="parameter" style="color:#3A95FF">\$a</span></span>, <span class="methodparam"><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.mixed.php" class="type mixed" style="color:#EAB766">mixed</a></span> <span class="parameter" style="color:#3A95FF">\$b</span></span>): <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.integer.php" class="type int" style="color:#EAB766">int</a></span></div><div class="caution"><strong class="caution">警告</strong> <p class="simpara">  从比较函数中返回<em>非整数</em>值，例如 <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.float.php" class="type float" style="color:#EAB766">float</a></span>，将导致内部强制转换为 callback 返回值为  <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.integer.php" class="type int" style="color:#EAB766">int</a></span>。因此，诸如 <span class="literal">0.99</span> 和 <span class="literal">0.1</span> 之类的值都将被转换为整数值  <span class="literal">0</span>，将这些值比较的话将会是相等。 </p></div>     </dd>      </dl> </div> <div class="refsect1 returnvalues" id="refsect1-ds-set.sort-returnvalues">  <h3 class="title">返回值</h3>  <p class="para">    没有返回值。  </p> </div> <div class="refsect1 examples" id="refsect1-ds-set.sort-examples">  <h3 class="title">示例</h3>  <div class="example" id="example-1">   <p><strong>示例 #1 <span class="function"><strong style="color:#CC7832">Ds\Set::sort()</strong></span> example</strong></p>   <div class="example-contents"><div class="phpcode" style="border-color:gray;background:#1E1F22;"><blockquote style="border:1px gray solid;white-space:pre-wrap"><span style="color: #000000"><span style="color: #9876AA">&lt;?php<br>\$set </span><span style="color: #007700">= new </span><span style="color: #9876AA">\Ds\Set</span><span style="color: #007700">([</span><span style="color: #9876AA">4</span><span style="color: #007700">, </span><span style="color: #9876AA">5</span><span style="color: #007700">, </span><span style="color: #9876AA">1</span><span style="color: #007700">, </span><span style="color: #9876AA">3</span><span style="color: #007700">, </span><span style="color: #9876AA">2</span><span style="color: #007700">]);<br></span><span style="color: #9876AA">\$set</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">sort</span><span style="color: #007700">();<br><br></span><span style="color: #9876AA">print_r</span><span style="color: #007700">(</span><span style="color: #9876AA">\$set</span><span style="color: #007700">);<br></span><span style="color: #9876AA">?&gt;</span></span></blockquote></div>   </div>   <div class="example-contents"><p>以上示例的输出类似于：</p></div>   <div class="example-contents screen" style="border-color:gray;background:#1E1F22;"><div class="examplescode"><blockquote style="border:1px gray solid;">Ds\Set&nbsp;Object<br>(<br>&nbsp;&nbsp;&nbsp;&nbsp;[0]&nbsp;=&gt;&nbsp;1<br>&nbsp;&nbsp;&nbsp;&nbsp;[1]&nbsp;=&gt;&nbsp;2<br>&nbsp;&nbsp;&nbsp;&nbsp;[2]&nbsp;=&gt;&nbsp;3<br>&nbsp;&nbsp;&nbsp;&nbsp;[3]&nbsp;=&gt;&nbsp;4<br>&nbsp;&nbsp;&nbsp;&nbsp;[4]&nbsp;=&gt;&nbsp;5<br>)</blockquote></div>   </div>  </div>  <div class="example" id="example-2">   <p><strong>示例 #2 <span class="function"><strong style="color:#CC7832">Ds\Set::sort()</strong></span> example using a comparator</strong></p>   <div class="example-contents"><div class="phpcode" style="border-color:gray;background:#1E1F22;"><blockquote style="border:1px gray solid;white-space:pre-wrap"><span style="color: #000000"><span style="color: #9876AA">&lt;?php<br>\$set </span><span style="color: #007700">= new </span><span style="color: #9876AA">\Ds\Set</span><span style="color: #007700">([</span><span style="color: #9876AA">4</span><span style="color: #007700">, </span><span style="color: #9876AA">5</span><span style="color: #007700">, </span><span style="color: #9876AA">1</span><span style="color: #007700">, </span><span style="color: #9876AA">3</span><span style="color: #007700">, </span><span style="color: #9876AA">2</span><span style="color: #007700">]);<br><br></span><span style="color: #9876AA">\$set</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">sort</span><span style="color: #007700">(function(</span><span style="color: #9876AA">\$a</span><span style="color: #007700">, </span><span style="color: #9876AA">\$b</span><span style="color: #007700">) {<br>    return </span><span style="color: #9876AA">\$b </span><span style="color: #007700">&lt;=&gt; </span><span style="color: #9876AA">\$a</span><span style="color: #007700">;<br>});<br><br></span><span style="color: #9876AA">print_r</span><span style="color: #007700">(</span><span style="color: #9876AA">\$set</span><span style="color: #007700">);<br></span><span style="color: #9876AA">?&gt;</span></span></blockquote></div>   </div>   <div class="example-contents"><p>以上示例的输出类似于：</p></div>   <div class="example-contents screen" style="border-color:gray;background:#1E1F22;"><div class="examplescode"><blockquote style="border:1px gray solid;">Ds\Set&nbsp;Object<br>(<br>&nbsp;&nbsp;&nbsp;&nbsp;[0]&nbsp;=&gt;&nbsp;5<br>&nbsp;&nbsp;&nbsp;&nbsp;[1]&nbsp;=&gt;&nbsp;4<br>&nbsp;&nbsp;&nbsp;&nbsp;[2]&nbsp;=&gt;&nbsp;3<br>&nbsp;&nbsp;&nbsp;&nbsp;[3]&nbsp;=&gt;&nbsp;2<br>&nbsp;&nbsp;&nbsp;&nbsp;[4]&nbsp;=&gt;&nbsp;1<br>)</blockquote></div>   </div>  </div> </div></div>
 */
    public function sort(?callable $comparator = null): void {}

    /**
 * <div id="ds-set.sorted" class="refentry"> <div class="refnamediv">  <h1 class="refname">Ds\Set::sorted</h1>  <p class="verinfo">(PECL ds &gt;= 1.0.0)</p><p class="refpurpose"><span class="refname">Ds\Set::sorted</span> — <span class="dc-title">Returns a sorted copy</span></p> </div> <div class="refsect1 description" id="refsect1-ds-set.sorted-description">  <h3 class="title">说明</h3>  <div class="methodsynopsis dc-description">   <span class="modifier">public</span> <span class="modifier">function</span> <span class="methodname" style="color:#CC7832"><strong>Ds\Set::sorted</strong></span>(<span class="methodparam"><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.callable.php" class="type callable" style="color:#EAB766">callable</a></span> <span class="parameter" style="color:#3A95FF">\$comparator</span><span class="initializer"> = ?</span></span>): <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/class.ds-set.php" class="type Ds\Set" style="color:#EAB766">Ds\Set</a></span></div>  <p class="para rdfs-comment">    Returns a sorted copy, using an optional <span class="parameter" style="color:#3A95FF">comparator</span> function.  </p> </div> <div class="refsect1 parameters" id="refsect1-ds-set.sorted-parameters">  <h3 class="title">参数</h3>  <dl>        <dt><span class="parameter" style="color:#3A95FF">comparator</span></dt>     <dd>      <span class="simpara"> 在第一个参数小于，等于或大于第二个参数时，该比较函数必须相应地返回一个小于，等于或大于 0 的整数。</span><div class="methodsynopsis dc-description"><span class="modifier">function</span> <span class="methodname" style="color:#CC7832"><span class="replaceable">callback</span></span>(<span class="methodparam"><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.mixed.php" class="type mixed" style="color:#EAB766">mixed</a></span> <span class="parameter" style="color:#3A95FF">\$a</span></span>, <span class="methodparam"><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.mixed.php" class="type mixed" style="color:#EAB766">mixed</a></span> <span class="parameter" style="color:#3A95FF">\$b</span></span>): <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.integer.php" class="type int" style="color:#EAB766">int</a></span></div><div class="caution"><strong class="caution">警告</strong> <p class="simpara">  从比较函数中返回<em>非整数</em>值，例如 <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.float.php" class="type float" style="color:#EAB766">float</a></span>，将导致内部强制转换为 callback 返回值为  <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.integer.php" class="type int" style="color:#EAB766">int</a></span>。因此，诸如 <span class="literal">0.99</span> 和 <span class="literal">0.1</span> 之类的值都将被转换为整数值  <span class="literal">0</span>，将这些值比较的话将会是相等。 </p></div>     </dd>      </dl> </div> <div class="refsect1 returnvalues" id="refsect1-ds-set.sorted-returnvalues">  <h3 class="title">返回值</h3>  <p class="para">    Returns a sorted copy of the set.  </p> </div> <div class="refsect1 examples" id="refsect1-ds-set.sorted-examples">  <h3 class="title">示例</h3>  <div class="example" id="example-1">   <p><strong>示例 #1 <span class="function"><strong style="color:#CC7832">Ds\Set::sorted()</strong></span> example</strong></p>   <div class="example-contents"><div class="phpcode" style="border-color:gray;background:#1E1F22;"><blockquote style="border:1px gray solid;white-space:pre-wrap"><span style="color: #000000"><span style="color: #9876AA">&lt;?php<br>\$set </span><span style="color: #007700">= new </span><span style="color: #9876AA">\Ds\Set</span><span style="color: #007700">([</span><span style="color: #9876AA">4</span><span style="color: #007700">, </span><span style="color: #9876AA">5</span><span style="color: #007700">, </span><span style="color: #9876AA">1</span><span style="color: #007700">, </span><span style="color: #9876AA">3</span><span style="color: #007700">, </span><span style="color: #9876AA">2</span><span style="color: #007700">]);<br><br></span><span style="color: #9876AA">print_r</span><span style="color: #007700">(</span><span style="color: #9876AA">\$set</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">sorted</span><span style="color: #007700">());<br></span><span style="color: #9876AA">?&gt;</span></span></blockquote></div>   </div>   <div class="example-contents"><p>以上示例的输出类似于：</p></div>   <div class="example-contents screen" style="border-color:gray;background:#1E1F22;"><div class="examplescode"><blockquote style="border:1px gray solid;">Ds\Set&nbsp;Object<br>(<br>&nbsp;&nbsp;&nbsp;&nbsp;[0]&nbsp;=&gt;&nbsp;1<br>&nbsp;&nbsp;&nbsp;&nbsp;[1]&nbsp;=&gt;&nbsp;2<br>&nbsp;&nbsp;&nbsp;&nbsp;[2]&nbsp;=&gt;&nbsp;3<br>&nbsp;&nbsp;&nbsp;&nbsp;[3]&nbsp;=&gt;&nbsp;4<br>&nbsp;&nbsp;&nbsp;&nbsp;[4]&nbsp;=&gt;&nbsp;5<br>)</blockquote></div>   </div>  </div>  <div class="example" id="example-2">   <p><strong>示例 #2 <span class="function"><strong style="color:#CC7832">Ds\Set::sorted()</strong></span> example using a comparator</strong></p>   <div class="example-contents"><div class="phpcode" style="border-color:gray;background:#1E1F22;"><blockquote style="border:1px gray solid;white-space:pre-wrap"><span style="color: #000000"><span style="color: #9876AA">&lt;?php<br>\$set </span><span style="color: #007700">= new </span><span style="color: #9876AA">\Ds\Set</span><span style="color: #007700">([</span><span style="color: #9876AA">4</span><span style="color: #007700">, </span><span style="color: #9876AA">5</span><span style="color: #007700">, </span><span style="color: #9876AA">1</span><span style="color: #007700">, </span><span style="color: #9876AA">3</span><span style="color: #007700">, </span><span style="color: #9876AA">2</span><span style="color: #007700">]);<br><br></span><span style="color: #9876AA">\$sorted </span><span style="color: #007700">= </span><span style="color: #9876AA">\$set</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">sorted</span><span style="color: #007700">(function(</span><span style="color: #9876AA">\$a</span><span style="color: #007700">, </span><span style="color: #9876AA">\$b</span><span style="color: #007700">) {<br>    return </span><span style="color: #9876AA">\$b </span><span style="color: #007700">&lt;=&gt; </span><span style="color: #9876AA">\$a</span><span style="color: #007700">;<br>});<br><br></span><span style="color: #9876AA">print_r</span><span style="color: #007700">(</span><span style="color: #9876AA">\$sorted</span><span style="color: #007700">);<br></span><span style="color: #9876AA">?&gt;</span></span></blockquote></div>   </div>   <div class="example-contents"><p>以上示例的输出类似于：</p></div>   <div class="example-contents screen" style="border-color:gray;background:#1E1F22;"><div class="examplescode"><blockquote style="border:1px gray solid;">Ds\Set&nbsp;Object<br>(<br>&nbsp;&nbsp;&nbsp;&nbsp;[0]&nbsp;=&gt;&nbsp;5<br>&nbsp;&nbsp;&nbsp;&nbsp;[1]&nbsp;=&gt;&nbsp;4<br>&nbsp;&nbsp;&nbsp;&nbsp;[2]&nbsp;=&gt;&nbsp;3<br>&nbsp;&nbsp;&nbsp;&nbsp;[3]&nbsp;=&gt;&nbsp;2<br>&nbsp;&nbsp;&nbsp;&nbsp;[4]&nbsp;=&gt;&nbsp;1<br>)</blockquote></div>   </div>  </div> </div></div>
 * 
     * @param null|callable(TValue, TValue): int $comparator
     * @return Set<TValue>
     */
    public function sorted(?callable $comparator = null): Set {}

/**
 * <div id="ds-set.sum" class="refentry"> <div class="refnamediv">  <h1 class="refname">Ds\Set::sum</h1>  <p class="verinfo">(PECL ds &gt;= 1.0.0)</p><p class="refpurpose"><span class="refname">Ds\Set::sum</span> — <span class="dc-title">Returns the sum of all values in the set</span></p> </div> <div class="refsect1 description" id="refsect1-ds-set.sum-description">  <h3 class="title">说明</h3>  <div class="methodsynopsis dc-description">   <span class="modifier">public</span> <span class="modifier">function</span> <span class="methodname" style="color:#CC7832"><strong>Ds\Set::sum</strong></span>(): <span class="type" style="color:#EAB766"><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.integer.php" class="type int" style="color:#EAB766">int</a></span>|<span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.float.php" class="type float" style="color:#EAB766">float</a></span></span></div>  <p class="para rdfs-comment">    Returns the sum of all values in the set.  </p>  <blockquote class="note" style="border:1px gray solid"><p><strong class="note" style="border:1px gray solid">注意</strong>:     </p><p class="para">        Arrays and objects are considered equal to zero when calculating the sum.    </p>  </blockquote> </div> <div class="refsect1 parameters" id="refsect1-ds-set.sum-parameters">  <h3 class="title">参数</h3>  <p class="simpara">此函数没有参数。</p> </div> <div class="refsect1 returnvalues" id="refsect1-ds-set.sum-returnvalues">  <h3 class="title">返回值</h3>  <p class="para">    The sum of all the values in the set as either a <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.float.php" class="type float" style="color:#EAB766">float</a></span> or <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.integer.php" class="type int" style="color:#EAB766">int</a></span>    depending on the values in the set.  </p> </div> <div class="refsect1 examples" id="refsect1-ds-set.sum-examples">  <h3 class="title">示例</h3>  <div class="example" id="example-1">   <p><strong>示例 #1 <span class="function"><strong style="color:#CC7832">Ds\Set::sum()</strong></span> integer example</strong></p>   <div class="example-contents"><div class="phpcode" style="border-color:gray;background:#1E1F22;"><blockquote style="border:1px gray solid;white-space:pre-wrap"><span style="color: #000000"><span style="color: #9876AA">&lt;?php<br>\$set </span><span style="color: #007700">= new </span><span style="color: #9876AA">\Ds\Set</span><span style="color: #007700">([</span><span style="color: #9876AA">1</span><span style="color: #007700">, </span><span style="color: #9876AA">2</span><span style="color: #007700">, </span><span style="color: #9876AA">3</span><span style="color: #007700">]);<br></span><span style="color: #9876AA">var_dump</span><span style="color: #007700">(</span><span style="color: #9876AA">\$set</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">sum</span><span style="color: #007700">());<br></span><span style="color: #9876AA">?&gt;</span></span></blockquote></div>   </div>   <div class="example-contents"><p>以上示例的输出类似于：</p></div>   <div class="example-contents screen" style="border-color:gray;background:#1E1F22;"><div class="examplescode"><blockquote style="border:1px gray solid;">int(6)</blockquote></div>   </div>  </div>  <div class="example" id="example-2">   <p><strong>示例 #2 <span class="function"><strong style="color:#CC7832">Ds\Set::sum()</strong></span> float example</strong></p>   <div class="example-contents"><div class="phpcode" style="border-color:gray;background:#1E1F22;"><blockquote style="border:1px gray solid;white-space:pre-wrap"><span style="color: #000000"><span style="color: #9876AA">&lt;?php<br>\$set </span><span style="color: #007700">= new </span><span style="color: #9876AA">\Ds\Set</span><span style="color: #007700">([</span><span style="color: #9876AA">1</span><span style="color: #007700">, </span><span style="color: #9876AA">2.5</span><span style="color: #007700">, </span><span style="color: #9876AA">3</span><span style="color: #007700">]);<br></span><span style="color: #9876AA">var_dump</span><span style="color: #007700">(</span><span style="color: #9876AA">\$set</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">sum</span><span style="color: #007700">());<br></span><span style="color: #9876AA">?&gt;</span></span></blockquote></div>   </div>   <div class="example-contents"><p>以上示例的输出类似于：</p></div>   <div class="example-contents screen" style="border-color:gray;background:#1E1F22;"><div class="examplescode"><blockquote style="border:1px gray solid;">float(6.5)</blockquote></div>   </div>  </div> </div></div>
 */
    public function sum() {}

/**
 * <div id="ds-set.toarray" class="refentry"> <div class="refnamediv">  <h1 class="refname">Ds\Set::toArray</h1>  <p class="verinfo">(PECL ds &gt;= 1.0.0)</p><p class="refpurpose"><span class="refname">Ds\Set::toArray</span> — <span class="dc-title">    Converts the set to an <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.array.php" class="type array" style="color:#EAB766">array</a></span>  </span></p> </div> <div class="refsect1 description" id="refsect1-ds-set.toarray-description">  <h3 class="title">说明</h3>  <div class="methodsynopsis dc-description"><span class="modifier">public</span> <span class="modifier">function</span> <span class="methodname" style="color:#CC7832"><strong>Ds\Set::toArray</strong></span>(): <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.array.php" class="type array" style="color:#EAB766">array</a></span></div>  <p class="para rdfs-comment">    Converts the set to an <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.array.php" class="type array" style="color:#EAB766">array</a></span>.  </p>  <blockquote class="note" style="border:1px gray solid"><p><strong class="note" style="border:1px gray solid">注意</strong>:     </p><p class="para">        Casting to an <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.array.php" class="type array" style="color:#EAB766">array</a></span> is not supported yet.    </p>  </blockquote> </div> <div class="refsect1 parameters" id="refsect1-ds-set.toarray-parameters">  <h3 class="title">参数</h3>  <p class="simpara">此函数没有参数。</p> </div> <div class="refsect1 returnvalues" id="refsect1-ds-set.toarray-returnvalues">  <h3 class="title">返回值</h3>  <p class="para">    An <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.array.php" class="type array" style="color:#EAB766">array</a></span> containing all the values in the same order as the set.  </p> </div> <div class="refsect1 examples" id="refsect1-ds-set.toarray-examples">  <h3 class="title">示例</h3>  <div class="example" id="example-1">   <p><strong>示例 #1 <span class="function"><strong style="color:#CC7832">Ds\Set::toArray()</strong></span> example</strong></p>   <div class="example-contents"><div class="phpcode" style="border-color:gray;background:#1E1F22;"><blockquote style="border:1px gray solid;white-space:pre-wrap"><span style="color: #000000"><span style="color: #9876AA">&lt;?php<br>\$set </span><span style="color: #007700">= new </span><span style="color: #9876AA">\Ds\Set</span><span style="color: #007700">([</span><span style="color: #9876AA">1</span><span style="color: #007700">, </span><span style="color: #9876AA">2</span><span style="color: #007700">, </span><span style="color: #9876AA">3</span><span style="color: #007700">]);<br><br></span><span style="color: #9876AA">var_dump</span><span style="color: #007700">(</span><span style="color: #9876AA">\$set</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">toArray</span><span style="color: #007700">());<br></span><span style="color: #9876AA">?&gt;</span></span></blockquote></div>   </div>   <div class="example-contents"><p>以上示例的输出类似于：</p></div>   <div class="example-contents screen" style="border-color:gray;background:#1E1F22;"><div class="examplescode"><blockquote style="border:1px gray solid;">array(3)&nbsp;{<br>&nbsp;&nbsp;[0]=&gt;<br>&nbsp;&nbsp;int(1)<br>&nbsp;&nbsp;[1]=&gt;<br>&nbsp;&nbsp;int(2)<br>&nbsp;&nbsp;[2]=&gt;<br>&nbsp;&nbsp;int(3)<br>}</blockquote></div>   </div>  </div> </div></div>
 */
    public function toArray(): array {}

/**
 * <div id="ds-set.union" class="refentry"> <div class="refnamediv">  <h1 class="refname">Ds\Set::union</h1>  <p class="verinfo">(PECL ds &gt;= 1.0.0)</p><p class="refpurpose"><span class="refname">Ds\Set::union</span> — <span class="dc-title">Creates a new set using values from the current instance and another set</span></p> </div> <div class="refsect1 description" id="refsect1-ds-set.union-description">  <h3 class="title">说明</h3>  <div class="methodsynopsis dc-description">   <span class="modifier">public</span> <span class="modifier">function</span> <span class="methodname" style="color:#CC7832"><strong>Ds\Set::union</strong></span>(<span class="methodparam"><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/class.ds-set.php" class="type Ds\Set" style="color:#EAB766">Ds\Set</a></span> <span class="parameter" style="color:#3A95FF">\$set</span></span>): <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/class.ds-set.php" class="type Ds\Set" style="color:#EAB766">Ds\Set</a></span></div>  <p class="para rdfs-comment">    Creates a new set that contains the values of the current instance as well as the    values of another <span class="parameter" style="color:#3A95FF">set</span>.  </p>  <p class="para">    <span class="code">A ∪ B = {x: x ∈ A ∨ x ∈ B}</span>  </p> </div> <div class="refsect1 parameters" id="refsect1-ds-set.union-parameters">  <h3 class="title">参数</h3>  <dl>       <dt><span class="parameter" style="color:#3A95FF">set</span></dt>    <dd>     <p class="para">        The other set, to combine with the current instance.     </p>    </dd>     </dl> </div> <div class="refsect1 returnvalues" id="refsect1-ds-set.union-returnvalues">  <h3 class="title">返回值</h3>    <p class="para">    A new set containing all the values of the current instance as well as another <span class="parameter" style="color:#3A95FF">set</span>.    </p> </div> <div class="refsect1 seealso" id="refsect1-ds-set.union-seealso">  <h3 class="title">参见</h3>  <p class="para">   </p><ul class="simplelist">    <li><a href="https://en.wikipedia.org/wiki/Union_(set_theory)" class="link external">»&nbsp;Union</a> on Wikipedia</li>   </ul>   </div> <div class="refsect1 examples" id="refsect1-ds-set.union-examples">  <h3 class="title">示例</h3>  <div class="example" id="example-1">   <p><strong>示例 #1 <span class="function"><strong style="color:#CC7832">Ds\Set::union()</strong></span> example</strong></p>   <div class="example-contents"><div class="phpcode" style="border-color:gray;background:#1E1F22;"><blockquote style="border:1px gray solid;white-space:pre-wrap"><span style="color: #000000"><span style="color: #9876AA">&lt;?php<br>\$a </span><span style="color: #007700">= new </span><span style="color: #9876AA">\Ds\Set</span><span style="color: #007700">([</span><span style="color: #9876AA">1</span><span style="color: #007700">, </span><span style="color: #9876AA">2</span><span style="color: #007700">, </span><span style="color: #9876AA">3</span><span style="color: #007700">]);<br></span><span style="color: #9876AA">\$b </span><span style="color: #007700">= new </span><span style="color: #9876AA">\Ds\Set</span><span style="color: #007700">([</span><span style="color: #9876AA">3</span><span style="color: #007700">, </span><span style="color: #9876AA">4</span><span style="color: #007700">, </span><span style="color: #9876AA">5</span><span style="color: #007700">]);<br><br></span><span style="color: #9876AA">var_dump</span><span style="color: #007700">(</span><span style="color: #9876AA">\$a</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">union</span><span style="color: #007700">(</span><span style="color: #9876AA">\$b</span><span style="color: #007700">));<br></span><span style="color: #9876AA">?&gt;</span></span></blockquote></div>   </div>   <div class="example-contents"><p>以上示例的输出类似于：</p></div>   <div class="example-contents screen" style="border-color:gray;background:#1E1F22;"><div class="examplescode"><blockquote style="border:1px gray solid;">object(Ds\Set)#3&nbsp;(5)&nbsp;{<br>&nbsp;&nbsp;[0]=&gt;<br>&nbsp;&nbsp;int(1)<br>&nbsp;&nbsp;[1]=&gt;<br>&nbsp;&nbsp;int(2)<br>&nbsp;&nbsp;[2]=&gt;<br>&nbsp;&nbsp;int(3)<br>&nbsp;&nbsp;[3]=&gt;<br>&nbsp;&nbsp;int(4)<br>&nbsp;&nbsp;[4]=&gt;<br>&nbsp;&nbsp;int(5)<br>}</blockquote></div>   </div>  </div> </div></div>
 */
    public function union(Set $set): Set {}

/**
 * <div id="ds-set.xor" class="refentry"> <div class="refnamediv">  <h1 class="refname">Ds\Set::xor</h1>  <p class="verinfo">(PECL ds &gt;= 1.0.0)</p><p class="refpurpose"><span class="refname">Ds\Set::xor</span> — <span class="dc-title">Creates a new set using values in either the current instance or in another set, but not in both</span></p> </div> <div class="refsect1 description" id="refsect1-ds-set.xor-description">  <h3 class="title">说明</h3>  <div class="methodsynopsis dc-description">   <span class="modifier">public</span> <span class="modifier">function</span> <span class="methodname" style="color:#CC7832"><strong>Ds\Set::xor</strong></span>(<span class="methodparam"><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/class.ds-set.php" class="type Ds\Set" style="color:#EAB766">Ds\Set</a></span> <span class="parameter" style="color:#3A95FF">\$set</span></span>): <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/class.ds-set.php" class="type Ds\Set" style="color:#EAB766">Ds\Set</a></span></div>  <p class="para rdfs-comment">    Creates a new set containing values in the current instance as well as another <span class="parameter" style="color:#3A95FF">set</span>,    but not in both.  </p>  <p class="para">    <span class="code">A ⊖ B = {x : x ∈ (A \ B) ∪ (B \ A)}</span>  </p> </div> <div class="refsect1 parameters" id="refsect1-ds-set.xor-parameters">  <h3 class="title">参数</h3>  <dl>       <dt><span class="parameter" style="color:#3A95FF">set</span></dt>    <dd>     <p class="para">        The other set.     </p>    </dd>     </dl> </div> <div class="refsect1 returnvalues" id="refsect1-ds-set.xor-returnvalues">  <h3 class="title">返回值</h3>    <p class="para">        A new set containing values in the current instance as well as another <span class="parameter" style="color:#3A95FF">set</span>,        but not in both.    </p> </div> <div class="refsect1 seealso" id="refsect1-ds-set.xor-seealso">  <h3 class="title">参见</h3>  <p class="para">   </p><ul class="simplelist">    <li><a href="https://en.wikipedia.org/wiki/Symmetric_difference" class="link external">»&nbsp;Symmetric Difference</a> on Wikipedia</li>   </ul>   </div> <div class="refsect1 examples" id="refsect1-ds-set.xor-examples">  <h3 class="title">示例</h3>  <div class="example" id="example-1">   <p><strong>示例 #1 <span class="function"><strong style="color:#CC7832">Ds\Set::xor()</strong></span> example</strong></p>   <div class="example-contents"><div class="phpcode" style="border-color:gray;background:#1E1F22;"><blockquote style="border:1px gray solid;white-space:pre-wrap"><span style="color: #000000"><span style="color: #9876AA">&lt;?php<br>\$a </span><span style="color: #007700">= new </span><span style="color: #9876AA">\Ds\Set</span><span style="color: #007700">([</span><span style="color: #9876AA">1</span><span style="color: #007700">, </span><span style="color: #9876AA">2</span><span style="color: #007700">, </span><span style="color: #9876AA">3</span><span style="color: #007700">]);<br></span><span style="color: #9876AA">\$b </span><span style="color: #007700">= new </span><span style="color: #9876AA">\Ds\Set</span><span style="color: #007700">([</span><span style="color: #9876AA">3</span><span style="color: #007700">, </span><span style="color: #9876AA">4</span><span style="color: #007700">, </span><span style="color: #9876AA">5</span><span style="color: #007700">]);<br><br></span><span style="color: #9876AA">var_dump</span><span style="color: #007700">(</span><span style="color: #9876AA">\$a</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">xor</span><span style="color: #007700">(</span><span style="color: #9876AA">\$b</span><span style="color: #007700">));<br></span><span style="color: #9876AA">?&gt;</span></span></blockquote></div>   </div>   <div class="example-contents"><p>以上示例的输出类似于：</p></div>   <div class="example-contents screen" style="border-color:gray;background:#1E1F22;"><div class="examplescode"><blockquote style="border:1px gray solid;">object(Ds\Set)#3&nbsp;(4)&nbsp;{<br>&nbsp;&nbsp;[0]=&gt;<br>&nbsp;&nbsp;int(1)<br>&nbsp;&nbsp;[1]=&gt;<br>&nbsp;&nbsp;int(2)<br>&nbsp;&nbsp;[2]=&gt;<br>&nbsp;&nbsp;int(4)<br>&nbsp;&nbsp;[3]=&gt;<br>&nbsp;&nbsp;int(5)<br>}</blockquote></div>   </div>  </div> </div></div>
 */
